/**
 * Almacenamiento de contraseñas (HU-01-01 RN-5 / RNE-2).
 *
 * Se usa **scrypt** con parámetros de coste `N = 2^15`, `r = 8`, `p = 1` (uno de los tres
 * algoritmos admitidos por RN-5, junto con Argon2id y bcrypt), sal única de 16 bytes por
 * cuenta generada con el CSPRNG del sistema y clave derivada de 32 bytes.
 * Está prohibido —y no se usa— MD5/SHA-1/SHA-2 directos como mecanismo de almacenamiento.
 *
 * La verificación es de **tiempo constante** respecto del contenido del hash
 * (`timingSafeEqual`) y el módulo expone `dummyVerify` para ejecutar un KDF de coste
 * equivalente cuando el email no existe (HU-01-02 RN-12, anti timing attack).
 */
import { randomBytes, scrypt, timingSafeEqual } from 'node:crypto';

export const SCRYPT_N = 32768; // 2^15
export const SCRYPT_R = 8;
export const SCRYPT_P = 1;
export const SCRYPT_KEYLEN = 32;
const SALT_BYTES = 16;
// 128 * N * r = 32 MiB de memoria; se deja margen porque Node contabiliza algo más.
const MAXMEM = 128 * SCRYPT_N * SCRYPT_R * 2;

function scryptAsync(password: string, salt: Buffer): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    scrypt(
      Buffer.from(password, 'utf8'),
      salt,
      SCRYPT_KEYLEN,
      { N: SCRYPT_N, r: SCRYPT_R, p: SCRYPT_P, maxmem: MAXMEM },
      (err, derivedKey) => (err ? reject(err) : resolve(derivedKey as Buffer)),
    );
  });
}

/** Formato persistido: `scrypt$N$r$p$<salt b64>$<hash b64>`. Nunca se expone por la API. */
export async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(SALT_BYTES);
  const derived = await scryptAsync(password, salt);
  return `scrypt$${SCRYPT_N}$${SCRYPT_R}$${SCRYPT_P}$${salt.toString('base64')}$${derived.toString('base64')}`;
}

function parseStored(stored: string): { N: number; r: number; p: number; salt: Buffer; hash: Buffer } | null {
  const parts = stored.split('$');
  if (parts.length !== 6 || parts[0] !== 'scrypt') return null;
  const N = Number.parseInt(parts[1], 10);
  const r = Number.parseInt(parts[2], 10);
  const p = Number.parseInt(parts[3], 10);
  if (!Number.isInteger(N) || !Number.isInteger(r) || !Number.isInteger(p)) return null;
  return { N, r, p, salt: Buffer.from(parts[4], 'base64'), hash: Buffer.from(parts[5], 'base64') };
}

export async function verifyPassword(password: string, stored: string): Promise<boolean> {
  const parsed = parseStored(stored);
  if (!parsed) return false;
  const derived = await new Promise<Buffer>((resolve, reject) => {
    scrypt(
      Buffer.from(password, 'utf8'),
      parsed.salt,
      parsed.hash.length,
      { N: parsed.N, r: parsed.r, p: parsed.p, maxmem: MAXMEM },
      (err, key) => (err ? reject(err) : resolve(key as Buffer)),
    );
  });
  if (derived.length !== parsed.hash.length) return false;
  return timingSafeEqual(derived, parsed.hash);
}

/**
 * Hash "dummy" de coste equivalente al KDF configurado, usado cuando el email no existe
 * para que la latencia del login sea indistinguible del caso "email existe + password
 * incorrecta" (HU-01-02 RN-12 / RNE-3).
 */
const DUMMY_HASH_PROMISE: Promise<string> = hashPassword(randomBytes(24).toString('base64'));

export async function dummyVerify(password: string): Promise<void> {
  const dummy = await DUMMY_HASH_PROMISE;
  await verifyPassword(password, dummy);
}

/** Pre-calienta el hash dummy para que el primer login fallido no pague su generación. */
export async function warmUpDummyHash(): Promise<void> {
  await DUMMY_HASH_PROMISE;
}
