/**
 * Sesiones: emisión y validación del token Bearer (HU-01-02 RN-3/RN-5/RN-6, HU-09-02).
 *
 * El token es **opaco**: 32 bytes (256 bits) del CSPRNG del sistema
 * (`crypto.randomBytes`), codificados en base64url. No deriva del email ni del
 * `accountId` y no los contiene (AT-01-02-10). En la base sólo se guarda su
 * **hash SHA-256**, de modo que el secreto no queda en reposo en claro.
 */
import { createHash, randomBytes } from 'node:crypto';
import type { Db } from '../../db/index';
import { isoFromEpochMs, nowIso } from '../../core/time';

const TOKEN_BYTES = 32; // 256 bits >= 128 bits exigidos por HU-01-02 RN-3

export interface IssuedSession {
  token: string;
  expiresAt: string;
}

export interface SessionIdentity {
  accountId: string;
  expiresAt: string;
}

export function hashToken(token: string): string {
  return createHash('sha256').update(token, 'utf8').digest('hex');
}

export class SessionService {
  constructor(private readonly db: Db, private readonly ttlSeconds: number) {}

  issue(accountId: string, now = Date.now()): IssuedSession {
    const token = randomBytes(TOKEN_BYTES).toString('base64url');
    const expiresAt = isoFromEpochMs(now + this.ttlSeconds * 1000);
    this.db
      .prepare(
        'INSERT INTO sessions (token_hash, account_id, created_at, expires_at, revoked_at) VALUES (?, ?, ?, ?, NULL)',
      )
      .run(hashToken(token), accountId, isoFromEpochMs(now), expiresAt);
    return { token, expiresAt };
  }

  /** Devuelve la identidad si el token es válido y no expiró/revocó; `null` en otro caso. */
  resolve(token: string, now = Date.now()): SessionIdentity | null {
    const row = this.db
      .prepare(
        'SELECT account_id AS accountId, expires_at AS expiresAt, revoked_at AS revokedAt FROM sessions WHERE token_hash = ?',
      )
      .get(hashToken(token)) as
      | { accountId: string; expiresAt: string; revokedAt: string | null }
      | undefined;
    if (!row) return null;
    if (row.revokedAt !== null) return null;
    if (Date.parse(row.expiresAt) <= now) return null;
    return { accountId: row.accountId, expiresAt: row.expiresAt };
  }

  /** Cantidad de sesiones vivas de una cuenta (uso interno / tests). */
  activeCount(accountId: string, now = Date.now()): number {
    const rows = this.db
      .prepare('SELECT expires_at AS expiresAt, revoked_at AS revokedAt FROM sessions WHERE account_id = ?')
      .all(accountId) as unknown as { expiresAt: string; revokedAt: string | null }[];
    return rows.filter((r) => r.revokedAt === null && Date.parse(r.expiresAt) > now).length;
  }

  purgeExpired(now = Date.now()): void {
    this.db.prepare('DELETE FROM sessions WHERE expires_at <= ?').run(isoFromEpochMs(now));
  }

  get ttl(): number {
    return this.ttlSeconds;
  }

  get issuedAtIso(): string {
    return nowIso();
  }
}
