/**
 * Asignación y consulta de direcciones de depósito (HU-06-03, HU-06-04).
 *
 * Biyección cuenta ↔ `address_index` ↔ dirección: el índice es único, monótono creciente
 * desde 0, sin reúso e inmutable (INV-EPICA-06-A). La única fuente de huecos admitida es un
 * índice que produzca una clave BIP-32 inválida (~2⁻¹²⁷), que se salta de forma
 * determinista y queda auditado en `derivation_skips` (HU-06-03 RN-1 / HU-06-02 RN-8).
 */
import { EventEmitter } from 'node:events';
import { AppError } from '../../core/errors';
import { CHAIN_ID, NETWORK_NAME } from '../../core/config';
import { nowIso } from '../../core/time';
import { isUniqueConstraintError, transaction, type Db } from '../../db/index';
import { MAX_ADDRESS_INDEX, deriveAccountFromIndexOrNext } from '../../wallet/hd';

export interface DepositAddressRecord {
  accountId: string;
  addressIndex: number;
  address: string;
  derivationPath: string;
  network: string;
  chainId: string;
  createdAt: string;
}

export interface DepositAddressAssignedEvent {
  accountId: string;
  addressIndex: number;
  address: string;
  chainId: string;
}

export const DEPOSIT_ADDRESS_ASSIGNED = 'DepositAddressAssigned';

export class WalletService {
  readonly events = new EventEmitter();
  private pendingEvents: DepositAddressAssignedEvent[] = [];

  constructor(private readonly db: Db, private readonly seed: Buffer) {}

  find(accountId: string): DepositAddressRecord | undefined {
    return this.db
      .prepare(
        `SELECT account_id AS accountId, address_index AS addressIndex, address,
                derivation_path AS derivationPath, network, chain_id AS chainId,
                created_at AS createdAt
         FROM deposit_addresses WHERE account_id = ?`,
      )
      .get(accountId) as DepositAddressRecord | undefined;
  }

  listAll(): DepositAddressRecord[] {
    return this.db
      .prepare(
        `SELECT account_id AS accountId, address_index AS addressIndex, address,
                derivation_path AS derivationPath, network, chain_id AS chainId,
                created_at AS createdAt
         FROM deposit_addresses ORDER BY address_index ASC`,
      )
      .all() as unknown as DepositAddressRecord[];
  }

  /**
   * Asigna la dirección de la cuenta **dentro de una transacción ya abierta** (alta de
   * cuenta, HU-06-03 RN-12). Es idempotente: si la cuenta ya tiene índice, no hace nada.
   */
  assignForAccountInTransaction(accountId: string): DepositAddressRecord {
    const existing = this.find(accountId);
    if (existing) return existing;

    const row = this.db
      .prepare('SELECT MAX(address_index) AS maxIndex FROM deposit_addresses')
      .get() as { maxIndex: number | null };
    const startIndex = row.maxIndex === null ? 0 : row.maxIndex + 1;
    if (startIndex > MAX_ADDRESS_INDEX) {
      // HU-06-03 RN-13: nunca se produce silenciosamente un índice hardened.
      throw new AppError(
        'INTERNAL_ERROR',
        'Se agotó el espacio de índices de derivación no-hardened.',
      );
    }

    const derived = deriveAccountFromIndexOrNext(this.seed, startIndex);
    // Auditoría de índices saltados por clave BIP-32 inválida (RN-1).
    for (let skipped = startIndex; skipped < derived.addressIndex; skipped += 1) {
      this.db
        .prepare(
          'INSERT OR IGNORE INTO derivation_skips (address_index, reason, created_at) VALUES (?, ?, ?)',
        )
        .run(skipped, 'INVALID_BIP32_KEY', nowIso());
    }

    const record: DepositAddressRecord = {
      accountId,
      addressIndex: derived.addressIndex,
      address: derived.address,
      derivationPath: derived.derivationPath,
      network: NETWORK_NAME,
      chainId: CHAIN_ID,
      createdAt: nowIso(),
    };
    this.db
      .prepare(
        `INSERT INTO deposit_addresses
           (account_id, address_index, address, derivation_path, network, chain_id, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        record.accountId,
        record.addressIndex,
        record.address,
        record.derivationPath,
        record.network,
        record.chainId,
        record.createdAt,
      );

    const event: DepositAddressAssignedEvent = {
      accountId: record.accountId,
      addressIndex: record.addressIndex,
      address: record.address,
      chainId: record.chainId,
    };
    // El evento de dominio se persiste dentro de la misma transacción (queda disponible
    // para la épica 07 aunque el proceso caiga inmediatamente después) y se publica
    // in-process recién tras el commit.
    this.db
      .prepare('INSERT INTO domain_events (type, payload, created_at) VALUES (?, ?, ?)')
      .run(DEPOSIT_ADDRESS_ASSIGNED, JSON.stringify(event), record.createdAt);
    this.pendingEvents.push(event);
    return record;
  }

  /** Publica los eventos encolados por asignaciones ya committeadas (HU-06-03 RN-11). */
  publishPendingEvents(): void {
    const events = this.pendingEvents;
    this.pendingEvents = [];
    for (const event of events) {
      this.events.emit(DEPOSIT_ADDRESS_ASSIGNED, event);
    }
  }

  /**
   * Fallback idempotente de HU-06-04 RN-5: devuelve la dirección de la cuenta y, si no
   * existiera, la asigna. Nunca asigna un segundo índice a una cuenta que ya tiene uno.
   */
  getOrAssign(accountId: string): DepositAddressRecord {
    const existing = this.find(accountId);
    if (existing) return existing;
    let record: DepositAddressRecord;
    try {
      record = transaction(this.db, () => this.assignForAccountInTransaction(accountId));
    } catch (err) {
      if (isUniqueConstraintError(err)) {
        // Otra asignación concurrente ganó la carrera: se devuelve la ya persistida.
        const winner = this.find(accountId);
        if (winner) return winner;
      }
      throw err;
    }
    this.publishPendingEvents();
    return record;
  }

  /** Eventos de dominio persistidos (inspección interna / épica 07 al arrancar). */
  listEvents(type = DEPOSIT_ADDRESS_ASSIGNED): DepositAddressAssignedEvent[] {
    const rows = this.db
      .prepare('SELECT payload FROM domain_events WHERE type = ? ORDER BY id ASC')
      .all(type) as unknown as { payload: string }[];
    return rows.map((r) => JSON.parse(r.payload) as DepositAddressAssignedEvent);
  }
}
