/**
 * Tests del módulo puro de wallet HD (BIP-39 / BIP-32 / BIP-44 / EIP-55).
 *
 * Cubre los criterios de aceptación:
 *  - HU-06-01: AT-06-01-01, AT-06-01-02, AT-06-01-03, AT-06-01-04, AT-06-01-05,
 *              AT-06-01-09, AT-06-01-10 (y la parte estática de custodia de AT-06-01-06).
 *  - HU-06-02: AT-06-02-01, AT-06-02-02, AT-06-02-03, AT-06-02-04, AT-06-02-05,
 *              AT-06-02-08, AT-06-02-09 (y la parte estática de custodia de AT-06-02-07).
 *
 * Se usa `@scure/bip32` SOLO aquí, como implementación de referencia independiente para
 * cross-checkear la implementación propia de BIP-32 (CKDpriv + master key) de `src/wallet/hd.ts`.
 */

import test from 'node:test';
import assert from 'node:assert/strict';

import { HDKey } from '@scure/bip32';
import { hmac } from '@noble/hashes/hmac';
import { sha512 } from '@noble/hashes/sha512';
import { wordlist as ENGLISH_WORDLIST } from '@scure/bip39/wordlists/english';

import {
  AddressIndexRangeError,
  DerivationExhaustedError,
  DerivedAccount,
  DerivationDeps,
  HARDENED_OFFSET,
  MAX_ADDRESS_INDEX,
  MnemonicValidationError,
  deriveAccount,
  deriveAccountFromIndexOrNext,
  derivationPathFor,
  generateMnemonic24,
  isValidChecksumAddress,
  mnemonicToSeed,
  normalizeMnemonic,
  toChecksumAddress,
  validateMnemonic24,
} from '../src/wallet/hd';

// ---------------------------------------------------------------------------
// Constantes de los vectores canónicos de la spec
// ---------------------------------------------------------------------------

/** HU-06-01: vector canónico BIP-39 (12 palabras; valida el algoritmo PBKDF2, no el largo). */
const MNEMONIC_BIP39_CANONICO =
  'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about';

const SEED_BIP39_CANONICO_TREZOR =
  'c55257c360c07c72029aebc1b53c05ed0362ada38ead3e3e9efa3708e53495531f09a6987599d18264c1e1c92f2cf1' +
  '41630c7a3c4ab7c81b2f001698e7463b04';

/** HU-06-02: mnemonic canónico de Hardhat/Anvil, passphrase vacía. */
const MNEMONIC_HARDHAT = 'test test test test test test test test test test test junk';

/** Direcciones esperadas para `m/44'/60'/0'/0/{0,1,2,3}` con MNEMONIC_HARDHAT. */
const HARDHAT_ADDRESSES = [
  '0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266',
  '0x70997970C51812dc3A010C7d01b50e0d17dc79C8',
  '0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC',
  '0x90F79bf6EB2c4f870365E785982E1f101E93b906',
];

/** Vectores de checksum EIP-55 de HU-06-02 (input raw lowercase sin `0x` -> output). */
const EIP55_VECTORS: ReadonlyArray<readonly [string, string]> = [
  ['5aaeb6053f3e94c9b9a09f33669435e7ef1beaed', '0x5aAeb6053F3E94C9b9A09f33669435E7Ef1BeAed'],
  ['fb6916095ca1df60bb79ce92ce3ea74c37c5d359', '0xfB6916095ca1df60bB79Ce92cE3Ea74c37c5d359'],
  ['dbf03b407c01e7cd3cbea99509d93f8dddc8c6fb', '0xdbF03B407c01E7cD3CBea99509d93f8DDDC8C6FB'],
  ['d1220a0cf47c7b9be7a2e6ba89f429762e7b9adb', '0xD1220A0cf47c7B9Be7A2E6BA89F429762e7b9aDb'],
];

/** Mnemonic de 24 palabras válido (entropía de 256 bits en cero): 23x `abandon` + `art`. */
const MNEMONIC_24_VALIDO = `${'abandon '.repeat(23)}art`;

/** Mismo mnemonic con la última palabra cambiada por otra del wordlist: checksum inválido. */
const MNEMONIC_24_CHECKSUM_INVALIDO = `${'abandon '.repeat(23)}zoo`;

/** 24 palabras donde una (la 24) NO pertenece al wordlist BIP-39 inglés. */
const MNEMONIC_24_PALABRA_FUERA_WORDLIST = `${'abandon '.repeat(23)}notaword`;

/** Orden del grupo secp256k1 (n). */
const SECP256K1_N = BigInt('0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141');

const seedHardhat = mnemonicToSeed(MNEMONIC_HARDHAT, '');

// ---------------------------------------------------------------------------
// Helpers de test
// ---------------------------------------------------------------------------

function ser32(index: number): Uint8Array {
  const out = new Uint8Array(4);
  new DataView(out.buffer).setUint32(0, index, false);
  return out;
}

function ser256(value: bigint): Uint8Array {
  const out = new Uint8Array(32);
  let v = value;
  for (let i = 31; i >= 0; i--) {
    out[i] = Number(v & 0xffn);
    v >>= 8n;
  }
  return out;
}

function endsWithIndex(data: Uint8Array, index: number): boolean {
  const suffix = ser32(index);
  const off = data.length - 4;
  return (
    off >= 0 &&
    data[off] === suffix[0] &&
    data[off + 1] === suffix[1] &&
    data[off + 2] === suffix[2] &&
    data[off + 3] === suffix[3]
  );
}

/** Referencia independiente: dirección de `m/44'/60'/0'/0/<i>` según @scure/bip32. */
function referenceHdKey(seed: Uint8Array): HDKey {
  // Índices numéricos EXPLÍCITOS (AT-06-02-04): 44' = 2147483692, 60' = 2147483708, 0' = 2147483648.
  return HDKey.fromMasterSeed(seed)
    .deriveChild(2147483692)
    .deriveChild(2147483708)
    .deriveChild(2147483648)
    .deriveChild(0);
}

// ===========================================================================
// HU-06-01 — Generación y custodia del seed
// ===========================================================================

test('AT-06-01-02: known-answer test BIP-39 (MNEMONIC_BIP39_CANONICO + passphrase "TREZOR")', () => {
  const seed = mnemonicToSeed(MNEMONIC_BIP39_CANONICO, 'TREZOR');
  assert.equal(seed.length, 64);
  assert.equal(seed.toString('hex'), SEED_BIP39_CANONICO_TREZOR);
});

test('AT-06-01-01: generateMnemonic24 produce 24 palabras del wordlist con checksum válido y seed de 64 bytes', () => {
  const mnemonic = generateMnemonic24();
  const words = mnemonic.split(' ');

  assert.equal(words.length, 24, 'entropía fijada del proyecto: 256 bits => 24 palabras (RN-1)');
  for (const word of words) {
    assert.ok(ENGLISH_WORDLIST.includes(word), 'toda palabra pertenece al wordlist inglés');
  }
  // Checksum válido y longitud aceptada por la validación de provisioning (RN-2).
  assert.doesNotThrow(() => validateMnemonic24(mnemonic));

  // Seed derivada con passphrase vacía por defecto (RN-3).
  const seed = mnemonicToSeed(mnemonic);
  assert.equal(seed.length, 64);
  assert.deepEqual(seed, mnemonicToSeed(mnemonic, ''), 'passphrase por defecto = cadena vacía');
});

test('AT-06-01-04: dos generaciones independientes producen mnemonics y seeds distintos', () => {
  const a = generateMnemonic24();
  const b = generateMnemonic24();

  assert.notEqual(a, b, 'no hay entropía hardcodeada (colisión ~2^-256)');
  assert.notEqual(mnemonicToSeed(a).toString('hex'), mnemonicToSeed(b).toString('hex'));
});

test('AT-06-01-03: determinismo de mnemonicToSeed (misma entrada => misma seed byte a byte)', () => {
  const first = mnemonicToSeed(MNEMONIC_24_VALIDO, 'passphrase-de-prueba');
  const second = mnemonicToSeed(MNEMONIC_24_VALIDO, 'passphrase-de-prueba');

  assert.deepEqual(first, second);
  assert.equal(first.toString('hex'), second.toString('hex'));

  // Y la passphrase efectivamente participa de la derivación.
  assert.notEqual(
    first.toString('hex'),
    mnemonicToSeed(MNEMONIC_24_VALIDO, '').toString('hex')
  );

  // Normalización NFKD + colapso de espacios: no altera el resultado del vector canónico.
  assert.equal(
    mnemonicToSeed(`  ${MNEMONIC_BIP39_CANONICO.replace(/ /g, '   ')}  `, 'TREZOR').toString('hex'),
    SEED_BIP39_CANONICO_TREZOR
  );
  assert.equal(normalizeMnemonic(`  ${MNEMONIC_BIP39_CANONICO}\n`), MNEMONIC_BIP39_CANONICO);
});

test('AT-06-01-09: mnemonic de 12 palabras válido se rechaza (longitud != 24)', () => {
  assert.throws(
    () => validateMnemonic24(MNEMONIC_BIP39_CANONICO),
    (err: unknown) => {
      assert.ok(err instanceof MnemonicValidationError);
      assert.match((err as Error).message, /24 palabras/);
      return true;
    }
  );
});

test('AT-06-01-10: mnemonic de 24 palabras con una palabra fuera del wordlist se rechaza', () => {
  assert.throws(
    () => validateMnemonic24(MNEMONIC_24_PALABRA_FUERA_WORDLIST),
    (err: unknown) => {
      assert.ok(err instanceof MnemonicValidationError);
      assert.match((err as Error).message, /wordlist/);
      return true;
    }
  );
});

test('AT-06-01-05: mnemonic de 24 palabras con checksum BIP-39 inválido se rechaza', () => {
  // Las 24 palabras están en el wordlist y la longitud es correcta: solo falla el checksum.
  assert.doesNotThrow(() => validateMnemonic24(MNEMONIC_24_VALIDO));
  assert.throws(
    () => validateMnemonic24(MNEMONIC_24_CHECKSUM_INVALIDO),
    (err: unknown) => {
      assert.ok(err instanceof MnemonicValidationError);
      assert.match((err as Error).message, /checksum/);
      return true;
    }
  );
});

test('AT-06-01-06 (custodia, estático): los errores de validación no filtran el mnemonic ni sus palabras', () => {
  const casos = [
    MNEMONIC_BIP39_CANONICO,
    MNEMONIC_24_CHECKSUM_INVALIDO,
    MNEMONIC_24_PALABRA_FUERA_WORDLIST,
  ];

  for (const mnemonic of casos) {
    try {
      validateMnemonic24(mnemonic);
      assert.fail('se esperaba MnemonicValidationError');
    } catch (err) {
      assert.ok(err instanceof MnemonicValidationError);
      const message = `${(err as Error).message}\n${(err as Error).stack ?? ''}`;
      assert.ok(!message.includes(mnemonic), 'el mensaje no contiene el mnemonic completo');
      for (const word of new Set(mnemonic.split(' '))) {
        assert.ok(!message.includes(word), `el mensaje no contiene la palabra secreta`);
      }
    }
  }
});

// ===========================================================================
// HU-06-02 — Derivación jerárquica BIP-32/BIP-44
// ===========================================================================

test('AT-06-02-01: índice 0 de MNEMONIC_HARDHAT deriva 0xf39Fd6e5...b92266', () => {
  const account = deriveAccount(seedHardhat, 0);

  assert.equal(account.address, HARDHAT_ADDRESSES[0]);
  assert.equal(account.addressIndex, 0);
  assert.equal(account.derivationPath, "m/44'/60'/0'/0/0");
  assert.match(account.publicKey, /^0x[0-9a-f]{66}$/, 'clave pública comprimida (33 bytes)');
});

test('AT-06-02-02: índices 1, 2 y 3 derivan las direcciones canónicas y todas difieren', () => {
  const accounts = [0, 1, 2, 3].map((i) => deriveAccount(seedHardhat, i));

  for (let i = 0; i < HARDHAT_ADDRESSES.length; i++) {
    assert.equal(accounts[i].address, HARDHAT_ADDRESSES[i], `address_index ${i}`);
    assert.equal(accounts[i].derivationPath, `m/44'/60'/0'/0/${i}`);
    assert.equal(accounts[i].addressIndex, i);
  }

  const distintas = new Set(accounts.map((a) => a.address));
  assert.equal(distintas.size, accounts.length, 'cada índice produce una dirección distinta');

  // Toda dirección emitida tiene checksum EIP-55 válido (RN-4).
  for (const account of accounts) assert.ok(isValidChecksumAddress(account.address));
});

test('AT-06-02-03: vectores de checksum EIP-55, comparación carácter a carácter', () => {
  for (const [raw, expected] of EIP55_VECTORS) {
    const fromString = toChecksumAddress(raw);
    const fromBytes = toChecksumAddress(Buffer.from(raw, 'hex'));

    assert.equal(fromString.length, expected.length);
    for (let i = 0; i < expected.length; i++) {
      assert.equal(fromString[i], expected[i], `posición ${i} del vector ${raw}`);
    }
    assert.equal(fromBytes, expected, 'mismo resultado desde 20 bytes crudos');
    assert.equal(toChecksumAddress(`0x${raw}`), expected, 'acepta prefijo 0x');
    assert.equal(toChecksumAddress(expected), expected, 'idempotente');
    assert.ok(isValidChecksumAddress(expected));
  }
});

test('AT-06-02-03 (borde): isValidChecksumAddress rechaza formatos y checksums incorrectos', () => {
  const [raw, checksummed] = EIP55_VECTORS[0];

  assert.equal(isValidChecksumAddress(checksummed), true);
  // Todo-minúsculas / todo-mayúsculas: no transportan checksum EIP-55 verificable => false.
  assert.equal(isValidChecksumAddress(`0x${raw}`), false);
  assert.equal(isValidChecksumAddress(`0x${raw.toUpperCase()}`), false);
  // Un solo carácter con la caja cambiada rompe el checksum.
  const flipped = `0x${checksummed[2] === '5' ? '' : ''}${checksummed.slice(2, 3)}${
    checksummed[3] === 'a' ? 'A' : 'a'
  }${checksummed.slice(4)}`;
  assert.equal(isValidChecksumAddress(flipped), false);
  // Formato inválido.
  assert.equal(isValidChecksumAddress(raw), false, 'sin prefijo 0x');
  assert.equal(isValidChecksumAddress(`0x${raw}00`), false, 'longitud incorrecta');
  assert.equal(isValidChecksumAddress(`0x${raw.slice(0, 39)}g`), false, 'carácter no hexadecimal');
  assert.equal(isValidChecksumAddress(''), false);
});

test('AT-06-02-04: componentes hardened del path (2147483692 / 2147483708 / 2147483648) y no-hardened (change, address_index)', () => {
  // (1) Las constantes del offset hardened y del rango no-hardened son las del estándar.
  assert.equal(HARDENED_OFFSET, 2147483648);
  assert.equal(MAX_ADDRESS_INDEX, 2147483647);
  assert.equal(44 + HARDENED_OFFSET, 2147483692);
  assert.equal(60 + HARDENED_OFFSET, 2147483708);
  assert.equal(0 + HARDENED_OFFSET, 2147483648);

  // (2) El path declara hardened purpose/coin_type/account y NO hardened change/address_index.
  assert.equal(derivationPathFor(0), "m/44'/60'/0'/0/0");
  assert.equal(derivationPathFor(7), "m/44'/60'/0'/0/7");
  assert.equal(derivationPathFor(MAX_ADDRESS_INDEX), `m/44'/60'/0'/0/${MAX_ADDRESS_INDEX}`);

  // (3) Verificación efectiva de los índices usados: se reconstruye la derivación con una
  //     implementación de referencia independiente (@scure/bip32) alimentada con los índices
  //     numéricos EXPLÍCITOS 2147483692 / 2147483708 / 2147483648 / 0 / address_index.
  //     Si el módulo no usara exactamente esos índices, las direcciones no coincidirían.
  const referencia = referenceHdKey(seedHardhat);
  for (const index of [0, 1, 2, 3, 12345]) {
    const child = referencia.deriveChild(index);
    assert.equal(
      deriveAccount(seedHardhat, index).publicKey,
      `0x${Buffer.from(child.publicKey as Uint8Array).toString('hex')}`,
      `índice ${index}: clave pública comprimida idéntica a la referencia`
    );
  }

  // (4) Contraprueba: derivar los mismos componentes SIN hardened da otras direcciones,
  //     lo que demuestra que la implementación usa efectivamente el espacio hardened.
  const noHardened = HDKey.fromMasterSeed(seedHardhat)
    .deriveChild(44)
    .deriveChild(60)
    .deriveChild(0)
    .deriveChild(0)
    .deriveChild(0);
  assert.notEqual(
    `0x${Buffer.from(noHardened.publicKey as Uint8Array).toString('hex')}`,
    deriveAccount(seedHardhat, 0).publicKey
  );

  // (5) `change` y `address_index` son NO hardened: el último componente entra crudo en la
  //     derivación (deriveChild(index) sin sumarle 2^31 reproduce el resultado del módulo).
  assert.ok(MAX_ADDRESS_INDEX < HARDENED_OFFSET);
});

test('AT-06-02-05: determinismo — dos derivaciones del mismo (seed, address_index) son idénticas', () => {
  const primera = deriveAccount(seedHardhat, 3);
  const segunda = deriveAccount(Uint8Array.from(seedHardhat), 3);

  assert.deepEqual(primera, segunda);
  assert.equal(primera.address, segunda.address);
  assert.equal(primera.publicKey, segunda.publicKey);

  // Reproducible también desde una seed reconstruida desde el mnemonic (reinicio simulado).
  const seedReconstruida = mnemonicToSeed(MNEMONIC_HARDHAT, '');
  assert.deepEqual(deriveAccount(seedReconstruida, 3), primera);
});

test('AT-06-02-08: I_L >= n en un índice => se avanza determinísticamente al índice siguiente', () => {
  const INDICE_ROTO = 5;
  // I forjado: I_L = n (>= n, condición inválida de BIP-32 RN-8), I_R arbitrario.
  const I_FORZADO = Buffer.concat([Buffer.from(ser256(SECP256K1_N)), Buffer.alloc(32, 0xab)]);

  let intercepciones = 0;
  const deps: DerivationDeps = {
    hmacSha512: (key, data) => {
      // Solo el último paso (derivación normal de 33+4 bytes) del índice objetivo.
      if (data.length === 37 && endsWithIndex(data, INDICE_ROTO)) {
        intercepciones++;
        return new Uint8Array(I_FORZADO);
      }
      return hmac(sha512, key, data);
    },
  };

  const derivada = deriveAccountFromIndexOrNext(seedHardhat, INDICE_ROTO, deps);

  assert.equal(intercepciones, 1, 'la inyección se activó exactamente en el índice roto');
  assert.equal(derivada.addressIndex, INDICE_ROTO + 1, 'se avanzó al índice siguiente (RN-8)');
  assert.equal(derivada.derivationPath, `m/44'/60'/0'/0/${INDICE_ROTO + 1}`);

  // El resultado es exactamente el del índice siguiente derivado normalmente, y determinista.
  const esperado = deriveAccount(seedHardhat, INDICE_ROTO + 1);
  assert.deepEqual(derivada, esperado);
  assert.deepEqual(deriveAccountFromIndexOrNext(seedHardhat, INDICE_ROTO, deps), derivada);

  // Sin inyección, el índice roto deriva normalmente (la condición no ocurre en la realidad).
  assert.equal(deriveAccountFromIndexOrNext(seedHardhat, INDICE_ROTO).addressIndex, INDICE_ROTO);

  // La variante estricta señala el borde en lugar de saltarlo.
  assert.throws(
    () => deriveAccount(seedHardhat, INDICE_ROTO, deps),
    DerivationExhaustedError
  );
});

test('AT-06-02-08 (segunda rama): k_hijo == 0 en un índice => se avanza al índice siguiente', () => {
  const INDICE_ROTO = 7;
  // k_par del nodo m/44'/60'/0'/0 según la implementación de referencia (@scure/bip32).
  const kPar = BigInt(`0x${Buffer.from(referenceHdKey(seedHardhat).privateKey as Uint8Array).toString('hex')}`);
  // I_L = n - k_par  =>  k_hijo = (I_L + k_par) mod n = 0  (inválido, BIP-32 RN-8).
  const I_FORZADO = Buffer.concat([
    Buffer.from(ser256(SECP256K1_N - kPar)),
    Buffer.alloc(32, 0x11),
  ]);

  const deps: DerivationDeps = {
    hmacSha512: (key, data) =>
      data.length === 37 && endsWithIndex(data, INDICE_ROTO)
        ? new Uint8Array(I_FORZADO)
        : hmac(sha512, key, data),
  };

  const derivada = deriveAccountFromIndexOrNext(seedHardhat, INDICE_ROTO, deps);

  assert.equal(derivada.addressIndex, INDICE_ROTO + 1);
  assert.deepEqual(derivada, deriveAccount(seedHardhat, INDICE_ROTO + 1));
  assert.throws(() => deriveAccount(seedHardhat, INDICE_ROTO, deps), DerivationExhaustedError);
});

test('AT-06-02-09: address_index fuera del rango no-hardened se rechaza ANTES de derivar', () => {
  // 2^31 = primer índice hardened => rechazado.
  let derivaciones = 0;
  const deps: DerivationDeps = {
    hmacSha512: (key, data) => {
      derivaciones++;
      return hmac(sha512, key, data);
    },
  };

  assert.throws(
    () => deriveAccount(seedHardhat, 2147483648, deps),
    (err: unknown) => {
      assert.ok(err instanceof AddressIndexRangeError);
      assert.match((err as Error).message, /address_index/);
      return true;
    }
  );
  assert.equal(derivaciones, 0, 'no se intentó ninguna derivación (RN-9)');

  for (const invalido of [-1, 1.5, 2147483649, Number.NaN, Number.POSITIVE_INFINITY]) {
    assert.throws(() => deriveAccount(seedHardhat, invalido), AddressIndexRangeError);
    assert.throws(() => deriveAccountFromIndexOrNext(seedHardhat, invalido), AddressIndexRangeError);
  }

  // 2^31 - 1 = último índice no-hardened válido => deriva normalmente.
  const ultimo: DerivedAccount = deriveAccount(seedHardhat, MAX_ADDRESS_INDEX);
  assert.equal(ultimo.addressIndex, 2147483647);
  assert.equal(ultimo.derivationPath, "m/44'/60'/0'/0/2147483647");
  assert.ok(isValidChecksumAddress(ultimo.address));
  assert.equal(
    ultimo.publicKey,
    `0x${Buffer.from(
      referenceHdKey(seedHardhat).deriveChild(MAX_ADDRESS_INDEX).publicKey as Uint8Array
    ).toString('hex')}`
  );
});

test('AT-06-02-07 (custodia, estático): DerivedAccount solo expone datos públicos', () => {
  const account = deriveAccount(seedHardhat, 0);

  assert.deepEqual(Object.keys(account).sort(), [
    'address',
    'addressIndex',
    'derivationPath',
    'publicKey',
  ]);

  const serializado = JSON.stringify(account);
  assert.ok(!/privateKey|privKey|seed|mnemonic/i.test(serializado));
  // Ni la seed ni la clave privada del nodo aparecen en la salida.
  assert.ok(!serializado.includes(seedHardhat.toString('hex')));
  assert.ok(
    !serializado.includes(
      Buffer.from(referenceHdKey(seedHardhat).deriveChild(0).privateKey as Uint8Array).toString('hex')
    )
  );
});

test('cross-check independiente: 16 índices coinciden con @scure/bip32 (dirección y clave pública)', () => {
  const seed24 = mnemonicToSeed(MNEMONIC_24_VALIDO, '');
  const referencia = referenceHdKey(seed24);

  for (const index of [0, 1, 2, 3, 4, 5, 9, 10, 99, 1000, 65535, 65536, 1000000, 16777216, 2147483646, 2147483647]) {
    const account = deriveAccount(seed24, index);
    const child = referencia.deriveChild(index);
    assert.equal(
      account.publicKey,
      `0x${Buffer.from(child.publicKey as Uint8Array).toString('hex')}`,
      `clave pública del índice ${index}`
    );
    assert.ok(isValidChecksumAddress(account.address), `dirección EIP-55 del índice ${index}`);
    assert.equal(account.derivationPath, derivationPathFor(index));
  }
});

