/**
 * Helper compartido por los tests de aceptación: levanta una instancia real del backend
 * (base SQLite en un directorio temporal + wallet HD provisionada) y expone utilidades
 * para inyectar requests HTTP con `app.inject()` (sin abrir un puerto).
 */
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { randomBytes } from 'node:crypto';
import type { FastifyInstance, InjectOptions } from 'fastify';
import { loadConfig, type Config } from '../../src/core/config';
import { bootstrap, type BootstrappedApp } from '../../src/bootstrap';

export interface TestApp extends BootstrappedApp {
  config: Config;
  dbPath: string;
  encryptionKey: string;
  /** Cierra la app y borra el directorio temporal. */
  cleanup(): Promise<void>;
}

export function makeEnv(overrides: Record<string, string> = {}): NodeJS.ProcessEnv {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cex-test-'));
  return {
    LOAD_DOTENV: 'false',
    WALLET_ENCRYPTION_KEY: randomBytes(32).toString('hex'),
    DATABASE_PATH: path.join(dir, 'exchange.db'),
    LOG_LEVEL: 'silent',
    ...overrides,
  };
}

/** Levanta una app de test. `env` permite sobreescribir cualquier variable de entorno. */
export function createTestApp(overrides: Record<string, string> = {}): TestApp {
  const env = makeEnv(overrides);
  const config = loadConfig(env);
  const booted = bootstrap(config);
  return {
    ...booted,
    config,
    dbPath: config.databasePath,
    encryptionKey: env.WALLET_ENCRYPTION_KEY as string,
    async cleanup() {
      await booted.close();
      fs.rmSync(path.dirname(config.databasePath), { recursive: true, force: true });
    },
  };
}

/** Reabre una app sobre la MISMA base y clave (simula un reinicio del proceso). */
export function restartTestApp(previous: TestApp, overrides: Record<string, string> = {}): TestApp {
  const env = {
    LOAD_DOTENV: 'false',
    WALLET_ENCRYPTION_KEY: previous.encryptionKey,
    DATABASE_PATH: previous.dbPath,
    LOG_LEVEL: 'silent',
    ...overrides,
  } as NodeJS.ProcessEnv;
  const config = loadConfig(env);
  const booted = bootstrap(config);
  return {
    ...booted,
    config,
    dbPath: previous.dbPath,
    encryptionKey: previous.encryptionKey,
    async cleanup() {
      await booted.close();
      fs.rmSync(path.dirname(previous.dbPath), { recursive: true, force: true });
    },
  };
}

export const VALID_PASSWORD = 'Sup3rSecreta';

export async function post(
  app: FastifyInstance,
  url: string,
  payload: unknown,
  options: InjectOptions = {},
) {
  return app.inject({
    method: 'POST',
    url,
    payload: payload === undefined ? undefined : JSON.stringify(payload),
    headers: { 'content-type': 'application/json', ...(options.headers ?? {}) },
    ...options,
  });
}

export async function get(app: FastifyInstance, url: string, token?: string, options: InjectOptions = {}) {
  return app.inject({
    method: 'GET',
    url,
    headers: {
      ...(token ? { authorization: `Bearer ${token}` } : {}),
      ...(options.headers ?? {}),
    },
    ...options,
  });
}

export async function registerAccount(
  app: FastifyInstance,
  email: string,
  password: string = VALID_PASSWORD,
) {
  const response = await post(app, '/api/v1/auth/register', { email, password });
  if (response.statusCode !== 201) {
    throw new Error(`registro inesperado (${response.statusCode}): ${response.body}`);
  }
  return response.json() as { accountId: string; email: string; status: string; createdAt: string };
}

export async function loginToken(
  app: FastifyInstance,
  email: string,
  password: string = VALID_PASSWORD,
): Promise<string> {
  const response = await post(app, '/api/v1/auth/login', { email, password });
  if (response.statusCode !== 200) {
    throw new Error(`login inesperado (${response.statusCode}): ${response.body}`);
  }
  return (response.json() as { token: string }).token;
}

let emailCounter = 0;
export function uniqueEmail(prefix = 'trader'): string {
  emailCounter += 1;
  return `${prefix}-${process.pid}-${emailCounter}-${randomBytes(4).toString('hex')}@example.com`;
}
