=== CONFIG ===
/**
 * Configuración del backend, leída del entorno y validada al arranque.
 *
 * Una configuración inválida **impide el arranque** (no se inicia el servicio en estado
 * inválido): HU-01-02 RN-3 (rango del TTL) y HU-06-01 RN-6/RN-11 (credencial de cifrado).
 */
import * as fs from 'node:fs';
import * as path from 'node:path';

/** Red única del proyecto: Sepolia (spec/00-fundaciones/activos-y-par-de-trading.md §1). */
export const CHAIN_ID = '11155111';
export const NETWORK_NAME = 'sepolia';
/** Confirmaciones requeridas (constante fundacional; la consumen las épicas 07/08). */
export const CONFIRMACIONES_REQUERIDAS = 12;

export class ConfigError extends Error {}

export interface RateLimitPolicy {
  enabled: boolean;
  max: number;
  windowSeconds: number;
}

export interface Config {
  host: string;
  port: number;
  databasePath: string;
  /** TTL del token de sesión en segundos; entero en [60, 86400] (HU-01-02 RN-3). */
  sessionTtlSeconds: number;
  /** Clave AES-256-GCM (32 bytes) para el cifrado en reposo del seed (HU-06-01 RN-6). */
  walletEncryptionKey: Buffer;
  /** Mnemonic importado por configuración (opcional); si falta, se genera uno nuevo. */
  walletMnemonic?: string;
  walletMnemonicPassphrase: string;
  /** Dirección del contrato USDC-mock del entorno (checksum EIP-55). */
  usdcContractAddress: string;
  /** Endpoint JSON-RPC de Sepolia (opcional en esta etapa; sin default de terceros). */
  ethRpcUrl: string;
  /** Rate limit por cuenta y endpoint para endpoints autenticados (HU-09-02 RN-12). */
  apiRateLimit: RateLimitPolicy;
  /** Anti-flood del registro (HU-01-01 RN-10); desactivado salvo configuración explícita. */
  registerRateLimit: RateLimitPolicy;
  /** Anti-fuerza-bruta del login sobre intentos fallidos (HU-01-02 RN-9). */
  loginRateLimit: RateLimitPolicy;
  /** Token para las rutas internas (`/internal/*`); si falta, sólo se admite loopback. */
  internalApiToken?: string;
  logLevel: string;
}

function readEnvFile(file: string): void {
  if (!fs.existsSync(file)) return;
  const content = fs.readFileSync(file, 'utf8');
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"') && value.length >= 2) ||
      (value.startsWith("'") && value.endsWith("'") && value.length >= 2)
    ) {
      value = value.slice(1, -1);
    }
    if (process.env[key] === undefined) process.env[key] = value;
  }
}

function parseIntStrict(value: string, name: string): number {
  if (!/^-?\d+$/.test(value.trim())) {
    throw new ConfigError(`${name} debe ser un entero; se recibió "${value}".`);
  }
  return Number.parseInt(value.trim(), 10);
}

function parseBool(value: string | undefined, fallback: boolean): boolean {
  if (value === undefined || value.trim() === '') return fallback;
  const v = value.trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(v)) return true;
  if (['0', 'false', 'no', 'off'].includes(v)) return false;
  throw new ConfigError(`Valor booleano inválido: "${value}".`);
}

function decodeKey(raw: string): Buffer {
  const value = raw.trim();
  let buf: Buffer;
  if (/^(0x)?[0-9a-fA-F]{64}$/.test(value)) {
    buf = Buffer.from(value.replace(/^0x/, ''), 'hex');
  } else {
    buf = Buffer.from(value, 'base64');
  }
  if (buf.length !== 32) {
    throw new ConfigError(
      'WALLET_ENCRYPTION_KEY debe ser una clave de 32 bytes (64 hex o 44 caracteres base64). ' +
        'Podés generar una con: npm run genkey',
    );
  }
  return buf;
}

function rateLimitFrom(
  enabledVar: string,
  maxVar: string,
  windowVar: string,
  defaults: RateLimitPolicy,
): RateLimitPolicy {
  const enabled = parseBool(process.env[enabledVar], defaults.enabled);
  if (!enabled) return { enabled: false, max: defaults.max, windowSeconds: defaults.windowSeconds };
  // Cuando el rate limiting está activo, umbral y ventana son obligatorios y declarados
  // en la configuración del entorno (HU-01-01 RN-10).
  const rawMax = process.env[maxVar];
  const rawWindow = process.env[windowVar];
  const max = rawMax !== undefined && rawMax !== '' ? parseIntStrict(rawMax, maxVar) : defaults.max;
  const windowSeconds =
    rawWindow !== undefined && rawWindow !== ''
      ? parseIntStrict(rawWindow, windowVar)
      : defaults.windowSeconds;
  if (max <= 0) throw new ConfigError(`${maxVar} debe ser un entero positivo.`);
  if (windowSeconds <= 0) throw new ConfigError(`${windowVar} debe ser un entero positivo.`);
  return { enabled: true, max, windowSeconds };
}

/**
 * Dirección por defecto del USDC-mock en Sepolia. Es un parámetro del despliegue
 * (spec/00-fundaciones/activos-y-par-de-trading.md §2.2): se sobreescribe con
 * `USDC_CONTRACT_ADDRESS`.
 */
export const DEFAULT_USDC_CONTRACT_ADDRESS = '0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238';

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  if (parseBool(env.LOAD_DOTENV, true)) {
    readEnvFile(path.resolve(process.cwd(), '.env'));
  }

  const port = env.PORT ? parseIntStrict(env.PORT, 'PORT') : 3000;
  if (port < 0 || port > 65535) throw new ConfigError('PORT fuera de rango.');

  const sessionTtlSeconds = env.SESSION_TTL_SECONDS
    ? parseIntStrict(env.SESSION_TTL_SECONDS, 'SESSION_TTL_SECONDS')
    : 3600;
  // HU-01-02 RN-3: TTL entero positivo en [60, 86400]; fuera de rango => no se arranca.
  if (sessionTtlSeconds < 60 || sessionTtlSeconds > 86400) {
    throw new ConfigError(
      `SESSION_TTL_SECONDS debe ser un entero en el rango [60, 86400]; se recibió ${sessionTtlSeconds}.`,
    );
  }

  const rawKey = env.WALLET_ENCRYPTION_KEY;
  if (!rawKey || rawKey.trim() === '') {
    throw new ConfigError(
      'Falta WALLET_ENCRYPTION_KEY: la credencial de cifrado del seed HD se provee por ' +
        'configuración del entorno y nunca se embebe en el código (HU-06-01 RN-6). ' +
        'Generá una con: npm run genkey',
    );
  }

  const chainIdEnv = (env.CHAIN_ID ?? CHAIN_ID).trim();
  if (chainIdEnv !== CHAIN_ID) {
    throw new ConfigError(
      `La única red soportada es Sepolia (chainId ${CHAIN_ID}); se configuró ${chainIdEnv}.`,
    );
  }

  return {
    host: env.HOST?.trim() || '0.0.0.0',
    port,
    databasePath: env.DATABASE_PATH?.trim() || path.resolve(process.cwd(), 'data', 'exchange.db'),
    sessionTtlSeconds,
    walletEncryptionKey: decodeKey(rawKey),
    walletMnemonic: env.WALLET_MNEMONIC?.trim() ? env.WALLET_MNEMONIC.trim() : undefined,
    walletMnemonicPassphrase: env.WALLET_MNEMONIC_PASSPHRASE ?? '',
    usdcContractAddress: env.USDC_CONTRACT_ADDRESS?.trim() || DEFAULT_USDC_CONTRACT_ADDRESS,
    ethRpcUrl: env.ETH_RPC_URL?.trim() || '',
    apiRateLimit: rateLimitFrom(
      'API_RATE_LIMIT_ENABLED',
      'API_RATE_LIMIT_MAX',
      'API_RATE_LIMIT_WINDOW_SECONDS',
      // HU-09-02 RN-12: 60 requests por minuto, por cuenta y por endpoint.
      { enabled: true, max: 60, windowSeconds: 60 },
    ),
    registerRateLimit: rateLimitFrom(
      'REGISTER_RATE_LIMIT_ENABLED',
      'REGISTER_RATE_LIMIT_MAX',
      'REGISTER_RATE_LIMIT_WINDOW_SECONDS',
      // HU-01-01 RN-10: opcional; desactivado salvo configuración explícita del entorno.
      { enabled: false, max: 20, windowSeconds: 60 },
    ),
    loginRateLimit: rateLimitFrom(
      'LOGIN_RATE_LIMIT_ENABLED',
      'LOGIN_RATE_LIMIT_MAX_FAILURES',
      'LOGIN_RATE_LIMIT_WINDOW_SECONDS',
      // HU-01-02 RN-9: opcional; cuenta intentos fallidos por (origen, email).
      { enabled: false, max: 5, windowSeconds: 60 },
    ),
    internalApiToken: env.INTERNAL_API_TOKEN?.trim() || undefined,
    logLevel: env.LOG_LEVEL?.trim() || 'info',
  };
}

