/** Validaciones transversales de entrada (formato de email, montos, etc.). */

/**
 * Formato de email (HU-01-01 RN-2): exactamente un `@`, parte local no vacía sin espacios,
 * dominio con al menos un punto, sin punto inicial/final ni puntos consecutivos.
 */
export const EMAIL_PATTERN = /^[^@\s]+@[^@\s.]+(\.[^@\s.]+)+$/;
export const EMAIL_MAX_LENGTH = 254;
export const PASSWORD_MIN_LENGTH = 8;
export const PASSWORD_MAX_LENGTH = 128;

/** Normalización de identidad (RNE-1 / HU-01-01 RN-1): `trim` + `lowercase`. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

export function isValidEmailFormat(normalizedEmail: string): boolean {
  return (
    normalizedEmail.length <= EMAIL_MAX_LENGTH && EMAIL_PATTERN.test(normalizedEmail)
  );
}

/**
 * Patrón de monto serializado (convenciones-monetarias.md §5): string de entero decimal no
 * negativo, sin signo, sin decimales, sin notación científica y sin ceros a la izquierda.
 */
export const AMOUNT_PATTERN = /^(0|[1-9][0-9]*)$/;

export function isSerializedAmount(value: unknown): value is string {
  return typeof value === 'string' && AMOUNT_PATTERN.test(value);
}
