/**
 * Composición de la aplicación: abre la base, provisiona/carga la wallet HD, arma los
 * servicios y construye el servidor HTTP. Lo usan tanto `main.ts` como los tests.
 */
import type { FastifyInstance } from 'fastify';
import type { Config } from './core/config';
import { AuditLog } from './core/audit';
import { openDatabase, type Db } from './db/index';
import { AccountService } from './modules/accounts/service';
import { SessionService } from './modules/accounts/sessions';
import { WalletService } from './modules/wallet/service';
import { provisionWallet, verifySeedIntegrity } from './modules/wallet/seedStore';
import { buildApp } from './http/app';

export interface Services {
  accounts: AccountService;
  sessions: SessionService;
  wallet: WalletService;
  audit: AuditLog;
}

export interface BootstrappedApp {
  app: FastifyInstance;
  db: Db;
  services: Services;
  seed: Buffer;
  close(): Promise<void>;
}

export function createServices(config: Config, db: Db, seed: Buffer): Services {
  const audit = new AuditLog(db);
  const sessions = new SessionService(db, config.sessionTtlSeconds);
  const wallet = new WalletService(db, seed);
  const accounts = new AccountService(db, sessions, audit, wallet);
  return { accounts, sessions, wallet, audit };
}

export function bootstrap(config: Config): BootstrappedApp {
  const db = openDatabase(config.databasePath);
  const provisioned = provisionWallet({
    db,
    encryptionKey: config.walletEncryptionKey,
    importedMnemonic: config.walletMnemonic,
    passphrase: config.walletMnemonicPassphrase,
  });
  // Smoke test de integridad del seed contra el mapeo persistido (HU-06-01 RN-10).
  verifySeedIntegrity(db, provisioned.seed);
  const services = createServices(config, db, provisioned.seed);
  const app = buildApp({ config, db, ...services });
  return {
    app,
    db,
    services,
    seed: provisioned.seed,
    async close() {
      await app.close();
      db.close();
    },
  };
}
