/**
 * Provisioning y custodia del seed HD (HU-06-01).
 *
 * - El material secreto se persiste **cifrado en reposo** con AES-256-GCM, con nonce
 *   aleatorio de 96 bits por operación de cifrado y tag de 128 bits, en el formato
 *   `nonce || ciphertext || tag` (RN-6).
 * - La clave de cifrado proviene de la configuración del entorno; nunca se persiste junto
 *   al material cifrado ni está embebida en el código.
 * - Ante mnemonic inválido, fallo de descifrado o verificación de integridad fallida, el
 *   proceso **aborta** sin generar ni sobrescribir un seed (RN-11). Esta capa señaliza el
 *   fallo con `ProvisioningError`, que `main.ts` traduce a salida distinta de cero con el
 *   `code` del catálogo en `stderr`, **sin filtrar material secreto** (RN-5).
 */
import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto';
import type { Db } from '../../db/index';
import { transaction } from '../../db/index';
import { nowIso } from '../../core/time';
import {
  MnemonicValidationError,
  deriveAccount,
  generateMnemonic24,
  mnemonicToSeed,
  validateMnemonic24,
} from '../../wallet/hd';

const NONCE_BYTES = 12;
const TAG_BYTES = 16;

export type ProvisioningErrorCode = 'VALIDATION_ERROR' | 'INTERNAL_ERROR';

export class ProvisioningError extends Error {
  constructor(readonly code: ProvisioningErrorCode, message: string) {
    super(message);
    this.name = 'ProvisioningError';
  }
}

interface SeedPayload {
  v: 1;
  mnemonic: string;
  passphrase: string;
}

export function encryptPayload(plaintext: Buffer, key: Buffer): Buffer {
  const nonce = randomBytes(NONCE_BYTES);
  const cipher = createCipheriv('aes-256-gcm', key, nonce);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([nonce, ciphertext, tag]);
}

export function decryptPayload(blob: Buffer, key: Buffer): Buffer {
  if (blob.length < NONCE_BYTES + TAG_BYTES) {
    throw new ProvisioningError('INTERNAL_ERROR', 'El material cifrado del seed está incompleto.');
  }
  const nonce = blob.subarray(0, NONCE_BYTES);
  const tag = blob.subarray(blob.length - TAG_BYTES);
  const ciphertext = blob.subarray(NONCE_BYTES, blob.length - TAG_BYTES);
  const decipher = createDecipheriv('aes-256-gcm', key, nonce);
  decipher.setAuthTag(tag);
  try {
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  } catch {
    // Tag GCM que no verifica: corrupción, restauración incorrecta o credencial errónea.
    throw new ProvisioningError(
      'INTERNAL_ERROR',
      'No se pudo descifrar el seed HD persistido (credencial incorrecta o material corrupto).',
    );
  }
}

export interface ProvisionedWallet {
  seed: Buffer;
  /** `true` si esta ejecución generó el seed; `false` si lo recuperó del almacenamiento. */
  generated: boolean;
}

export interface ProvisionOptions {
  db: Db;
  encryptionKey: Buffer;
  /** Mnemonic importado por configuración (opcional). Debe cumplir BIP-39 de 24 palabras. */
  importedMnemonic?: string;
  passphrase?: string;
}

/**
 * Carga el seed persistido o, si no existe, provisiona uno nuevo (o importa el configurado).
 * Nunca regenera ni sobrescribe un seed existente (RN-4/RN-8).
 */
export function provisionWallet(options: ProvisionOptions): ProvisionedWallet {
  const { db, encryptionKey } = options;
  const existing = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as
    | { payload: Uint8Array }
    | undefined;

  if (existing) {
    const plaintext = decryptPayload(Buffer.from(existing.payload), encryptionKey);
    let payload: SeedPayload;
    try {
      payload = JSON.parse(plaintext.toString('utf8')) as SeedPayload;
    } catch {
      throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD persistido no es legible.');
    }
    if (typeof payload?.mnemonic !== 'string') {
      throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD persistido no es legible.');
    }
    const seed = mnemonicToSeed(payload.mnemonic, payload.passphrase ?? '');
    return { seed, generated: false };
  }

  const passphrase = options.passphrase ?? '';
  let mnemonic: string;
  if (options.importedMnemonic) {
    try {
      validateMnemonic24(options.importedMnemonic);
    } catch (err) {
      if (err instanceof MnemonicValidationError) {
        // No se adopta ni se persiste nada (RN-2/RN-11).
        throw new ProvisioningError('VALIDATION_ERROR', `Mnemonic BIP-39 inválido: ${err.message}`);
      }
      throw err;
    }
    mnemonic = options.importedMnemonic;
  } else {
    mnemonic = generateMnemonic24();
  }

  const payload: SeedPayload = { v: 1, mnemonic, passphrase };
  const blob = encryptPayload(Buffer.from(JSON.stringify(payload), 'utf8'), encryptionKey);
  // Escritura atómica: una única transacción; el seed se considera provisionado sólo si
  // luego puede leerse y descifrarse (RN-9).
  transaction(db, () => {
    db.prepare('INSERT INTO wallet_seed (id, payload, created_at) VALUES (1, ?, ?)').run(
      blob,
      nowIso(),
    );
  });
  const verification = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as
    | { payload: Uint8Array }
    | undefined;
  if (!verification) {
    throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD no quedó persistido.');
  }
  decryptPayload(Buffer.from(verification.payload), encryptionKey);

  return { seed: mnemonicToSeed(mnemonic, passphrase), generated: true };
}

/**
 * Smoke test de integridad al arrancar (RN-10): con un mapeo `cuenta → address_index` no
 * vacío, se re-deriva el índice más bajo asignado y se compara con la dirección
 * persistida. Cualquier discrepancia aborta el arranque (RN-11).
 */
export function verifySeedIntegrity(db: Db, seed: Buffer, k = 1): void {
  const rows = db
    .prepare(
      'SELECT address_index AS addressIndex, address FROM deposit_addresses ORDER BY address_index ASC LIMIT ?',
    )
    .all(k) as unknown as { addressIndex: number; address: string }[];
  for (const row of rows) {
    const derived = deriveAccount(seed, row.addressIndex);
    if (derived.address !== row.address) {
      throw new ProvisioningError(
        'INTERNAL_ERROR',
        `Verificación de integridad del seed fallida para el índice ${row.addressIndex}: ` +
          'la dirección derivada no coincide con la persistida.',
      );
    }
  }
}

/**
 * Asignación y consulta de direcciones de depósito (HU-06-03, HU-06-04).
 *
 * Biyección cuenta ↔ `address_index` ↔ dirección: el índice es único, monótono creciente
 * desde 0, sin reúso e inmutable (INV-EPICA-06-A). La única fuente de huecos admitida es un
 * índice que produzca una clave BIP-32 inválida (~2⁻¹²⁷), que se salta de forma
 * determinista y queda auditado en `derivation_skips` (HU-06-03 RN-1 / HU-06-02 RN-8).
 */
import { EventEmitter } from 'node:events';
import { AppError } from '../../core/errors';
import { CHAIN_ID, NETWORK_NAME } from '../../core/config';
import { nowIso } from '../../core/time';
import { isUniqueConstraintError, transaction, type Db } from '../../db/index';
import { MAX_ADDRESS_INDEX, deriveAccountFromIndexOrNext } from '../../wallet/hd';

export interface DepositAddressRecord {
  accountId: string;
  addressIndex: number;
  address: string;
  derivationPath: string;
  network: string;
  chainId: string;
  createdAt: string;
}

export interface DepositAddressAssignedEvent {
  accountId: string;
  addressIndex: number;
  address: string;
  chainId: string;
}

export const DEPOSIT_ADDRESS_ASSIGNED = 'DepositAddressAssigned';

export class WalletService {
  readonly events = new EventEmitter();
  private pendingEvents: DepositAddressAssignedEvent[] = [];

  constructor(private readonly db: Db, private readonly seed: Buffer) {}

  find(accountId: string): DepositAddressRecord | undefined {
    return this.db
      .prepare(
        `SELECT account_id AS accountId, address_index AS addressIndex, address,
                derivation_path AS derivationPath, network, chain_id AS chainId,
                created_at AS createdAt
         FROM deposit_addresses WHERE account_id = ?`,
      )
      .get(accountId) as DepositAddressRecord | undefined;
  }

  listAll(): DepositAddressRecord[] {
    return this.db
      .prepare(
        `SELECT account_id AS accountId, address_index AS addressIndex, address,
                derivation_path AS derivationPath, network, chain_id AS chainId,
                created_at AS createdAt
         FROM deposit_addresses ORDER BY address_index ASC`,
      )
      .all() as unknown as DepositAddressRecord[];
  }

  /**
   * Asigna la dirección de la cuenta **dentro de una transacción ya abierta** (alta de
   * cuenta, HU-06-03 RN-12). Es idempotente: si la cuenta ya tiene índice, no hace nada.
   */
  assignForAccountInTransaction(accountId: string): DepositAddressRecord {
    const existing = this.find(accountId);
    if (existing) return existing;

    const row = this.db
      .prepare('SELECT MAX(address_index) AS maxIndex FROM deposit_addresses')
      .get() as { maxIndex: number | null };
    const startIndex = row.maxIndex === null ? 0 : row.maxIndex + 1;
    if (startIndex > MAX_ADDRESS_INDEX) {
      // HU-06-03 RN-13: nunca se produce silenciosamente un índice hardened.
      throw new AppError(
        'INTERNAL_ERROR',
        'Se agotó el espacio de índices de derivación no-hardened.',
      );
    }

    const derived = deriveAccountFromIndexOrNext(this.seed, startIndex);
    // Auditoría de índices saltados por clave BIP-32 inválida (RN-1).
    for (let skipped = startIndex; skipped < derived.addressIndex; skipped += 1) {
      this.db
        .prepare(
          'INSERT OR IGNORE INTO derivation_skips (address_index, reason, created_at) VALUES (?, ?, ?)',
        )
        .run(skipped, 'INVALID_BIP32_KEY', nowIso());
    }

    const record: DepositAddressRecord = {
      accountId,
      addressIndex: derived.addressIndex,
      address: derived.address,
      derivationPath: derived.derivationPath,
      network: NETWORK_NAME,
      chainId: CHAIN_ID,
      createdAt: nowIso(),
    };
    this.db
      .prepare(
        `INSERT INTO deposit_addresses
           (account_id, address_index, address, derivation_path, network, chain_id, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        record.accountId,
        record.addressIndex,
        record.address,
        record.derivationPath,
        record.network,
        record.chainId,
        record.createdAt,
      );

    const event: DepositAddressAssignedEvent = {
      accountId: record.accountId,
      addressIndex: record.addressIndex,
      address: record.address,
      chainId: record.chainId,
    };
    // El evento de dominio se persiste dentro de la misma transacción (queda disponible
    // para la épica 07 aunque el proceso caiga inmediatamente después) y se publica
    // in-process recién tras el commit.
    this.db
      .prepare('INSERT INTO domain_events (type, payload, created_at) VALUES (?, ?, ?)')
      .run(DEPOSIT_ADDRESS_ASSIGNED, JSON.stringify(event), record.createdAt);
    this.pendingEvents.push(event);
    return record;
  }

  /** Publica los eventos encolados por asignaciones ya committeadas (HU-06-03 RN-11). */
  publishPendingEvents(): void {
    const events = this.pendingEvents;
    this.pendingEvents = [];
    for (const event of events) {
      this.events.emit(DEPOSIT_ADDRESS_ASSIGNED, event);
    }
  }

  /**
   * Fallback idempotente de HU-06-04 RN-5: devuelve la dirección de la cuenta y, si no
   * existiera, la asigna. Nunca asigna un segundo índice a una cuenta que ya tiene uno.
   */
  getOrAssign(accountId: string): DepositAddressRecord {
    const existing = this.find(accountId);
    if (existing) return existing;
    let record: DepositAddressRecord;
    try {
      record = transaction(this.db, () => this.assignForAccountInTransaction(accountId));
    } catch (err) {
      if (isUniqueConstraintError(err)) {
        // Otra asignación concurrente ganó la carrera: se devuelve la ya persistida.
        const winner = this.find(accountId);
        if (winner) return winner;
      }
      throw err;
    }
    this.publishPendingEvents();
    return record;
  }

  /** Eventos de dominio persistidos (inspección interna / épica 07 al arrancar). */
  listEvents(type = DEPOSIT_ADDRESS_ASSIGNED): DepositAddressAssignedEvent[] {
    const rows = this.db
      .prepare('SELECT payload FROM domain_events WHERE type = ? ORDER BY id ASC')
      .all(type) as unknown as { payload: string }[];
    return rows.map((r) => JSON.parse(r.payload) as DepositAddressAssignedEvent);
  }
}
