test('AT-01-01-19: el accountId es opaco, no secuencial y estable para la misma cuenta', async () => {
  const ctx = createTestApp();
  try {
    const emailA = uniqueEmail('a');
    const emailB = uniqueEmail('b');
    const a = await registerAccount(ctx.app, emailA);
    const b = await registerAccount(ctx.app, emailB);

    for (const id of [a.accountId, b.accountId]) {
      assert.equal(typeof id, 'string');
      assert.ok(id.length > 0, 'accountId no vacío');
      // No secuencial: no es un entero (ni, por lo tanto, un contador incremental).
      assert.ok(!/^\d+$/.test(id), `accountId no debe ser un entero: ${id}`);
      // Opaco y con ≥122 bits de entropía: UUID v4 (RN-6 / RNE-6).
      assert.match(id, UUID_V4);
    }
    assert.notEqual(a.accountId, b.accountId);

    // No difieren en un patrón predecible: no son enteros consecutivos en ninguna base
    // razonable, ni comparten el prefijo de alta entropía del UUID.
    assert.notEqual(a.accountId.slice(0, 8), b.accountId.slice(0, 8));
    const hexA = BigInt(`0x${a.accountId.replace(/-/g, '')}`);
    const hexB = BigInt(`0x${b.accountId.replace(/-/g, '')}`);
    const delta = hexA > hexB ? hexA - hexB : hexB - hexA;
    assert.ok(delta > 1n, 'los accountId no pueden ser consecutivos');

    // Estabilidad: consultas sucesivas de la misma cuenta devuelven el mismo accountId.
    const repo = ctx.services.accounts.repository;
    assert.equal(repo.findByEmail(emailA)!.accountId, a.accountId);
    assert.equal(repo.findByEmail(emailA)!.accountId, a.accountId);
    assert.equal(repo.findById(a.accountId)!.email, emailA);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-01-01-20: anti-flood de registro — la solicitud N+1 se rechaza con RATE_LIMITED (429)', async () => {
  // El rate limiting de registro es opcional (RN-10) y está desactivado por defecto: se
  // activa explícitamente por entorno, con umbral y ventana declarados.
  const MAX = 3;
  const ctx = createTestApp({
    REGISTER_RATE_LIMIT_ENABLED: 'true',
    REGISTER_RATE_LIMIT_MAX: String(MAX),
    REGISTER_RATE_LIMIT_WINDOW_SECONDS: '60',
  });
  try {
    assert.equal(ctx.config.registerRateLimit.enabled, true);
    assert.equal(ctx.config.registerRateLimit.max, MAX);

    for (let i = 0; i < MAX; i += 1) {
      const ok = await post(ctx.app, REGISTER_URL, {
        email: uniqueEmail(),
        password: VALID_PASSWORD,
      });
      assert.equal(ok.statusCode, 201, `solicitud ${i + 1} debería pasar: ${ok.body}`);
    }

    const limited = await post(ctx.app, REGISTER_URL, {
      email: uniqueEmail(),
      password: VALID_PASSWORD,
    });
    const error = assertErrorEnvelope(limited, 'RATE_LIMITED', 429);
    const details = error.details as { retryAfterSeconds: number };
    assert.equal(typeof details.retryAfterSeconds, 'number');
    assert.ok(details.retryAfterSeconds >= 0, 'retryAfterSeconds ≥ 0');
    assert.equal(limited.headers['retry-after'], String(details.retryAfterSeconds));

    // RN-9 paso 0: con el límite excedido, un payload inválido responde 429, no 422.
    const invalid = await post(ctx.app, REGISTER_URL, { email: 42 });
    assertErrorEnvelope(invalid, 'RATE_LIMITED', 429);

    assert.equal(countAccounts(ctx), MAX, 'la solicitud N+1 no crea cuenta');
  } finally {
    await ctx.cleanup();
  }
});
