test('AT-01-02-01: login exitoso devuelve token y expiresAt ISO 8601 UTC futuro (200)', async () => {
  const ctx = createTestApp();
  try {
    await registerAccount(ctx.app, 'trader@example.com', 'Sup3rSecreta');
    const before = Date.now();
    const response = await post(ctx.app, LOGIN_URL, {
      email: 'trader@example.com',
      password: 'Sup3rSecreta',
    });

    assert.equal(response.statusCode, 200, response.body);
    const body = response.json() as { token: string; tokenType: string; expiresAt: string };
    assert.deepEqual(Object.keys(body).sort(), ['expiresAt', 'token', 'tokenType']);
    assert.equal(typeof body.token, 'string');
    assert.ok(body.token.length > 0, 'el token no puede ser vacío');
    assert.equal(body.tokenType, 'Bearer');
    assert.match(body.expiresAt, ISO_UTC);
    assert.ok(Date.parse(body.expiresAt) > before, 'expiresAt debe ser posterior al instante actual');
    // TTL por defecto del proyecto: 3600 s (RN-3).
    assert.ok(
      Math.abs(Date.parse(body.expiresAt) - (before + ctx.config.sessionTtlSeconds * 1000)) < 5000,
      'expiresAt debe corresponder al TTL configurado',
    );

    // RN-4 / RNE-2: ni contraseña ni hash en la respuesta.
    assertNoSecrets(response, ['Sup3rSecreta']);
  } finally {
    await ctx.cleanup();
  }
});

