/**
 * AT-01-02-11 — indistinguibilidad temporal (anti timing attack, RN-12 / RNE-3).
 *
 * Metodología (escrita para NO ser flaky):
 *  1. Se descarta un **warm-up** de 5 intentos por ruta: la primera ejecución paga la
 *     generación perezosa del hash dummy, la preparación de statements SQLite y el JIT.
 *  2. Se toman N = 50 mediciones por ruta **alternando** ambas rutas (A, B, A, B, …), de
 *     modo que cualquier deriva del entorno (GC, ruido de CPU, throttling) afecte por
 *     igual a las dos muestras en vez de concentrarse en la que se mida primero.
 *  3. Cada medición es secuencial (sin concurrencia) y usa `process.hrtime.bigint()`.
 *  4. Se calculan P50 y P95 con el método del rango más cercano
 *     (`idx = ceil(p * n) - 1` sobre la muestra ordenada) y se afirma que la **diferencia
 *     absoluta** de cada percentil entre ambas rutas es menor a la tolerancia de
 *     referencia de la spec: 50 ms.
 */
const TIMING_TOLERANCE_MS = 50;

function percentile(samples: number[], p: number): number {
  const sorted = [...samples].sort((a, b) => a - b);
  const idx = Math.min(sorted.length - 1, Math.max(0, Math.ceil(p * sorted.length) - 1));
  return sorted[idx];
}

test('AT-01-02-11: indistinguibilidad temporal entre email inexistente y contraseña incorrecta', async () => {
  const ctx = createTestApp();
  try {
    await registerAccount(ctx.app, 'trader@example.com');

    const existente = () =>
      post(ctx.app, LOGIN_URL, { email: 'trader@example.com', password: 'PasswordIncorrecta' });
    const inexistente = () =>
      post(ctx.app, LOGIN_URL, { email: 'desconocido@example.com', password: 'PasswordIncorrecta' });

    // 1) Warm-up descartado.
    for (let i = 0; i < 5; i += 1) {
      assert.equal((await inexistente()).statusCode, 401);
      assert.equal((await existente()).statusCode, 401);
    }

    // 2) 50 + 50 mediciones alternadas.
    const N = 50;
    const desconocidos: number[] = [];
    const passwordMala: number[] = [];
    for (let i = 0; i < N; i += 1) {
      let t0 = process.hrtime.bigint();
      assert.equal((await inexistente()).statusCode, 401);
      desconocidos.push(Number(process.hrtime.bigint() - t0) / 1e6);

      t0 = process.hrtime.bigint();
      assert.equal((await existente()).statusCode, 401);
      passwordMala.push(Number(process.hrtime.bigint() - t0) / 1e6);
    }

    // 4) Comparación de percentiles.
    const p50a = percentile(desconocidos, 0.5);
    const p50b = percentile(passwordMala, 0.5);
    const p95a = percentile(desconocidos, 0.95);
    const p95b = percentile(passwordMala, 0.95);
    const diffP50 = Math.abs(p50a - p50b);
    const diffP95 = Math.abs(p95a - p95b);

    assert.ok(
      diffP50 < TIMING_TOLERANCE_MS,
      `P50 difiere ${diffP50.toFixed(2)} ms (inexistente=${p50a.toFixed(2)}, password incorrecta=${p50b.toFixed(2)}); tolerancia ${TIMING_TOLERANCE_MS} ms`,
    );
    assert.ok(
      diffP95 < TIMING_TOLERANCE_MS,
      `P95 difiere ${diffP95.toFixed(2)} ms (inexistente=${p95a.toFixed(2)}, password incorrecta=${p95b.toFixed(2)}); tolerancia ${TIMING_TOLERANCE_MS} ms`,
    );
    // Evidencia del hash dummy: la ruta "email inexistente" no es una respuesta rápida.
    assert.ok(p50a > 1, `la ruta de email inexistente debe ejecutar el KDF dummy (P50=${p50a.toFixed(2)} ms)`);
  } finally {
    await ctx.cleanup();
  }
});

