  verifySeedIntegrity,
} from '../src/modules/wallet/seedStore';
import { DEPOSIT_ADDRESS_ASSIGNED } from '../src/modules/wallet/service';
import { deriveAccount } from '../src/wallet/hd';

// ---------------------------------------------------------------------------
// Constantes y utilidades del test
// ---------------------------------------------------------------------------

const CHAIN_ID = '11155111';
const NETWORK = 'sepolia';

/** Mnemonic BIP-39 de 24 palabras (256 bits de entropía) usado como seed importado. */
const MNEMONIC_24 = `${Array(23).fill('abandon').join(' ')} art`;
/** Un segundo mnemonic de 24 palabras, distinto, para simular una restauración incorrecta. */
const MNEMONIC_24_AJENO = `${Array(23).fill('legal').join(' ')} will`;

function bytesToHex(bytes: Uint8Array): string {
  return Buffer.from(bytes).toString('hex');
}

/** Checksum EIP-55 implementado en el test (independiente de `src/wallet/hd.ts`). */
function toEip55(raw20: Uint8Array): string {
  const lower = bytesToHex(raw20);
  const hash = bytesToHex(keccak_256(Buffer.from(lower, 'ascii')));
  let out = '';
  for (let i = 0; i < lower.length; i += 1) {
    out += Number.parseInt(hash[i], 16) >= 8 ? lower[i].toUpperCase() : lower[i];
  }
  return `0x${out}`;
}

/** `true` si la dirección tiene formato `0x`+40 hex y checksum EIP-55 correcto. */
function isEip55(address: unknown): boolean {
  if (typeof address !== 'string' || !/^0x[0-9a-fA-F]{40}$/.test(address)) return false;
  return address === toEip55(Buffer.from(address.slice(2).toLowerCase(), 'hex'));
}

/** Derivación BIP-44 de referencia (externa al sistema) sobre `m/44'/60'/0'/0/{i}`. */
function referenceDerivation(mnemonic: string, addressIndex: number, passphrase = '') {
  assert.ok(validateMnemonic(mnemonic, ENGLISH_WORDLIST), 'el mnemonic de referencia es BIP-39');
  const seed = mnemonicToSeedSync(mnemonic, passphrase);
  const child = HDKey.fromMasterSeed(seed).derive(`m/44'/60'/0'/0/${addressIndex}`);
  assert.ok(child.privateKey, 'la referencia derivó una clave privada');
  const uncompressed = secp256k1.getPublicKey(child.privateKey, false).slice(1); // X || Y
  return {
    address: toEip55(keccak_256(uncompressed).slice(12)),
    privateKeyHex: bytesToHex(child.privateKey),
    seedHex: bytesToHex(seed),
  };
}

function referenceAddress(mnemonic: string, addressIndex: number): string {
  return referenceDerivation(mnemonic, addressIndex).address;
}

