test('AT-06-01-06: ninguna respuesta de la API expone mnemonic, seed ni privateKey', async () => {
  const ctx = createTestApp({ WALLET_MNEMONIC: MNEMONIC_24 });
  try {
    const email = uniqueEmail();
    const account = await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);

    const responses = [
      await get(ctx.app, '/health'),
      await get(ctx.app, '/api/v1/deposit-address?asset=ETH', token),
      await get(ctx.app, '/api/v1/deposit-address?asset=USDC', token),
      await get(ctx.app, '/internal/deposit-addresses'),
      // También las respuestas de error deben respetar la custodia.
      await get(ctx.app, '/api/v1/deposit-address?asset=BTC', token),
      await get(ctx.app, '/api/v1/deposit-address?asset=ETH'),
    ];

    const reference = referenceDerivation(MNEMONIC_24, 0);
    const secretos = [MNEMONIC_24, reference.seedHex, reference.privateKeyHex, 'abandon'];

    for (const response of responses) {
      const body = response.body;
      // (a) Ningún campo llamado `mnemonic`, `seed` o `privateKey` (ni variantes).
      for (const key of collectKeys(response.json())) {
        assert.ok(
          !/mnemonic|seed|privatekey|private_key|secret/i.test(key),
          `la respuesta expone el campo "${key}": ${body}`,
        );
      }
      // (b) Ni su VALOR en ningún campo.
      for (const secreto of secretos) {
        assert.ok(
          !body.toLowerCase().includes(secreto.toLowerCase()),
          `la respuesta filtra material secreto ("${secreto.slice(0, 16)}…"): ${body}`,
        );
      }
    }

    // Sólo salen datos no secretos: dirección y clave pública/red.
    const eth = responses[1].json() as Record<string, unknown>;
    assert.equal(eth.address, referenceAddress(MNEMONIC_24, 0));
    assert.ok(isEip55(eth.address));
    assert.ok(account.accountId);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-06-01-06 (auditoría estática): `grep` sobre src/ confirma que el secreto no se logea', () => {
  // Ninguna llamada de logging/escritura a stdout-stderr menciona material secreto (RN-5).
  const logsConSecreto = grepSrc(
    '(console\\.(log|info|warn|error|debug|trace)|\\.log\\.(fatal|error|warn|info|debug|trace)|process\\.(stdout|stderr)\\.write)[^\\n]*(mnemonic|seed|privatekey|private_key|passphrase)',
  );
  assert.deepEqual(logsConSecreto, [], 'hay logging de material secreto en src/');

  // El sistema no serializa jamás una clave privada derivada: el término no aparece en src/
  // fuera de comentarios (la proyección pública `DerivedAccount` sólo tiene datos públicos).
  const privateKeyRefs = grepSrc('privatekey').filter((line) => {
    const code = line.slice(line.indexOf(':', line.indexOf(':') + 1) + 1).trim();
    return !code.startsWith('*') && !code.startsWith('//') && !code.startsWith('/*');
  });
  assert.deepEqual(privateKeyRefs, [], 'src/ manipula/serializa una clave privada nombrada');

  // Tampoco hay `console.*` (superficie de salida no controlada) en el código de producción.
  assert.deepEqual(grepSrc('console\\.(log|info|warn|error|debug|trace)'), []);
});

test('AT-06-01-06 (logs de una corrida de integración): stdout/stderr no contienen el secreto', async () => {
  const originalOut = process.stdout.write.bind(process.stdout);
  const originalErr = process.stderr.write.bind(process.stderr);
  const captured: string[] = [];
  const capture = (chunk: unknown): boolean => {
    captured.push(typeof chunk === 'string' ? chunk : String(chunk));
    return true;
  };

  let ctx: TestApp | undefined;
  try {
    // Nivel de log máximo: se registran todas las trazas de la corrida.
    (process.stdout as unknown as { write: unknown }).write = capture;
    (process.stderr as unknown as { write: unknown }).write = capture;
    ctx = createTestApp({ WALLET_MNEMONIC: MNEMONIC_24, LOG_LEVEL: 'trace' });
    const email = uniqueEmail();
    await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);
    await get(ctx.app, '/api/v1/deposit-address?asset=ETH', token);
    await get(ctx.app, '/api/v1/deposit-address?asset=USDC', token);
    await get(ctx.app, '/api/v1/deposit-address?asset=BTC', token);
  } finally {
    (process.stdout as unknown as { write: unknown }).write = originalOut;
    (process.stderr as unknown as { write: unknown }).write = originalErr;
    if (ctx) await ctx.cleanup();
  }

  const logs = captured.join('');
  const reference = referenceDerivation(MNEMONIC_24, 0);
  for (const secreto of [MNEMONIC_24, reference.seedHex, reference.privateKeyHex]) {
    assert.ok(
      !logs.toLowerCase().includes(secreto.toLowerCase()),
      'las trazas de la corrida filtran material secreto',
    );
  }
  assert.ok(!/"?(mnemonic|privateKey|seedHex)"?\s*[:=]/i.test(logs), 'las trazas nombran un secreto');
});

