test('AT-06-01-11: fallo de descifrado del seed ⇒ el arranque aborta (INTERNAL_ERROR) sin generar uno nuevo', async () => {
  const ctx = createTestApp();
  const dbPath = ctx.dbPath;
  try {
    await registerAccount(ctx.app, uniqueEmail());
    const blobOriginal = seedBlob(ctx.db);
    const filasOriginales = addressRows(ctx.db);
    await ctx.close();

    // (a) Credencial INCORRECTA: el tag GCM no verifica con otra clave.
    const otraClave = randomBytes(32).toString('hex');
    const errorClave = assert.throws(
      () => bootstrap(loadConfig(envFor(dbPath, otraClave))),
      ProvisioningError,
    ) as ProvisioningError;
    assert.equal(errorClave.code, 'INTERNAL_ERROR');
    assert.ok(!errorClave.message.includes('abandon'), 'el error filtra material secreto');

    // (b) Credencial AUSENTE: el arranque también aborta (falla la carga de configuración,
    //     `main.ts` lo traduce a salida ≠ 0). Nunca se continúa sin seed ni se regenera.
    assert.throws(
      () => loadConfig({ LOAD_DOTENV: 'false', DATABASE_PATH: dbPath, LOG_LEVEL: 'silent' }),
      ConfigError,
    );

    // (c) Tag GCM CORRUPTO (restauración incorrecta / almacenamiento dañado).
    const corrupto = Buffer.from(blobOriginal);
    corrupto[corrupto.length - 1] ^= 0xff;
    const db = openDatabase(dbPath);
    db.prepare('UPDATE wallet_seed SET payload = ? WHERE id = 1').run(corrupto);
    db.close();

    const errorTag = assert.throws(
      () => bootstrap(loadConfig(envFor(dbPath, ctx.encryptionKey))),
      ProvisioningError,
    ) as ProvisioningError;
    assert.equal(errorTag.code, 'INTERNAL_ERROR');

    // En ningún caso se generó un seed nuevo ni se tocó el mapeo cuenta → dirección.
    const post = openDatabase(dbPath);
    try {
      assert.equal(seedRowCount(post), 1, 'se persistió un seed adicional');
      assert.ok(seedBlob(post).equals(corrupto), 'el seed fue regenerado/sobrescrito');
      assert.deepEqual(addressRows(post), filasOriginales);
    } finally {
      post.close();
    }
  } finally {
    rmDir(dbPath);
  }
});

test('AT-06-01-12: atomicidad — nunca queda un seed parcialmente escrito', () => {
  // (a) El proceso muere ANTES del commit: al reiniciar el estado es "sin seed" y el
  //     provisioning se re-ejecuta correctamente generando un seed nuevo válido (RN-9).
  const crash = makeTempDb();
  try {
    const db = openDatabase(crash.dbPath);
    db.exec('BEGIN IMMEDIATE');
    db.prepare('INSERT INTO wallet_seed (id, payload, created_at) VALUES (1, ?, ?)').run(
      encodedSeedPayload(MNEMONIC_24, crash.key),
      new Date().toISOString(),
    );
    db.exec('ROLLBACK'); // el proceso murió durante la escritura
    db.close();

    const reabierta = openDatabase(crash.dbPath);
    try {
      assert.equal(seedRowCount(reabierta), 0, 'quedó un seed a medio escribir');
      const provisionado = provisionWallet({ db: reabierta, encryptionKey: crash.key });
      assert.equal(provisionado.generated, true);
      assert.equal(provisionado.seed.length, 64);
      // Y el seed reci n generado es completo y descifrable.
      const releido = provisionWallet({ db: reabierta, encryptionKey: crash.key });
      assert.equal(releido.generated, false);
      assert.ok(provisionado.seed.equals(releido.seed));
    } finally {
      reabierta.close();
    }
  } finally {
    rmDir(crash.dbPath);
  }

  // (b) Si el almacenamiento contuviera un blob TRUNCADO (escritura parcial), jamás se
  //     interpreta como un seed válido: el arranque aborta y no lo sobrescribe (RN-9/RN-11).
  const truncado = makeTempDb();
  try {
    const completo = encodedSeedPayload(MNEMONIC_24, truncado.key);
    const parcial = completo.subarray(0, completo.length - 6);
    const db = openDatabase(truncado.dbPath);
    try {
      db.prepare('INSERT INTO wallet_seed (id, payload, created_at) VALUES (1, ?, ?)').run(
        parcial,
        new Date().toISOString(),
      );
      const error = assert.throws(
        () => provisionWallet({ db, encryptionKey: truncado.key }),
        ProvisioningError,
      ) as ProvisioningError;
      assert.equal(error.code, 'INTERNAL_ERROR');
      assert.equal(seedRowCount(db), 1);
      assert.ok(seedBlob(db).equals(parcial), 'el seed parcial fue sobrescrito/regenerado');
    } finally {
      db.close();
    }
  } finally {
    rmDir(truncado.dbPath);
  }

  // (c) Camino normal: commit atómico ⇒ el seed queda completo y descifrable.
  const feliz = makeTempDb();
  try {
    const db = openDatabase(feliz.dbPath);
    try {
      const provisionado = provisionWallet({ db, encryptionKey: feliz.key });
      assert.equal(provisionado.generated, true);
      assert.equal(seedRowCount(db), 1);
      const blob = seedBlob(db);
      assert.ok(blob.length > 12 + 16, 'el blob incluye nonce(12) || ciphertext || tag(16)');
      assert.ok(provisionWallet({ db, encryptionKey: feliz.key }).seed.equals(provisionado.seed));
    } finally {
      db.close();
    }
  } finally {
    rmDir(feliz.dbPath);
  }
});

test('AT-06-01-13: smoke test de integridad — un seed que no deriva la dirección persistida aborta el arranque', async () => {
  const ctx = createTestApp({ WALLET_MNEMONIC: MNEMONIC_24 });
  const dbPath = ctx.dbPath;
  try {
    await registerAccount(ctx.app, uniqueEmail());
    await registerAccount(ctx.app, uniqueEmail());
    const filas = addressRows(ctx.db);
    assert.equal(filas.length, 2);
    // La dirección persistida del índice más bajo es la derivada del mnemonic real.
    assert.equal(filas[0].addressIndex, 0);
    assert.equal(filas[0].address, referenceAddress(MNEMONIC_24, 0));
    await ctx.close();

    // El harness inyecta OTRO seed (restauración incorrecta / corrupción): descifra bien,
    // pero no deriva la dirección persistida.
    const key = Buffer.from(ctx.encryptionKey, 'hex');
    const ajeno = encodedSeedPayload(MNEMONIC_24_AJENO, key);
    const db = openDatabase(dbPath);
    db.prepare('UPDATE wallet_seed SET payload = ? WHERE id = 1').run(ajeno);
    db.close();

    // El arranque se detiene con error crítico ANTES de procesar operaciones.
    const error = assert.throws(
      () => bootstrap(loadConfig(envFor(dbPath, ctx.encryptionKey))),
      ProvisioningError,
    ) as ProvisioningError;
    assert.equal(error.code, 'INTERNAL_ERROR');
    assert.match(error.message, /integridad/i);

    // No regeneró el seed ni asignó direcciones nuevas con el seed sospechoso.
    const post = openDatabase(dbPath);
    try {
      assert.equal(seedRowCount(post), 1);
      assert.ok(seedBlob(post).equals(ajeno));
      assert.deepEqual(addressRows(post), filas);

      // La verificación puntual (K = 1: el índice más bajo) también falla de forma directa.
      const seedAjeno = mnemonicToSeedSync(MNEMONIC_24_AJENO, '');
      assert.throws(() => verifySeedIntegrity(post, Buffer.from(seedAjeno)), ProvisioningError);
      // Con el seed correcto, en cambio, la verificación pasa.
      verifySeedIntegrity(post, Buffer.from(mnemonicToSeedSync(MNEMONIC_24, '')));
    } finally {
      post.close();
    }
  } finally {
    rmDir(dbPath);
  }
});

