test('AT-06-03-01: a una cuenta nueva se le asigna índice único/monótono y dirección EIP-55', async () => {
  const ctx = createTestApp();
  try {
    const account = await registerAccount(ctx.app, uniqueEmail());
    const registro = ctx.services.wallet.find(account.accountId);
    assert.ok(registro, 'la cuenta no tiene dirección asignada');
    assert.equal(registro.addressIndex, 0);
    assert.ok(Number.isInteger(registro.addressIndex) && registro.addressIndex >= 0);
    assert.ok(isEip55(registro.address), `checksum EIP-55 inválido: ${registro.address}`);
    assert.equal(registro.derivationPath, `m/44'/60'/0'/0/${registro.addressIndex}`);

    // La dirección queda asociada exclusivamente a esa cuenta.
    const filas = addressRows(ctx.db);
    assert.equal(filas.length, 1);
    assert.equal(filas[0].accountId, account.accountId);

    const otra = await registerAccount(ctx.app, uniqueEmail());
    const registroOtra = ctx.services.wallet.find(otra.accountId);
    assert.ok(registroOtra);
    assert.ok(registroOtra.addressIndex > registro.addressIndex, 'el índice no es monótono');
    assert.notEqual(registroOtra.address, registro.address);
  } finally {
    await ctx.cleanup();
  }
});

