test('AT-06-03-10: se emite el evento DepositAddressAssigned y la dirección es consultable internamente', async () => {
  const ctx = createTestApp();
  try {
    const recibidos: Record<string, unknown>[] = [];
    ctx.services.wallet.events.on(DEPOSIT_ADDRESS_ASSIGNED, (evento) => {
      recibidos.push(evento as Record<string, unknown>);
    });

    const cuenta = await registerAccount(ctx.app, uniqueEmail());
    const registro = ctx.services.wallet.find(cuenta.accountId);
    assert.ok(registro);

    assert.equal(recibidos.length, 1, 'no se emitió DepositAddressAssigned');
    assert.deepEqual(recibidos[0], {
      accountId: cuenta.accountId,
      addressIndex: registro.addressIndex,
      address: registro.address,
      chainId: CHAIN_ID,
    });

    // El evento también queda persistido (la épica 07 puede consumirlo al arrancar).
    const persistidos = ctx.services.wallet.listEvents();
    assert.equal(persistidos.length, 1);
    assert.deepEqual(persistidos[0], recibidos[0]);

    // Y la dirección está en el conjunto consultable internamente.
    const interno = await get(ctx.app, '/internal/deposit-addresses');
    assert.equal(interno.statusCode, 200);
    const body = interno.json() as { chainId: string; items: AddressRow[] };
    assert.equal(body.chainId, CHAIN_ID);
    assert.ok(
      body.items.some(
        (item) => item.accountId === cuenta.accountId && item.address === registro.address,
      ),
      'el monitor de la épica 07 no ve la dirección asignada',
    );
  } finally {
    await ctx.cleanup();
  }
});

