test('AT-06-04-03: sin credencial válida (ausente, inválida o expirada) ⇒ UNAUTHENTICATED (401)', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    const cuenta = await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);

    const sinToken = await get(ctx.app, '/api/v1/deposit-address?asset=ETH');
    const invalido = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', 'token-invalido');

    // Token expirado: se vence la sesión emitida.
    ctx.db
      .prepare('UPDATE sessions SET expires_at = ? WHERE account_id = ?')
      .run(new Date(Date.now() - 1000).toISOString(), cuenta.accountId);
    const expirado = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', token);

    for (const response of [sinToken, invalido, expirado]) {
      assert.equal(response.statusCode, 401);
      const body = response.json() as { error: { code: string } };
      assert.equal(body.error.code, 'UNAUTHENTICATED');
      // No se revela ninguna dirección.
      assert.ok(!/0x[0-9a-fA-F]{40}/.test(response.body), `se filtró una dirección: ${response.body}`);
    }
  } finally {
    await ctx.cleanup();
  }
});

test('AT-06-04-04: aislamiento — un accountId ajeno inyectado por query/body se ignora', async () => {
  const ctx = createTestApp();
  try {
    const emailA = uniqueEmail();
    const emailB = uniqueEmail();
    const a = await registerAccount(ctx.app, emailA);
    const b = await registerAccount(ctx.app, emailB);
    const tokenA = await loginToken(ctx.app, emailA);

    const direccionA = ctx.services.wallet.find(a.accountId)?.address;
    const direccionB = ctx.services.wallet.find(b.accountId)?.address;
    assert.ok(direccionA && direccionB && direccionA !== direccionB);

    // (a) selector inyectado por query
    const porQuery = await get(
      ctx.app,
      `/api/v1/deposit-address?asset=ETH&accountId=${encodeURIComponent(b.accountId)}`,
      tokenA,
    );
    // (b) selector inyectado por cuerpo
    const porBody = await ctx.app.inject({
      method: 'GET',
      url: '/api/v1/deposit-address?asset=ETH',
      headers: { authorization: `Bearer ${tokenA}`, 'content-type': 'application/json' },
      payload: JSON.stringify({ accountId: b.accountId }),
    });

    for (const response of [porQuery, porBody]) {
      assert.equal(response.statusCode, 200);
      const body = response.json() as Record<string, unknown>;
      assert.equal(body.address, direccionA, 'la respuesta no es la dirección del dueño del token');
      assert.ok(!response.body.includes(direccionB), 'se reveló la dirección de otra cuenta');
      assert.ok(!response.body.includes(b.accountId));
    }
  } finally {
    await ctx.cleanup();
  }
});

