test('AT-06-04-06: chainId distinto de Sepolia ⇒ CHAIN_ID_MISMATCH (422) con expected/got', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);

    const response = await get(ctx.app, '/api/v1/deposit-address?asset=ETH&chainId=1', token);
    assert.equal(response.statusCode, 422);
    const body = response.json() as {
      error: { code: string; details?: { expected?: unknown; got?: unknown } };
    };
    assert.equal(body.error.code, 'CHAIN_ID_MISMATCH');
    assert.equal(body.error.details?.expected, CHAIN_ID);
    assert.equal(body.error.details?.got, '1');
    assert.equal(typeof body.error.details?.expected, 'string');
    assert.equal(typeof body.error.details?.got, 'string');

    // Una red distinta de sepolia se rechaza igual (RN-4).
    const porRed = await get(ctx.app, '/api/v1/deposit-address?asset=ETH&network=mainnet', token);
    assert.equal(porRed.statusCode, 422);
    assert.equal((porRed.json() as { error: { code: string } }).error.code, 'CHAIN_ID_MISMATCH');

    // Precedencia RN-9: el esquema/activo se evalúa ANTES que la red.
    const ambos = await get(ctx.app, '/api/v1/deposit-address?asset=BTC&chainId=1', token);
    assert.equal(ambos.statusCode, 422);
    assert.equal((ambos.json() as { error: { code: string } }).error.code, 'VALIDATION_ERROR');
  } finally {
    await ctx.cleanup();
  }
});

test('AT-06-04-07: fallback — la primera consulta de una cuenta sin dirección la asigna con HTTP 200', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    const cuenta = await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);

    // Caso excepcional: la cuenta quedó sin dirección asignada.
    ctx.db.prepare('DELETE FROM deposit_addresses WHERE account_id = ?').run(cuenta.accountId);
    assert.equal(ctx.services.wallet.find(cuenta.accountId), undefined);

    const primera = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', token);
    assert.equal(primera.statusCode, 200, 'la asignación-fallback debe responder 200, no 201');
    const direccion = (primera.json() as Record<string, unknown>).address;
    assert.ok(isEip55(direccion));

    const segunda = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', token);
    assert.equal(segunda.statusCode, 200);
    assert.equal((segunda.json() as Record<string, unknown>).address, direccion);

    // Un solo índice asignado a la cuenta.
    assert.equal(addressRows(ctx.db).filter((f) => f.accountId === cuenta.accountId).length, 1);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-06-04-08: consultas repetidas (ETH y USDC) devuelven siempre la misma dirección y no mutan el índice', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    const cuenta = await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);
    const indiceInicial = ctx.services.wallet.find(cuenta.accountId)?.addressIndex;

    const direcciones = new Set<string>();
    for (const asset of ['ETH', 'USDC', 'ETH', 'USDC', 'ETH']) {
      const response = await get(ctx.app, `/api/v1/deposit-address?asset=${asset}`, token);
      assert.equal(response.statusCode, 200);
      direcciones.add((response.json() as Record<string, string>).address);
    }
    assert.equal(direcciones.size, 1, 'la dirección cambió entre consultas');
    assert.equal(ctx.services.wallet.find(cuenta.accountId)?.addressIndex, indiceInicial);
    assert.equal(addressRows(ctx.db).length, 1);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-06-04-09: dos consultas concurrentes del fallback asignan exactamente un índice', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    const cuenta = await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);
    ctx.db.prepare('DELETE FROM deposit_addresses WHERE account_id = ?').run(cuenta.accountId);

    const [a, b] = await Promise.all([
      get(ctx.app, '/api/v1/deposit-address?asset=ETH', token),
      get(ctx.app, '/api/v1/deposit-address?asset=USDC', token),
    ]);

    assert.equal(a.statusCode, 200);
    assert.equal(b.statusCode, 200);
    const direccionA = (a.json() as Record<string, string>).address;
    const direccionB = (b.json() as Record<string, string>).address;
    assert.equal(direccionA, direccionB, 'las dos consultas concurrentes devolvieron direcciones distintas');

    const filas = addressRows(ctx.db).filter((f) => f.accountId === cuenta.accountId);
    assert.equal(filas.length, 1, 'se asignaron dos índices a la misma cuenta');
    assert.equal(filas[0].address, direccionA);
  } finally {
    await ctx.cleanup();
  }
});
