test('AT-01-01-01: registro exitoso con credenciales válidas (201, ACTIVE, balances internos en 0)', async () => {
  const ctx = createTestApp();
  try {
    const before = Date.now();
    const response = await post(ctx.app, REGISTER_URL, {
      email: 'trader@example.com',
      password: 'Sup3rSecreta',
    });

    assert.equal(response.statusCode, 201);
    const body = response.json() as Record<string, unknown>;
    assertAccountView(body, 'trader@example.com');
    assert.ok(Date.parse(body.createdAt as string) >= before - 1000);

    // RN-7 (no auto-login) + RNE-2 (sin secretos).
    assert.equal((body as { token?: unknown }).token, undefined);
    assertNoSecrets(response, ['Sup3rSecreta']);

    // RN-6/RNE-6: estado interno con balances disponible="0" y bloqueado="0" en ETH y USDC.
    const balances = ctx.services.accounts.repository.balancesOf(body.accountId as string);
    assert.deepEqual(
      balances.map((b) => ({ asset: b.asset, available: b.available, locked: b.locked })),
      [
        { asset: 'ETH', available: '0', locked: '0' },
        { asset: 'USDC', available: '0', locked: '0' },
      ],
    );
  } finally {
    await ctx.cleanup();
  }
});

test('AT-01-01-09: precedencia — formato de email prevalece sobre política de contraseña (un solo error)', async () => {
  const ctx = createTestApp();
  try {
    const response = await post(ctx.app, REGISTER_URL, { email: 'no-es-email', password: '123' });
    const error = assertErrorEnvelope(response, 'VALIDATION_ERROR', 422);
    const issues = issuesOf(error);
    // RN-9: nivel 2 (formato de email) antes que nivel 3 (política de password); un solo error.
    assert.equal(issues.length, 1, `se esperaba un solo issue: ${JSON.stringify(issues)}`);
    assert.equal(issues[0].field, 'email');
    assert.ok(
      !issues.some((i) => i.field === 'password'),
      'no debe reportarse la política de contraseña (nivel 3) antes que el email (nivel 2)',
    );
    assert.equal(countAccounts(ctx), 0);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-01-01-10: concurrencia — dos registros simultáneos con el mismo email dan 201 + 409', async () => {
  const ctx = createTestApp();
  try {
    const payload = { email: 'trader@example.com', password: VALID_PASSWORD };
    const [a, b] = await Promise.all([
      post(ctx.app, REGISTER_URL, payload),
      post(ctx.app, REGISTER_URL, payload),
    ]);

    const statuses = [a.statusCode, b.statusCode].sort();
    assert.deepEqual(statuses, [201, 409], `respuestas inesperadas: ${a.body} | ${b.body}`);

    const created = a.statusCode === 201 ? a : b;
    const rejected = a.statusCode === 201 ? b : a;
    assertErrorEnvelope(rejected, 'EMAIL_ALREADY_EXISTS', 409);

    const view = created.json() as Record<string, unknown>;
    assertAccountView(view, 'trader@example.com');

    // Una sola cuenta, completa y consultable (RN-8).
    assert.equal(countAccounts(ctx), 1);
    const stored = ctx.services.accounts.repository.findByEmail('trader@example.com');
    assert.ok(stored);
    assert.equal(stored!.accountId, view.accountId);
    assert.equal(stored!.status, 'ACTIVE');
    assert.match(stored!.createdAt, ISO_UTC);
    assert.ok(stored!.passwordHash.length > 0, 'la cuenta no puede quedar a medio crear');

    // Consultable de punta a punta: la cuenta autentica y opera.
    const token = await loginToken(ctx.app, 'trader@example.com');
    const protectedResponse = await get(ctx.app, PROTECTED_URL, token);
    assert.equal(protectedResponse.statusCode, 200, protectedResponse.body);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-01-01-11: la cuenta sobrevive al reinicio del sistema (INV-8)', async () => {
  let ctx = createTestApp();
  const tmpDir = path.dirname(ctx.dbPath);

