/**
 * Tests de aceptación de la ÉPICA 09 — API HTTP, en el ALCANCE IMPLEMENTADO de esta
 * corrida: contrato REST de los tres endpoints existentes (`POST /api/v1/auth/register`,
 * `POST /api/v1/auth/login`, `GET /api/v1/deposit-address`), autenticación/autorización y
 * modelo de errores.
 *
 * Cobertura de esta suite:
 *  - HU-09-01: AT-09-01-01, AT-09-01-02, AT-09-01-10, AT-09-01-15 y la parte aplicable de
 *              AT-09-01-16 (cuerpo que no es JSON válido ⇒ VALIDATION_ERROR 422 con
 *              `details.issues`).
 *  - HU-09-02: AT-09-02-01, AT-09-02-02, AT-09-02-03, AT-09-02-04, AT-09-02-11.
 *  - HU-09-05: AT-09-05-01, AT-09-05-04, AT-09-05-05, AT-09-05-08, AT-09-05-10, AT-09-05-11.
 *
 * AT fuera del alcance de esta corrida (NO se implementan aquí):
 *  - HU-09-01 AT-09-01-03..09, -11..14, -17..22: dependen de `/me`, `/balances`,
 *    `/movements`, `/orders`, `/trades`, `/deposits`, `/withdrawals` y `/market/*`, que no
 *    existen en esta etapa (épicas 02..05, 07, 08).
 *  - HU-09-01 AT-09-01-16 (segunda mitad): los casos de serialización monetaria
 *    (`priceMin` numérico, `quantityWei` negativo, `clientOrderId`) exigen `POST /orders`
 *    (épica 04), fuera de alcance.
 *  - HU-09-02 AT-09-02-05..08: aislamiento de listados y de acceso directo a órdenes y
 *    retiros (épicas 04 y 08, endpoints inexistentes en esta corrida).
 *  - HU-09-02 AT-09-02-09/10 y HU-09-05 AT-09-05-07: canal WebSocket (HU-09-03/09-04), no
 *    implementado en esta etapa.
 *  - HU-09-05 AT-09-05-02/03/06/12: requieren el alta de órdenes y los retiros
 *    (`INSUFFICIENT_FUNDS`, `INVALID_SIDE`, `WITHDRAWAL_BELOW_MIN`), fuera de alcance.
 *  - HU-09-05 AT-09-05-09: `INTERNAL_ERROR` (500) exige inyectar una falla interna no
 *    clasificada; no hay disparador alcanzable por la API en el alcance implementado.
 *
 * `AT-09-01-15` usa `PUT /api/v1/auth/login` como "método no permitido sobre ruta
 * existente" porque `/api/v1/balances` (el ejemplo de la spec) no existe en esta corrida.
 */

import test from 'node:test';
import assert from 'node:assert/strict';
import type { LightMyRequestResponse } from 'fastify';

import {
  createTestApp,
  get,
  post,
  registerAccount,
  loginToken,
  uniqueEmail,
  VALID_PASSWORD,
  type TestApp,
} from './helpers/testApp';

// ---------------------------------------------------------------------------
// Catálogo de errores (spec/00-fundaciones/modelo-de-errores.md §3), transcrito aquí para
// evaluar contra la SPEC y no contra la implementación (AT-09-05-11).
// ---------------------------------------------------------------------------
const CATALOGO_ERRORES: Record<string, number> = {
  // §3.1 Autenticación y autorización
  UNAUTHENTICATED: 401,
  UNAUTHORIZED: 403,
  RATE_LIMITED: 429,
  // §3.2 Validación general
  VALIDATION_ERROR: 422,
  NOT_FOUND: 404,
  METHOD_NOT_ALLOWED: 405,
  // §3.3 Trading: validación de órdenes
  INVALID_PRICE_TICK: 422,
  INVALID_LOT_SIZE: 422,
  BELOW_MIN_NOTIONAL: 422,
  INVALID_SIDE: 422,
  INVALID_ORDER_TYPE: 422,
  PRICE_REQUIRED: 422,
  PRICE_NOT_ALLOWED: 422,
  // §3.4 Trading: estado y ejecución
  INSUFFICIENT_FUNDS: 422,
  ORDER_NOT_FOUND: 404,
  ORDER_NOT_CANCELLABLE: 409,
  SELF_TRADE_BLOCKED: 422,
  MARKET_NO_LIQUIDITY: 422,
  MARKET_BUDGET_INSUFFICIENT: 422,
  DUPLICATE_CLIENT_ORDER_ID: 409,
  // §3.5 On-chain: depósitos y retiros
  INVALID_ADDRESS: 422,
  WITHDRAWAL_BELOW_MIN: 422,
  WITHDRAWAL_AMOUNT_INVALID: 422,
  DEPOSIT_ALREADY_CREDITED: 409,
  DEPOSIT_NOT_CONFIRMED: 409,
  CHAIN_ID_MISMATCH: 422,
  NONCE_CONFLICT: 409,
  BROADCAST_FAILED: 502,
  // §3.6 Cuentas
  EMAIL_ALREADY_EXISTS: 409,
  INVALID_CREDENTIALS: 401,
  ACCOUNT_NOT_FOUND: 404,
  // §3.7 Genéricos / sistema
  CONFLICT: 409,
  INTERNAL_ERROR: 500,
};

interface ErrorEnvelope {
  error: { code: string; message: string; details?: Record<string, unknown> };
}

/** Verifica el envelope uniforme de HU-09-05 RN-1 y devuelve su contenido. */
function assertErrorEnvelope(response: LightMyRequestResponse): ErrorEnvelope['error'] {
  const body = response.json() as ErrorEnvelope;
  assert.deepEqual(
    Object.keys(body),
    ['error'],
    `el cuerpo de error tiene claves de más: ${response.body}`,
  );
  assert.equal(typeof body.error, 'object');
  assert.equal(typeof body.error.code, 'string', 'falta `code`');
  assert.equal(typeof body.error.message, 'string', 'falta `message`');
  assert.ok(body.error.message.length > 0);
  for (const key of Object.keys(body.error)) {
    assert.ok(['code', 'message', 'details'].includes(key), `clave inesperada en error: ${key}`);
  }
  if (body.error.details !== undefined) {
    assert.equal(typeof body.error.details, 'object');
    assert.ok(body.error.details !== null && !Array.isArray(body.error.details));
  }
  // El `code` pertenece al catálogo y su status HTTP coincide exactamente (RN-2/RN-6).
  assert.ok(
    Object.prototype.hasOwnProperty.call(CATALOGO_ERRORES, body.error.code),
    `code fuera del catálogo: ${body.error.code}`,
  );
  assert.equal(
    response.statusCode,
    CATALOGO_ERRORES[body.error.code],
    `status HTTP de ${body.error.code} no coincide con el catálogo`,
  );
  return body.error;
}

const EIP55_RE = /^0x[0-9a-fA-F]{40}$/;

/** Setea variables de entorno del proceso y devuelve el restaurador. */
function withProcessEnv(vars: Record<string, string>): () => void {
  const previos = new Map<string, string | undefined>();
  for (const [key, value] of Object.entries(vars)) {
    previos.set(key, process.env[key]);
    process.env[key] = value;
  }
  return () => {
    for (const [key, value] of previos) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
  };
}

async function authedApp(): Promise<{ ctx: TestApp; token: string; accountId: string }> {
  const ctx = createTestApp();
  const email = uniqueEmail();
  const account = await registerAccount(ctx.app, email);
  const token = await loginToken(ctx.app, email);
  return { ctx, token, accountId: account.accountId };
}

// ===========================================================================
// HU-09-01 — Contrato REST
// ===========================================================================

test('AT-09-01-01: POST /api/v1/auth/register ⇒ 201 con { accountId, email, status, createdAt }', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    const response = await post(ctx.app, '/api/v1/auth/register', {
      email,
      password: VALID_PASSWORD,
    });

    assert.equal(response.statusCode, 201);
    assert.match(String(response.headers['content-type']), /application\/json/);
    const body = response.json() as Record<string, unknown>;
    assert.deepEqual(Object.keys(body).sort(), ['accountId', 'createdAt', 'email', 'status']);
    assert.equal(body.email, email.toLowerCase());
    assert.equal(body.status, 'ACTIVE');
    assert.equal(typeof body.accountId, 'string');
    assert.equal(typeof body.createdAt, 'string');
    assert.ok(!Number.isNaN(Date.parse(body.createdAt as string)), 'createdAt ISO-8601 UTC');

    // No se expone la contraseña ni hash alguno.
    assert.ok(!response.body.includes(VALID_PASSWORD));
    assert.ok(!/password|hash|scrypt|salt/i.test(response.body), response.body);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-09-01-02: POST /api/v1/auth/login ⇒ 200 con token usable como Bearer; credenciales incorrectas ⇒ INVALID_CREDENTIALS (401)', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    await registerAccount(ctx.app, email);

    const ok = await post(ctx.app, '/api/v1/auth/login', { email, password: VALID_PASSWORD });
    assert.equal(ok.statusCode, 200);
    const body = ok.json() as Record<string, unknown>;
    assert.equal(typeof body.token, 'string');
    assert.ok((body.token as string).length > 0);

    // El token es utilizable como `Authorization: Bearer <token>` en un recurso protegido.
    const protegido = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', body.token as string);
    assert.equal(protegido.statusCode, 200);

    // Contraseña incorrecta y email inexistente son indistinguibles (no revela existencia).
    const passMal = await post(ctx.app, '/api/v1/auth/login', { email, password: 'OtraClave123' });
    const emailInexistente = await post(ctx.app, '/api/v1/auth/login', {
      email: uniqueEmail(),
      password: VALID_PASSWORD,
    });
    for (const response of [passMal, emailInexistente]) {
      assert.equal(response.statusCode, 401);
      assert.equal(assertErrorEnvelope(response).code, 'INVALID_CREDENTIALS');
    }
    assert.equal(passMal.body, emailInexistente.body, 'la respuesta revela si el email existe');
  } finally {
    await ctx.cleanup();
  }
});

test('AT-09-01-10: GET /api/v1/deposit-address?asset=ETH ⇒ 200 con { asset, address } EIP-55; ?asset=BTC ⇒ VALIDATION_ERROR (422)', async () => {
  const { ctx, token } = await authedApp();
  try {
    const response = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', token);
    assert.equal(response.statusCode, 200);
    const body = response.json() as Record<string, unknown>;
    assert.equal(body.asset, 'ETH');
    assert.match(String(body.address), EIP55_RE);
    // El cuerpo mínimo exigido por el contrato está presente.
    assert.ok('asset' in body && 'address' in body);

    const btc = await get(ctx.app, '/api/v1/deposit-address?asset=BTC', token);
    assert.equal(btc.statusCode, 422);
    assert.equal(assertErrorEnvelope(btc).code, 'VALIDATION_ERROR');
  } finally {
    await ctx.cleanup();
  }
});

test('AT-09-01-15: ruta inexistente ⇒ NOT_FOUND (404); método no permitido sobre ruta existente ⇒ METHOD_NOT_ALLOWED (405) con details { method, allowed }', async () => {
  const ctx = createTestApp();
  try {
    const inexistente = await get(ctx.app, '/api/v1/foo');
    assert.equal(inexistente.statusCode, 404);
    assert.equal(assertErrorEnvelope(inexistente).code, 'NOT_FOUND');

    // `/api/v1/balances` no existe en esta corrida: se usa una ruta existente del alcance.
    const put = await ctx.app.inject({
      method: 'PUT',
      url: '/api/v1/auth/login',
      headers: { 'content-type': 'application/json' },
      payload: JSON.stringify({ email: uniqueEmail(), password: VALID_PASSWORD }),
    });
    assert.equal(put.statusCode, 405);
    const error = assertErrorEnvelope(put);
    assert.equal(error.code, 'METHOD_NOT_ALLOWED');
    assert.equal(error.details?.method, 'PUT');
    assert.ok(Array.isArray(error.details?.allowed), 'details.allowed debe ser la lista de verbos');
    assert.deepEqual(error.details?.allowed, ['POST']);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-09-01-16 (aplicable): cuerpo que no es JSON válido ⇒ VALIDATION_ERROR (422) con details.issues', async () => {
  const ctx = createTestApp();
  try {
    for (const payload of ['esto-no-es-json', '{"email": ', '[1,2', '{email: "a@b.com"}']) {
      const response = await ctx.app.inject({
        method: 'POST',
        url: '/api/v1/auth/register',
        headers: { 'content-type': 'application/json' },
        payload,
      });
      assert.equal(response.statusCode, 422, `payload ${payload}`);
      const error = assertErrorEnvelope(response);
      assert.equal(error.code, 'VALIDATION_ERROR');
      const issues = error.details?.issues as { field: string; message: string }[] | undefined;
