test('AT-09-02-03: token inválido, esquema no Bearer o token expirado ⇒ UNAUTHENTICATED (401) sin revelar el motivo', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    const cuenta = await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);

    const invalido = await ctx.app.inject({
      method: 'GET',
      url: '/api/v1/deposit-address?asset=ETH',
      headers: { authorization: 'Bearer xxx-invalido' },
    });
    const esquemaAjeno = await ctx.app.inject({
