test('AT-09-02-11 / AT-09-05-08: rate limit por cuenta y endpoint ⇒ 429 RATE_LIMITED con details.retryAfterSeconds y header Retry-After', async () => {
  // NOTA: `loadConfig` lee las variables de rate limit de `process.env` (no del `env` que
  // recibe por parámetro), por lo que el override se hace sobre `process.env`. Es un bug de
  // `src/core/config.ts`, fuera del alcance editable de esta tarea; se reporta aparte.
  const restore = withProcessEnv({ API_RATE_LIMIT_MAX: '5', API_RATE_LIMIT_WINDOW_SECONDS: '60' });
  let ctx: TestApp | undefined;
  try {
    ctx = createTestApp();
    assert.equal(ctx.config.apiRateLimit.max, 5, 'no se aplicó el umbral de test');
    const emailA = uniqueEmail();
    const emailB = uniqueEmail();
    await registerAccount(ctx.app, emailA);
    await registerAccount(ctx.app, emailB);
    const tokenA = await loginToken(ctx.app, emailA);
    const tokenB = await loginToken(ctx.app, emailB);

    for (let i = 0; i < 5; i += 1) {
      const ok = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', tokenA);
      assert.equal(ok.statusCode, 200, `la request ${i + 1} no debía limitarse`);
    }
    const limitada = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', tokenA);
    assert.equal(limitada.statusCode, 429);
    const error = assertErrorEnvelope(limitada);
    assert.equal(error.code, 'RATE_LIMITED');
    assert.ok(
      Number.isInteger(error.details?.retryAfterSeconds),
      `details.retryAfterSeconds debe ser entero: ${JSON.stringify(error.details)}`,
    );
    assert.ok((error.details?.retryAfterSeconds as number) > 0);
    assert.ok(limitada.headers['retry-after'] !== undefined, 'falta el header Retry-After');
    assert.equal(
      String(limitada.headers['retry-after']),
      String(error.details?.retryAfterSeconds),
    );

    // El límite es POR CUENTA: otra cuenta no queda afectada.
    const otraCuenta = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', tokenB);
    assert.equal(otraCuenta.statusCode, 200);
  } finally {
    restore();
    if (ctx) await ctx.cleanup();
  }
});

