test('AT-06-03-05: concurrencia — 20 asignaciones simultáneas producen exactamente los índices {0..19}', async () => {
  const ctx = createTestApp();
  try {
    assert.equal(addressRows(ctx.db).length, 0, 'el sistema no arrancó en estado limpio');
    const N = 20;
    const emails = Array.from({ length: N }, () => uniqueEmail());
    // Las 20 altas (que disparan la asignación eager) se lanzan en el mismo ciclo.
    const respuestas = await Promise.all(
      emails.map((email) => registerAccount(ctx.app, email)),
    );
    assert.equal(respuestas.length, N);

    const filas = addressRows(ctx.db);
    assert.equal(filas.length, N);
    const indices = filas.map((f) => f.addressIndex).sort((a, b) => a - b);
    assert.deepEqual(indices, Array.from({ length: N }, (_, i) => i));
    const direcciones = new Set(filas.map((f) => f.address));
    assert.equal(direcciones.size, N, 'hay direcciones repetidas');
    const cuentas = new Set(filas.map((f) => f.accountId));
    assert.equal(cuentas.size, N, 'hay cuentas con más de una asignación');
  } finally {
    await ctx.cleanup();
  }
});

test('AT-06-03-06: persistencia — tras el reinicio cada cuenta conserva índice y dirección', async () => {
  const first = createTestApp();
  let second: TestApp | undefined;
  try {
    for (let i = 0; i < 4; i += 1) await registerAccount(first.app, uniqueEmail());
    const antes = addressRows(first.db);
    assert.equal(antes.length, 4);
    await first.close();

    second = restartTestApp(first);
    const despues = addressRows(second.db);
    assert.deepEqual(despues, antes);
    for (const fila of antes) {
      const registro = second.services.wallet.find(fila.accountId);
      assert.ok(registro);
      assert.equal(registro.addressIndex, fila.addressIndex);
      assert.equal(registro.address, fila.address);
    }
  } finally {
    if (second) await second.cleanup();
    else await first.cleanup();
  }
});

