test('AT-06-04-07: fallback — la primera consulta de una cuenta sin dirección la asigna con HTTP 200', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    const cuenta = await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);

    // Caso excepcional: la cuenta quedó sin dirección asignada.
    ctx.db.prepare('DELETE FROM deposit_addresses WHERE account_id = ?').run(cuenta.accountId);
    assert.equal(ctx.services.wallet.find(cuenta.accountId), undefined);

    const primera = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', token);
    assert.equal(primera.statusCode, 200, 'la asignación-fallback debe responder 200, no 201');
    const direccion = (primera.json() as Record<string, unknown>).address;
    assert.ok(isEip55(direccion));

    const segunda = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', token);
    assert.equal(segunda.statusCode, 200);
    assert.equal((segunda.json() as Record<string, unknown>).address, direccion);

    // Un solo índice asignado a la cuenta.
    assert.equal(addressRows(ctx.db).filter((f) => f.accountId === cuenta.accountId).length, 1);
  } finally {
    await ctx.cleanup();
  }
});

