/**
 * Servicio de cuentas: registro (HU-01-01) e inicio de sesión (HU-01-02).
 *
 * Las precedencias de validación son deterministas y se reporta **un solo error** por
 * respuesta (RNE-7 / modelo-de-errores.md §4).
 */
import { randomUUID } from 'node:crypto';
import { AppError, validationError, type ValidationIssue } from '../../core/errors';
import { dummyVerify, hashPassword, verifyPassword } from '../../core/password';
import { nowIso } from '../../core/time';
import {
  EMAIL_MAX_LENGTH,
  PASSWORD_MAX_LENGTH,
  PASSWORD_MIN_LENGTH,
  isValidEmailFormat,
  normalizeEmail,
} from '../../core/validation';
import { isUniqueConstraintError, transaction, type Db } from '../../db/index';
import type { AuditLog } from '../../core/audit';
import { AccountRepository } from './repository';
import type { SessionService } from './sessions';

/** Proyección pública de una cuenta (nunca incluye password, hash ni sal — RNE-2). */
export interface AccountView {
  accountId: string;
  email: string;
  status: string;
  createdAt: string;
}

export interface LoginResult {
  token: string;
  tokenType: 'Bearer';
  expiresAt: string;
}

/** Contrato mínimo con la épica 06: asignación eager de dirección al alta (HU-06-03 RN-12). */
export interface DepositAddressAssigner {
  /** Se ejecuta **dentro** de la transacción de alta de la cuenta. */
  assignForAccountInTransaction(accountId: string): void;
  /** Se ejecuta después del commit: publica el evento de dominio. */
  publishPendingEvents(): void;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Paso 1 de la precedencia: esquema/tipos/campos requeridos/campos desconocidos
 * (HU-01-01 RN-4/RN-9).
 */
export function parseRegisterPayload(body: unknown): { email: string; password: string } {
  if (!isPlainObject(body)) {
    throw validationError([{ field: 'body', message: 'El cuerpo debe ser un objeto JSON.' }]);
  }
  const issues: ValidationIssue[] = [];
  const allowed = new Set(['email', 'password']);
  for (const key of Object.keys(body)) {
    if (!allowed.has(key)) {
      issues.push({ field: key, message: 'Campo desconocido.' });
    }
  }
  if (!('email' in body)) {
    issues.push({ field: 'email', message: 'Campo requerido faltante.' });
  } else if (typeof body.email !== 'string') {
    issues.push({ field: 'email', message: 'Debe ser un string.' });
  }
  if (!('password' in body)) {
    issues.push({ field: 'password', message: 'Campo requerido faltante.' });
  } else if (typeof body.password !== 'string') {
    issues.push({ field: 'password', message: 'Debe ser un string.' });
  }
  if (issues.length > 0) throw validationError(issues);
  return { email: body.email as string, password: body.password as string };
}

/** Paso 1 del login: sólo tipos (HU-01-02 RN-7/RN-11: no se valida el formato del email). */
export function parseLoginPayload(body: unknown): { email: string; password: string } {
  if (!isPlainObject(body)) {
    throw validationError([{ field: 'body', message: 'El cuerpo debe ser un objeto JSON.' }]);
  }
  const issues: ValidationIssue[] = [];
  if (!('email' in body)) {
    issues.push({ field: 'email', message: 'Campo requerido faltante.' });
  } else if (typeof body.email !== 'string') {
    issues.push({ field: 'email', message: 'Debe ser un string.' });
  }
  if (!('password' in body)) {
    issues.push({ field: 'password', message: 'Campo requerido faltante.' });
  } else if (typeof body.password !== 'string') {
    issues.push({ field: 'password', message: 'Debe ser un string.' });
  }
  if (issues.length > 0) throw validationError(issues);
  return { email: body.email as string, password: body.password as string };
}

export class AccountService {
  private readonly accounts: AccountRepository;

  constructor(
    private readonly db: Db,
    private readonly sessions: SessionService,
    private readonly audit: AuditLog,
    private readonly addressAssigner: DepositAddressAssigner,
  ) {
    this.accounts = new AccountRepository(db);
  }

  get repository(): AccountRepository {
    return this.accounts;
  }

  /** HU-01-01: alta de cuenta. Devuelve la proyección pública (sin secretos). */
  async register(body: unknown, origin: string | null): Promise<AccountView> {
    // Paso 1: esquema.
    const payload = parseRegisterPayload(body);
    // Paso 2: formato de email (sobre el email normalizado, RN-1/RN-2).
    const email = normalizeEmail(payload.email);
    if (!isValidEmailFormat(email)) {
      this.audit.record({
        event: 'REGISTER',
        email,
        result: 'FAILURE',
        reason: 'VALIDATION_ERROR',
        origin,
      });
      throw validationError([
        {
          field: 'email',
          message: `Formato de email inválido o de más de ${EMAIL_MAX_LENGTH} caracteres.`,
        },
      ]);
    }
    // Paso 3: política de contraseña.
    if (
      payload.password.length < PASSWORD_MIN_LENGTH ||
      payload.password.length > PASSWORD_MAX_LENGTH
    ) {
      this.audit.record({
        event: 'REGISTER',
        email,
        result: 'FAILURE',
        reason: 'VALIDATION_ERROR',
        origin,
      });
      throw validationError([
        {
          field: 'password',
          message: `La contraseña debe tener entre ${PASSWORD_MIN_LENGTH} y ${PASSWORD_MAX_LENGTH} caracteres.`,
        },
      ]);
    }

    const passwordHash = await hashPassword(payload.password);
    const account: AccountView & { passwordHash: string } = {
      accountId: randomUUID(), // opaco, no secuencial, 122 bits de entropía (RN-6 / RNE-6)
      email,
      status: 'ACTIVE',
      createdAt: nowIso(),
      passwordHash,
    };

    // Paso 4: unicidad. La restricción UNIQUE de la base resuelve también el caso
    // concurrente (RN-8): a lo sumo una inserción prospera.
    try {
      transaction(this.db, () => {
        this.accounts.insert({
          accountId: account.accountId,
          email: account.email,
          passwordHash,
          status: account.status,
          createdAt: account.createdAt,
        });
        this.accounts.insertInitialBalances(account.accountId);
        // Asignación eager de la dirección de depósito (HU-06-03 RN-12), en la misma
        // transacción: no existe una cuenta sin dirección observable.
        this.addressAssigner.assignForAccountInTransaction(account.accountId);
      });
    } catch (err) {
      if (isUniqueConstraintError(err)) {
        this.audit.record({
          event: 'REGISTER',
          email,
          result: 'FAILURE',
          reason: 'EMAIL_ALREADY_EXISTS',
          origin,
        });
        throw new AppError('EMAIL_ALREADY_EXISTS', 'Ya existe una cuenta con ese email.', {
          email,
        });
      }
      throw err;
    }

    this.addressAssigner.publishPendingEvents();
    this.audit.record({ event: 'REGISTER', email, result: 'SUCCESS', origin });

    return {
      accountId: account.accountId,
      email: account.email,
      status: account.status,
      createdAt: account.createdAt,
    };
  }

  /** HU-01-02: verificación de credenciales y emisión del token de sesión. */
  async login(body: unknown, origin: string | null): Promise<LoginResult> {
    // Paso 1: esquema (sin validar el formato del email — RN-11).
    const payload = parseLoginPayload(body);
    const email = normalizeEmail(payload.email);
    const account = this.accounts.findByEmail(email);

    let ok = false;
    if (account) {
      ok = await verifyPassword(payload.password, account.passwordHash);
    } else {
      // Email inexistente: se ejecuta un KDF dummy de coste equivalente para que la
      // latencia no permita enumerar cuentas (RN-12 / RNE-3).
      await dummyVerify(payload.password);
    }

    if (!account || !ok) {
      this.audit.record({
        event: 'LOGIN',
        email,
        result: 'FAILURE',
        reason: 'INVALID_CREDENTIALS',
        origin,
      });
      // Respuesta idéntica tanto si el email no existe como si la contraseña es
      // incorrecta, y sin `details` discriminante (RN-2).
      throw new AppError('INVALID_CREDENTIALS', 'Credenciales inválidas.');
    }

    const session = this.sessions.issue(account.accountId);
    this.audit.record({ event: 'LOGIN', email, result: 'SUCCESS', origin });
    return { token: session.token, tokenType: 'Bearer', expiresAt: session.expiresAt };
  }
}
/** Acceso a datos de cuentas (HU-01-01). */
import type { Db } from '../../db/index';

export interface AccountRow {
  accountId: string;
  email: string;
  passwordHash: string;
  status: string;
  createdAt: string;
}

export const ASSETS = ['ETH', 'USDC'] as const;
export type Asset = (typeof ASSETS)[number];

export class AccountRepository {
  constructor(private readonly db: Db) {}

  findByEmail(normalizedEmail: string): AccountRow | undefined {
    return this.db
      .prepare(
        'SELECT account_id AS accountId, email, password_hash AS passwordHash, status, created_at AS createdAt FROM accounts WHERE email = ?',
      )
      .get(normalizedEmail) as AccountRow | undefined;
  }

  findById(accountId: string): AccountRow | undefined {
    return this.db
      .prepare(
        'SELECT account_id AS accountId, email, password_hash AS passwordHash, status, created_at AS createdAt FROM accounts WHERE account_id = ?',
      )
      .get(accountId) as AccountRow | undefined;
  }

  exists(accountId: string): boolean {
    return this.findById(accountId) !== undefined;
  }

  /** Inserta la cuenta. Lanza si el email ya existe (UNIQUE), lo que resuelve RN-8. */
  insert(row: AccountRow): void {
    this.db
      .prepare(
        'INSERT INTO accounts (account_id, email, password_hash, status, created_at) VALUES (?, ?, ?, ?, ?)',
      )
      .run(row.accountId, row.email, row.passwordHash, row.status, row.createdAt);
  }

  /** Estado inicial de balances: disponible "0" y bloqueado "0" por activo (HU-01-01 RN-6). */
  insertInitialBalances(accountId: string): void {
    const stmt = this.db.prepare(
      "INSERT INTO account_balances (account_id, asset, available, locked) VALUES (?, ?, '0', '0')",
    );
    for (const asset of ASSETS) stmt.run(accountId, asset);
  }

  /** Lectura interna del estado de balances (no hay superficie HTTP en esta etapa). */
  balancesOf(accountId: string): { asset: string; available: string; locked: string }[] {
    return this.db
      .prepare('SELECT asset, available, locked FROM account_balances WHERE account_id = ? ORDER BY asset')
      .all(accountId) as unknown as { asset: string; available: string; locked: string }[];
  }
}

