/**
 * Configuración del backend, leída del entorno y validada al arranque.
 *
 * Una configuración inválida **impide el arranque** (no se inicia el servicio en estado
 * inválido): HU-01-02 RN-3 (rango del TTL) y HU-06-01 RN-6/RN-11 (credencial de cifrado).
 */
import * as fs from 'node:fs';
import * as path from 'node:path';

/** Red única del proyecto: Sepolia (spec/00-fundaciones/activos-y-par-de-trading.md §1). */
export const CHAIN_ID = '11155111';
export const NETWORK_NAME = 'sepolia';
/** Confirmaciones requeridas (constante fundacional; la consumen las épicas 07/08). */
export const CONFIRMACIONES_REQUERIDAS = 12;

export class ConfigError extends Error {}

export interface RateLimitPolicy {
  enabled: boolean;
  max: number;
  windowSeconds: number;
}

export interface Config {
  host: string;
  port: number;
  databasePath: string;
  /** TTL del token de sesión en segundos; entero en [60, 86400] (HU-01-02 RN-3). */
  sessionTtlSeconds: number;
  /**
   * Clave AES-256-GCM (32 bytes) para el cifrado en reposo del seed (HU-06-01 RN-6).
   * Es obligatoria para operar; su ausencia se resuelve en el provisioning (no aquí) para
   * poder distinguir "no hay seed todavía" (`VALIDATION_ERROR`) de "hay un seed que no se
   * puede descifrar" (`INTERNAL_ERROR`, AT-06-01-11).
   */
  walletEncryptionKey?: Buffer;
  /** Mnemonic importado por configuración (opcional); si falta, se genera uno nuevo. */
  walletMnemonic?: string;
  walletMnemonicPassphrase: string;
  /** Dirección del contrato USDC-mock del entorno (checksum EIP-55). */
  usdcContractAddress: string;
  /** Endpoint JSON-RPC de Sepolia (opcional en esta etapa; sin default de terceros). */
  ethRpcUrl: string;
  /** Rate limit por cuenta y endpoint para endpoints autenticados (HU-09-02 RN-12). */
  apiRateLimit: RateLimitPolicy;
  /** Anti-flood del registro (HU-01-01 RN-10); desactivado salvo configuración explícita. */
  registerRateLimit: RateLimitPolicy;
  /** Anti-fuerza-bruta del login sobre intentos fallidos (HU-01-02 RN-9). */
  loginRateLimit: RateLimitPolicy;
  /** Token para las rutas internas (`/internal/*`); si falta, sólo se admite loopback. */
  internalApiToken?: string;
  logLevel: string;
}

function readEnvFile(file: string): void {
  if (!fs.existsSync(file)) return;
  const content = fs.readFileSync(file, 'utf8');
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"') && value.length >= 2) ||
      (value.startsWith("'") && value.endsWith("'") && value.length >= 2)
    ) {
      value = value.slice(1, -1);
    }
    if (process.env[key] === undefined) process.env[key] = value;
  }
}

function parseIntStrict(value: string, name: string): number {
  if (!/^-?\d+$/.test(value.trim())) {
    throw new ConfigError(`${name} debe ser un entero; se recibió "${value}".`);
  }
  return Number.parseInt(value.trim(), 10);
}

function parseBool(value: string | undefined, fallback: boolean): boolean {
  if (value === undefined || value.trim() === '') return fallback;
  const v = value.trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(v)) return true;
  if (['0', 'false', 'no', 'off'].includes(v)) return false;
  throw new ConfigError(`Valor booleano inválido: "${value}".`);
}

function decodeKey(raw: string): Buffer {
  const value = raw.trim();
  let buf: Buffer;
  if (/^(0x)?[0-9a-fA-F]{64}$/.test(value)) {
    buf = Buffer.from(value.replace(/^0x/, ''), 'hex');
  } else {
    buf = Buffer.from(value, 'base64');
  }
  if (buf.length !== 32) {
    throw new ConfigError(
      'WALLET_ENCRYPTION_KEY debe ser una clave de 32 bytes (64 hex o 44 caracteres base64). ' +
        'Podés generar una con: npm run genkey',
    );
  }
  return buf;
}

function rateLimitFrom(
  env: NodeJS.ProcessEnv,
  enabledVar: string,
  maxVar: string,
  windowVar: string,
  defaults: RateLimitPolicy,
): RateLimitPolicy {
  const enabled = parseBool(env[enabledVar], defaults.enabled);
  if (!enabled) return { enabled: false, max: defaults.max, windowSeconds: defaults.windowSeconds };
  // Cuando el rate limiting está activo, umbral y ventana son obligatorios y declarados
  // en la configuración del entorno (HU-01-01 RN-10).
  const rawMax = env[maxVar];
  const rawWindow = env[windowVar];
  const max = rawMax !== undefined && rawMax !== '' ? parseIntStrict(rawMax, maxVar) : defaults.max;
  const windowSeconds =
    rawWindow !== undefined && rawWindow !== ''
      ? parseIntStrict(rawWindow, windowVar)
      : defaults.windowSeconds;
  if (max <= 0) throw new ConfigError(`${maxVar} debe ser un entero positivo.`);
  if (windowSeconds <= 0) throw new ConfigError(`${windowVar} debe ser un entero positivo.`);
  return { enabled: true, max, windowSeconds };
}

/**
 * Dirección por defecto del USDC-mock en Sepolia. Es un parámetro del despliegue
 * (spec/00-fundaciones/activos-y-par-de-trading.md §2.2): se sobreescribe con
 * `USDC_CONTRACT_ADDRESS`.
 */
export const DEFAULT_USDC_CONTRACT_ADDRESS = '0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238';

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  if (parseBool(env.LOAD_DOTENV, true)) {
    readEnvFile(path.resolve(process.cwd(), '.env'));
  }

  const port = env.PORT ? parseIntStrict(env.PORT, 'PORT') : 3000;
  if (port < 0 || port > 65535) throw new ConfigError('PORT fuera de rango.');

  const sessionTtlSeconds = env.SESSION_TTL_SECONDS
    ? parseIntStrict(env.SESSION_TTL_SECONDS, 'SESSION_TTL_SECONDS')
    : 3600;
  // HU-01-02 RN-3: TTL entero positivo en [60, 86400]; fuera de rango => no se arranca.
  if (sessionTtlSeconds < 60 || sessionTtlSeconds > 86400) {
    throw new ConfigError(
      `SESSION_TTL_SECONDS debe ser un entero en el rango [60, 86400]; se recibió ${sessionTtlSeconds}.`,
    );
  }

  const rawKey = env.WALLET_ENCRYPTION_KEY;

  const chainIdEnv = (env.CHAIN_ID ?? CHAIN_ID).trim();
  if (chainIdEnv !== CHAIN_ID) {
    throw new ConfigError(
      `La única red soportada es Sepolia (chainId ${CHAIN_ID}); se configuró ${chainIdEnv}.`,
    );
  }

  return {
    host: env.HOST?.trim() || '0.0.0.0',
    port,
    databasePath: env.DATABASE_PATH?.trim() || path.resolve(process.cwd(), 'data', 'exchange.db'),
    sessionTtlSeconds,
    walletEncryptionKey: rawKey && rawKey.trim() !== '' ? decodeKey(rawKey) : undefined,
    walletMnemonic: env.WALLET_MNEMONIC?.trim() ? env.WALLET_MNEMONIC.trim() : undefined,
    walletMnemonicPassphrase: env.WALLET_MNEMONIC_PASSPHRASE ?? '',
    usdcContractAddress: env.USDC_CONTRACT_ADDRESS?.trim() || DEFAULT_USDC_CONTRACT_ADDRESS,
    ethRpcUrl: env.ETH_RPC_URL?.trim() || '',
    apiRateLimit: rateLimitFrom(
      env,
      'API_RATE_LIMIT_ENABLED',
      'API_RATE_LIMIT_MAX',
      'API_RATE_LIMIT_WINDOW_SECONDS',
      // HU-09-02 RN-12: 60 requests por minuto, por cuenta y por endpoint.
      { enabled: true, max: 60, windowSeconds: 60 },
    ),
    registerRateLimit: rateLimitFrom(
      env,
      'REGISTER_RATE_LIMIT_ENABLED',
      'REGISTER_RATE_LIMIT_MAX',
      'REGISTER_RATE_LIMIT_WINDOW_SECONDS',
      // HU-01-01 RN-10: opcional; desactivado salvo configuración explícita del entorno.
      { enabled: false, max: 20, windowSeconds: 60 },
    ),
    loginRateLimit: rateLimitFrom(
      env,
      'LOGIN_RATE_LIMIT_ENABLED',
      'LOGIN_RATE_LIMIT_MAX_FAILURES',
      'LOGIN_RATE_LIMIT_WINDOW_SECONDS',
      // HU-01-02 RN-9: opcional; cuenta intentos fallidos por (origen, email).
      { enabled: false, max: 5, windowSeconds: 60 },
    ),
    internalApiToken: env.INTERNAL_API_TOKEN?.trim() || undefined,
    logLevel: env.LOG_LEVEL?.trim() || 'info',
  };
}
/**
 * Composición de la aplicación: abre la base, provisiona/carga la wallet HD, arma los
 * servicios y construye el servidor HTTP. Lo usan tanto `main.ts` como los tests.
 */
import type { FastifyInstance } from 'fastify';
import type { Config } from './core/config';
import { AuditLog } from './core/audit';
import { openDatabase, type Db } from './db/index';
import { AccountService } from './modules/accounts/service';
import { SessionService } from './modules/accounts/sessions';
import { WalletService } from './modules/wallet/service';
import { provisionWallet, verifySeedIntegrity } from './modules/wallet/seedStore';
import { buildApp } from './http/app';

export interface Services {
  accounts: AccountService;
  sessions: SessionService;
  wallet: WalletService;
  audit: AuditLog;
}

export interface BootstrappedApp {
  app: FastifyInstance;
  db: Db;
  services: Services;
  seed: Buffer;
  close(): Promise<void>;
}

export function createServices(config: Config, db: Db, seed: Buffer): Services {
  // El eco por `stderr` del log de auditoría se silencia sólo cuando el logging está
  // apagado (entorno de tests); la persistencia del log ocurre siempre (RNE-9).
  const audit = new AuditLog(db, config.logLevel !== 'silent');
  const sessions = new SessionService(db, config.sessionTtlSeconds);
  const wallet = new WalletService(db, seed);
  const accounts = new AccountService(db, sessions, audit, wallet);
  return { accounts, sessions, wallet, audit };
}

export function bootstrap(config: Config): BootstrappedApp {
  const db = openDatabase(config.databasePath);
  const provisioned = provisionWallet({
    db,
    encryptionKey: config.walletEncryptionKey,
    importedMnemonic: config.walletMnemonic,
    passphrase: config.walletMnemonicPassphrase,
  });
  // Smoke test de integridad del seed contra el mapeo persistido (HU-06-01 RN-10).
  verifySeedIntegrity(db, provisioned.seed);
  const services = createServices(config, db, provisioned.seed);
  const app = buildApp({ config, db, ...services });
  return {
    app,
    db,
    services,
    seed: provisioned.seed,
    async close() {
      await app.close();
      db.close();
    },
  };
}
/**
 * Punto de entrada del backend.
 *
 * Secuencia de arranque:
 *  1. Carga y validación de configuración (TTL de sesión, credencial de cifrado, red).
 *  2. Apertura de la base persistente.
 *  3. Provisioning/carga del seed HD y **smoke test de integridad** (HU-06-01 RN-10).
 *  4. Verificación opcional del endpoint JSON-RPC configurado (chainId 11155111).
 *  5. Levantado del servidor HTTP.
 *
 * Cualquier fallo de (1)–(3) **aborta** con código de salida distinto de cero y el `code`
 * del catálogo en `stderr`, sin filtrar material secreto (HU-06-01 RN-11).
 */
import { ConfigError, loadConfig, CHAIN_ID } from './core/config';
import { warmUpDummyHash } from './core/password';
import { ProvisioningError } from './modules/wallet/seedStore';
import { JsonRpcClient } from './chain/rpc';
import { bootstrap, type BootstrappedApp } from './bootstrap';

function abort(code: string, message: string): never {
  process.stderr.write(`${JSON.stringify({ fatal: { code, message } })}\n`);
  process.exit(1);
}

async function main(): Promise<void> {
  let config;
  try {
    config = loadConfig();
  } catch (err) {
    if (err instanceof ConfigError) abort('VALIDATION_ERROR', err.message);
    throw err;
  }

  let booted: BootstrappedApp;
  try {
    booted = bootstrap(config);
  } catch (err) {
    if (err instanceof ProvisioningError) abort(err.code, err.message);
    throw err;
  }

  const rpc = new JsonRpcClient(config.ethRpcUrl);
  if (rpc.configured) {
    try {
      const chainId = await rpc.chainId();
      if (chainId !== CHAIN_ID) {
        abort(
          'CHAIN_ID_MISMATCH',
          `El endpoint JSON-RPC configurado reporta chainId ${chainId}; se esperaba ${CHAIN_ID}.`,
        );
      }
      process.stdout.write(`JSON-RPC verificado: chainId ${chainId} (sepolia).\n`);
    } catch (err) {
      if (err instanceof Error && err.name === 'ProvisioningError') throw err;
      process.stderr.write(
        `Aviso: no se pudo contactar el endpoint JSON-RPC configurado (${(err as Error).message}). ` +
          'El backend arranca igual: esta etapa no ejecuta operaciones on-chain.\n',
      );
    }
  }

  await warmUpDummyHash();

  await booted.app.listen({ host: config.host, port: config.port });

  const shutdown = async (): Promise<void> => {
    await booted.close();
    process.exit(0);
  };
  process.on('SIGINT', () => void shutdown());
  process.on('SIGTERM', () => void shutdown());
}

void main().catch((err) => {
  process.stderr.write(`${JSON.stringify({ fatal: { code: 'INTERNAL_ERROR', message: (err as Error).message } })}\n`);
  process.exit(1);
});
/**
 * Persistencia (INV-8). Se usa SQLite a través del módulo estándar `node:sqlite`, de modo
 * que no hace falta compilar dependencias nativas ni levantar un servidor de base de datos.
 *
 * Todas las escrituras que deben ser atómicas se ejecutan dentro de una transacción
 * (`transaction()`), y `node:sqlite` es síncrono: una transacción se ejecuta completa en un
 * único tick del event loop, por lo que ninguna otra request puede intercalarse.
 */
import { DatabaseSync } from 'node:sqlite';
import * as fs from 'node:fs';
import * as path from 'node:path';

export type Db = DatabaseSync;

const SCHEMA = `
CREATE TABLE IF NOT EXISTS accounts (
  account_id    TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  status        TEXT NOT NULL,
  created_at    TEXT NOT NULL
);

-- Estado inicial de balances de una cuenta (HU-01-01 RN-6 / RNE-6): disponible y bloqueado
-- en "0" para ETH y USDC. El modelo de balances y su superficie de API son de la épica 02
-- (fuera del alcance de esta etapa); aquí sólo se materializa el estado inicial.
CREATE TABLE IF NOT EXISTS account_balances (
  account_id TEXT NOT NULL REFERENCES accounts(account_id),
  asset      TEXT NOT NULL,
  available  TEXT NOT NULL DEFAULT '0',
  locked     TEXT NOT NULL DEFAULT '0',
  PRIMARY KEY (account_id, asset)
);

CREATE TABLE IF NOT EXISTS sessions (
  token_hash TEXT PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES accounts(account_id),
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  revoked_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_sessions_account ON sessions(account_id);

-- Seed HD cifrado en reposo con AES-256-GCM: nonce(12) || ciphertext || tag(16).
CREATE TABLE IF NOT EXISTS wallet_seed (
  id         INTEGER PRIMARY KEY CHECK (id = 1),
  payload    BLOB NOT NULL,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS deposit_addresses (
  account_id      TEXT PRIMARY KEY REFERENCES accounts(account_id),
  address_index   INTEGER NOT NULL UNIQUE,
  address         TEXT NOT NULL UNIQUE,
  derivation_path TEXT NOT NULL,
  network         TEXT NOT NULL,
  chain_id        TEXT NOT NULL,
  created_at      TEXT NOT NULL
);

-- Auditoría de índices BIP-32 saltados por clave inválida (HU-06-02 RN-8 / HU-06-03 RN-1).
CREATE TABLE IF NOT EXISTS derivation_skips (
  address_index INTEGER PRIMARY KEY,
  reason        TEXT NOT NULL,
  created_at    TEXT NOT NULL
);

-- Eventos de dominio internos (HU-06-03 RN-11: DepositAddressAssigned).
CREATE TABLE IF NOT EXISTS domain_events (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  type       TEXT NOT NULL,
  payload    TEXT NOT NULL,
  created_at TEXT NOT NULL
);

-- Log de auditoría interno de autenticación (RNE-9). No es consultable por el usuario final.
CREATE TABLE IF NOT EXISTS auth_audit_log (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  timestamp  TEXT NOT NULL,
  event      TEXT NOT NULL,
  email      TEXT,
  result     TEXT NOT NULL,
  reason     TEXT,
  origin     TEXT
);
`;

export function openDatabase(databasePath: string): Db {
  if (databasePath !== ':memory:') {
    fs.mkdirSync(path.dirname(path.resolve(databasePath)), { recursive: true });
  }
  const db = new DatabaseSync(databasePath);
  db.exec('PRAGMA journal_mode = WAL');
  db.exec('PRAGMA synchronous = FULL');
  db.exec('PRAGMA foreign_keys = ON');
  db.exec('PRAGMA busy_timeout = 5000');
  db.exec(SCHEMA);
  return db;
}

/** Ejecuta `fn` dentro de una transacción; revierte por completo ante cualquier excepción. */
export function transaction<T>(db: Db, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      /* la transacción ya no estaba abierta */
    }
    throw err;
  }
}

export function isUniqueConstraintError(err: unknown): boolean {
  const message = err instanceof Error ? err.message : String(err);
  return /UNIQUE constraint failed/i.test(message);
}
/**
 * Log de auditoría interno de eventos de autenticación (RNE-9).
 *
 * Es **interno**: no se expone por la API del usuario final, por lo que su existencia no
 * viola la regla de no-enumeración de cuentas (RNE-3). Se persiste en la base y además se
 * emite por `stderr` en formato JSON para inspección operativa. Nunca registra la
 * contraseña, su hash, ni el token emitido (RNE-2 / HU-09-02 RN-11).
 */
import type { Db } from '../db/index';
import { nowIso } from './time';

export type AuditEvent = 'REGISTER' | 'LOGIN';
export type AuditResult = 'SUCCESS' | 'FAILURE';

export interface AuditRecord {
  timestamp: string;
  event: AuditEvent;
  email: string | null;
  result: AuditResult;
  reason?: string | null;
  origin?: string | null;
}

export class AuditLog {
  constructor(private readonly db: Db, private readonly echoToStderr = true) {}

  record(entry: Omit<AuditRecord, 'timestamp'> & { timestamp?: string }): void {
    const timestamp = entry.timestamp ?? nowIso();
    this.db
      .prepare(
        'INSERT INTO auth_audit_log (timestamp, event, email, result, reason, origin) VALUES (?, ?, ?, ?, ?, ?)',
      )
      .run(
        timestamp,
        entry.event,
        entry.email,
        entry.result,
        entry.reason ?? null,
        entry.origin ?? null,
      );
    if (this.echoToStderr) {
      process.stderr.write(
        JSON.stringify({ audit: { ...entry, timestamp } }) + '\n',
      );
    }
  }

  /** Sólo para inspección interna / tests (no hay superficie HTTP para esto). */
  list(limit = 100): AuditRecord[] {
    return this.db
      .prepare('SELECT timestamp, event, email, result, reason, origin FROM auth_audit_log ORDER BY id DESC LIMIT ?')
      .all(limit) as unknown as AuditRecord[];
  }
}
/**
 * Cliente JSON-RPC mínimo contra el endpoint configurable de la red
 * (`ETH_RPC_URL`). La red es única: Sepolia, chainId 11155111 (INV-6).
 *
 * En esta etapa el backend no envía transacciones (las épicas 07/08 están fuera de
 * alcance); el cliente se usa para verificar, al arrancar, que el endpoint configurado
 * apunta efectivamente a Sepolia.
 */
export interface JsonRpcResponse<T> {
  jsonrpc: '2.0';
  id: number | string;
  result?: T;
  error?: { code: number; message: string };
}

export class JsonRpcError extends Error {}

export class JsonRpcClient {
  private nextId = 1;

  constructor(private readonly url: string, private readonly timeoutMs = 5000) {}

  get configured(): boolean {
    return this.url !== '';
  }

  async call<T>(method: string, params: unknown[] = []): Promise<T> {
    if (!this.configured) throw new JsonRpcError('No hay endpoint JSON-RPC configurado.');
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
    try {
      const response = await fetch(this.url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', id: this.nextId++, method, params }),
        signal: controller.signal,
      });
      if (!response.ok) throw new JsonRpcError(`HTTP ${response.status} del nodo JSON-RPC.`);
      const payload = (await response.json()) as JsonRpcResponse<T>;
      if (payload.error) throw new JsonRpcError(payload.error.message);
      return payload.result as T;
    } finally {
      clearTimeout(timer);
    }
  }

  /** `eth_chainId` devuelto como entero decimal en string (nunca float). */
  async chainId(): Promise<string> {
    const hex = await this.call<string>('eth_chainId');
    return BigInt(hex).toString(10);
  }

  async blockNumber(): Promise<string> {
    const hex = await this.call<string>('eth_blockNumber');
    return BigInt(hex).toString(10);
  }
}
/** Timestamps ISO 8601 en UTC (RNE-8 / HU-09-01 RN-15). */
export function nowIso(): string {
  return new Date().toISOString();
}

export function isoFromEpochMs(epochMs: number): string {
  return new Date(epochMs).toISOString();
}

