 83	// Constantes de dominio
 84	// ---------------------------------------------------------------------------
 85	
 86	/** Offset de los índices hardened de BIP-32: `0x80000000` = 2^31 (HU-06-02 RN-2). */
 87	export const HARDENED_OFFSET = 0x80000000;
 88	
 89	/** Último `address_index` válido del espacio no-hardened: 2^31 - 1 (HU-06-02 RN-9). */
 90	export const MAX_ADDRESS_INDEX = HARDENED_OFFSET - 1;
 91	
 92	/** Entropía fijada por el proyecto: 256 bits => 24 palabras (HU-06-01 RN-1). */
 93	const MNEMONIC_ENTROPY_BITS = 256;
 94	
 95	/** Cantidad de palabras exigida por el proyecto (HU-06-01 RN-1/RN-2 (a)). */
 96	const MNEMONIC_WORD_COUNT = 24;
 97	
 98	/** Orden del grupo de secp256k1 (`n`), HU-06-02 RN-1. */
 99	const SECP256K1_N: bigint = BigInt(
100	  '0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141'
101	);
102	
103	/** Componentes del path BIP-44 de Ethereum (HU-06-02 RN-2). */
104	const BIP44_PURPOSE = 44;
105	const BIP44_COIN_TYPE_ETHEREUM = 60; // SLIP-44 (00-fundaciones/activos-y-par-de-trading.md)
106	const BIP44_ACCOUNT = 0;
107	const BIP44_CHANGE = 0; // cadena externa, NO hardened
108	
109	/** Clave HMAC de la derivación de la clave maestra BIP-32 (HU-06-02 RN-1). */
110	const BIP32_MASTER_KEY = 'Bitcoin seed';
111	
112	/** Iteraciones y longitud del PBKDF2 de BIP-39 (HU-06-01 RN-3). */
113	const PBKDF2_ITERATIONS = 2048;
114	const SEED_BYTES = 64;
