116	// ---------------------------------------------------------------------------
117	// Helpers de bytes / enteros (aritmética exacta con BigInt, nunca floats)
118	// ---------------------------------------------------------------------------
119	
120	const utf8 = (s: string): Uint8Array => new Uint8Array(Buffer.from(s, 'utf8'));
121	
122	function bytesToHex(bytes: Uint8Array): string {
123	  let out = '';
124	  for (let i = 0; i < bytes.length; i++) out += bytes[i].toString(16).padStart(2, '0');
125	  return out;
126	}
127	
128	function bytesToBigIntBE(bytes: Uint8Array): bigint {
129	  let n = 0n;
130	  for (let i = 0; i < bytes.length; i++) n = (n << 8n) | BigInt(bytes[i]);
131	  return n;
132	}
133	
134	/** `ser256(k)`: entero de 256 bits en big-endian, 32 bytes (BIP-32). */
135	function ser256(value: bigint): Uint8Array {
136	  const out = new Uint8Array(32);
137	  let v = value;
138	  for (let i = 31; i >= 0; i--) {
139	    out[i] = Number(v & 0xffn);
140	    v >>= 8n;
141	  }
142	  return out;
143	}
144	
145	/** `ser32(i)`: entero de 32 bits sin signo en big-endian, 4 bytes (BIP-32). */
146	function ser32(index: number): Uint8Array {
147	  const out = new Uint8Array(4);
148	  out[0] = (index >>> 24) & 0xff;
149	  out[1] = (index >>> 16) & 0xff;
150	  out[2] = (index >>> 8) & 0xff;
151	  out[3] = index & 0xff;
152	  return out;
153	}
154	
155	function concatBytes(...parts: Uint8Array[]): Uint8Array {
156	  const total = parts.reduce((acc, p) => acc + p.length, 0);
157	  const out = new Uint8Array(total);
158	  let offset = 0;
159	  for (const p of parts) {
160	    out.set(p, offset);
161	    offset += p.length;
162	  }
163	  return out;
164	}
