167	// BIP-39: mnemonic y seed
168	// ---------------------------------------------------------------------------
169	
170	let wordSetCache: Set<string> | null = null;
171	function englishWordSet(): Set<string> {
172	  if (wordSetCache === null) wordSetCache = new Set<string>(ENGLISH_WORDLIST);
173	  return wordSetCache;
174	}
175	
176	/**
177	 * Genera un mnemonic BIP-39 de 24 palabras (256 bits de entropía) usando el CSPRNG del
178	 * sistema (HU-06-01 RN-1). No se registra ni se retorna nada más: el llamador es responsable
179	 * de custodiarlo (RN-5/RN-6).
180	 */
181	export function generateMnemonic24(): string {
182	  return bip39GenerateMnemonic(ENGLISH_WORDLIST, MNEMONIC_ENTROPY_BITS);
183	}
184	
185	/**
186	 * Normaliza el mnemonic a Unicode NFKD y colapsa los espacios en blanco a un único espacio
187	 * simple, recortando extremos (HU-06-01 RN-2). Para el wordlist inglés (ASCII puro) la NFKD
188	 * es un no-op, pero se aplica de forma genérica por conformidad con el estándar y robustez
189	 * ante mnemonics importados de sistemas con otra normalización.
190	 */
191	export function normalizeMnemonic(mnemonic: string): string {
192	  if (typeof mnemonic !== 'string') {
193	    throw new MnemonicValidationError('el mnemonic debe ser una cadena de texto');
194	  }
195	  return mnemonic.normalize('NFKD').trim().replace(/\s+/g, ' ');
196	}
197	
198	/**
199	 * Valida el mnemonic conforme a HU-06-01 RN-2, en este orden:
200	 *   (a) longitud = exactamente 24 palabras (entropía fijada del proyecto: 256 bits);
201	 *   (b) todas las palabras pertenecen al wordlist BIP-39 inglés (2048 palabras);
202	 *   (c) checksum BIP-39 (últimos ENT/32 bits = primeros ENT/32 bits de SHA-256(entropía)).
203	 *
204	 * Lanza `MnemonicValidationError` (equivalente a `VALIDATION_ERROR`) sin incluir el mnemonic
205	 * ni ninguna palabra suya en el mensaje (RN-5).
206	 */
207	export function validateMnemonic24(mnemonic: string): void {
208	  const normalized = normalizeMnemonic(mnemonic);
209	  const words = normalized.length === 0 ? [] : normalized.split(' ');
210	
211	  // (a) longitud
212	  if (words.length !== MNEMONIC_WORD_COUNT) {
213	    throw new MnemonicValidationError(
214	      `mnemonic inválido: se esperaban ${MNEMONIC_WORD_COUNT} palabras (256 bits de entropía) ` +
215	        `y se recibieron ${words.length}`
216	    );
217	  }
218	
219	  // (b) wordlist
220	  const dictionary = englishWordSet();
221	  for (let i = 0; i < words.length; i++) {
222	    if (!dictionary.has(words[i])) {
223	      // Se reporta solo la POSICIÓN, nunca la palabra (custodia RN-5).
224	      throw new MnemonicValidationError(
225	        `mnemonic inválido: la palabra en la posición ${i + 1} no pertenece al wordlist BIP-39 inglés`
226	      );
227	    }
228	  }
229	
230	  // (c) checksum
231	  if (!bip39ValidateMnemonic(normalized, ENGLISH_WORDLIST)) {
232	    throw new MnemonicValidationError('mnemonic inválido: el checksum BIP-39 no verifica');
233	  }
234	}
235	
236	/**
237	 * Deriva la seed binaria de 512 bits (64 bytes) según HU-06-01 RN-3:
238	 * `PBKDF2(HMAC-SHA512, password = mnemonic_NFKD, salt = "mnemonic" + passphrase_NFKD,
239	 *  iteraciones = 2048, dkLen = 64)`.
240	 *
241	 * Función pura y determinista (RN-7). NO valida la longitud del mnemonic: es el algoritmo
242	 * puro de BIP-39, usado también con vectores canónicos de 12 palabras (HU-06-02). La
243	 * validación de provisioning es responsabilidad de `validateMnemonic24`.
244	 */
245	export function mnemonicToSeed(mnemonic: string, passphrase = ''): Buffer {
246	  const password = normalizeMnemonic(mnemonic);
247	  // La passphrase se normaliza NFKD pero NO se colapsan sus espacios: son significativos.
248	  const salt = 'mnemonic' + passphrase.normalize('NFKD');
249	  const derived = noblePbkdf2(sha512, utf8(password), utf8(salt), {
250	    c: PBKDF2_ITERATIONS,
251	    dkLen: SEED_BYTES,
252	  });
253	  return Buffer.from(derived);
254	}
