256	// ---------------------------------------------------------------------------
257	// EIP-55 / dirección Ethereum
258	// ---------------------------------------------------------------------------
259	
260	const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/;
261	
262	/**
263	 * Codifica 20 bytes como dirección Ethereum con checksum EIP-55 (HU-06-02 RN-4).
264	 *
265	 * Acepta `Uint8Array`/`Buffer` de 20 bytes o un string hexadecimal de 40 dígitos, con o sin
266	 * prefijo `0x` y en cualquier caja. El algoritmo computa `Keccak-256` sobre la cadena ASCII
267	 * del hexadecimal en minúsculas (sin `0x`) y pasa a mayúscula el dígito `i` si el nibble `i`
268	 * del hash es >= 8.
269	 */
270	export function toChecksumAddress(address: string | Uint8Array): string {
271	  let lower: string;
272	  if (typeof address === 'string') {
273	    const raw = address.startsWith('0x') || address.startsWith('0X') ? address.slice(2) : address;
274	    if (!/^[0-9a-fA-F]{40}$/.test(raw)) {
275	      throw new Error('dirección inválida: se esperan 40 dígitos hexadecimales (20 bytes)');
276	    }
277	    lower = raw.toLowerCase();
278	  } else {
279	    if (!(address instanceof Uint8Array) || address.length !== 20) {
280	      throw new Error('dirección inválida: se esperan exactamente 20 bytes');
281	    }
282	    lower = bytesToHex(address);
283	  }
284	
285	  const hash = keccak_256(utf8(lower));
286	  let out = '0x';
287	  for (let i = 0; i < lower.length; i++) {
288	    const ch = lower[i];
289	    // nibble i del hash: byte i>>1, mitad alta si i es par.
290	    const nibble = i % 2 === 0 ? hash[i >> 1] >> 4 : hash[i >> 1] & 0x0f;
291	    out += nibble >= 8 ? ch.toUpperCase() : ch;
292	  }
293	  return out;
294	}
295	
296	/**
297	 * `true` si `address` es `0x` + 40 hex con checksum EIP-55 correcto.
298	 *
299	 * Nota deliberada sobre las formas sin caja mixta: una dirección **enteramente en minúsculas**
300	 * o **enteramente en mayúsculas** devuelve `false`, porque no transporta un checksum EIP-55
301	 * verificable (EIP-55 las considera "sin checksum"; que coincidan con la forma canónica sería
302	 * casualidad). Único caso en que esta regla no aplica: direcciones sin ningún dígito
303	 * alfabético (`a`-`f`), donde minúsculas y mayúsculas son la misma cadena y el checksum sí es
304	 * verificable de forma no ambigua; ahí se compara contra la forma canónica.
305	 */
306	export function isValidChecksumAddress(address: string): boolean {
307	  if (typeof address !== 'string' || !ADDRESS_RE.test(address)) return false;
308	  const body = address.slice(2);
309	  const hasCase = body.toLowerCase() !== body.toUpperCase();
310	  if (hasCase && (body === body.toLowerCase() || body === body.toUpperCase())) return false;
311	  return toChecksumAddress(body) === address;
312	}
