314	// ---------------------------------------------------------------------------
315	// BIP-32 / BIP-44
316	// ---------------------------------------------------------------------------
317	
318	/**
319	 * Punto de inyección para tests (AT-06-02-08): permite sustituir el HMAC-SHA512 usado por la
320	 * derivación BIP-32 para simular la condición de clave inválida (`I_L >= n` o `k_hijo == 0`,
321	 * probabilidad ~2^-127, no reproducible naturalmente).
322	 */
323	export interface DerivationDeps {
324	  hmacSha512?: (key: Uint8Array, data: Uint8Array) => Uint8Array;
325	}
326	
327	const defaultHmacSha512 = (key: Uint8Array, data: Uint8Array): Uint8Array =>
328	  hmac(sha512, key, data);
329	
330	/** Nodo extendido BIP-32 (privado). Nunca se expone fuera del módulo (RN-6). */
331	interface ExtendedKey {
332	  /** Clave privada como entero; permanece en memoria del módulo. */
333	  readonly k: bigint;
334	  readonly chainCode: Uint8Array;
335	}
336	
337	/** `serP(point(k))`: clave pública comprimida (33 bytes) de la clave privada `k`. */
338	function compressedPublicKey(k: bigint): Uint8Array {
339	  return secp256k1.Point.BASE.multiply(k).toBytes(true);
340	}
341	
342	/** Clave pública sin comprimir sin el prefijo `0x04`: `X || Y` (64 bytes). */
343	function uncompressedXY(k: bigint): Uint8Array {
344	  return secp256k1.Point.BASE.multiply(k).toBytes(false).subarray(1);
345	}
346	
347	/**
348	 * Clave maestra BIP-32 (HU-06-02 RN-1):
349	 * `I = HMAC-SHA512("Bitcoin seed", seed)`, `k = I[0:32]`, `c = I[32:64]`, con `1 <= k < n`.
350	 */
351	function masterKeyFromSeed(seed: Uint8Array, hmacSha512: DerivationDeps['hmacSha512']): ExtendedKey {
352	  if (!(seed instanceof Uint8Array) || seed.length < 16 || seed.length > 64) {
353	    throw new Error('seed inválida: se esperan entre 16 y 64 bytes');
354	  }
355	  const I = (hmacSha512 ?? defaultHmacSha512)(utf8(BIP32_MASTER_KEY), seed);
356	  const k = bytesToBigIntBE(I.subarray(0, 32));
357	  if (k === 0n || k >= SECP256K1_N) {
358	    // BIP-32: seed inutilizable (probabilidad ~2^-127). No se filtra material secreto.
359	    throw new Error('BIP-32: la seed produce una clave maestra inválida (I_L fuera de [1, n-1])');
360	  }
361	  return { k, chainCode: I.subarray(32, 64) };
362	}
363	
364	/**
365	 * `CKDpriv` de BIP-32 (HU-06-02 RN-3):
366	 *  - hardened (`i >= 2^31`): `I = HMAC-SHA512(c_par, 0x00 || ser256(k_par) || ser32(i))`
367	 *  - normal   (`i <  2^31`): `I = HMAC-SHA512(c_par, serP(point(k_par)) || ser32(i))`
368	 *  - `k_hijo = (I_L + k_par) mod n`, `c_hijo = I_R`.
369	 *
370	 * Si `I_L >= n` o `k_hijo == 0`, el índice es inválido (RN-8) y se lanza
371	 * `InvalidChildKeyError` para que el llamador avance al índice siguiente.
372	 */
373	function ckdPriv(
374	  parent: ExtendedKey,
375	  index: number,
376	  hmacSha512: DerivationDeps['hmacSha512']
377	): ExtendedKey {
378	  const data =
379	    index >= HARDENED_OFFSET
380	      ? concatBytes(new Uint8Array([0x00]), ser256(parent.k), ser32(index))
381	      : concatBytes(compressedPublicKey(parent.k), ser32(index));
382	
383	  const I = (hmacSha512 ?? defaultHmacSha512)(parent.chainCode, data);
384	  const IL = bytesToBigIntBE(I.subarray(0, 32));
385	  if (IL >= SECP256K1_N) {
386	    throw new InvalidChildKeyError(`BIP-32: I_L >= n en el índice ${index}`);
387	  }
388	  const k = (IL + parent.k) % SECP256K1_N;
389	  if (k === 0n) {
390	    throw new InvalidChildKeyError(`BIP-32: k_hijo == 0 en el índice ${index}`);
391	  }
392	  return { k, chainCode: I.subarray(32, 64) };
393	}
394	
395	/** Índice hardened: `value + 2^31` (HU-06-02 RN-2). */
396	function hardened(value: number): number {
397	  return value + HARDENED_OFFSET;
398	}
399	
400	/**
401	 * Ruta BIP-44 de Ethereum para un `address_index`: `m/44'/60'/0'/0/${addressIndex}`
402	 * (HU-06-02 RN-2). Los índices efectivos de los componentes hardened son
403	 * 2147483692 (44'), 2147483708 (60') y 2147483648 (0'); `change` y `address_index` son
404	 * no-hardened.
405	 */
406	export function derivationPathFor(addressIndex: number): string {
407	  return `m/${BIP44_PURPOSE}'/${BIP44_COIN_TYPE_ETHEREUM}'/${BIP44_ACCOUNT}'/${BIP44_CHANGE}/${addressIndex}`;
408	}
409	
410	/**
411	 * Nodo `m/44'/60'/0'/0` (la "cadena externa" de la cuenta 0), común a todos los índices.
412	 * Se calcula una sola vez por derivación / barrido de índices.
413	 */
414	function externalChainNode(seed: Uint8Array, hmacSha512: DerivationDeps['hmacSha512']): ExtendedKey {
415	  let node = masterKeyFromSeed(seed, hmacSha512);
416	  const path = [
417	    hardened(BIP44_PURPOSE), // 2147483692
418	    hardened(BIP44_COIN_TYPE_ETHEREUM), // 2147483708
419	    hardened(BIP44_ACCOUNT), // 2147483648
420	    BIP44_CHANGE, // 0 (no hardened)
421	  ];
422	  for (const index of path) node = ckdPriv(node, index, hmacSha512);
423	  return node;
424	}
425	
426	/** Valida el rango no-hardened del `address_index` (HU-06-02 RN-9), ANTES de derivar. */
427	function assertAddressIndexInRange(addressIndex: number): void {
428	  if (
429	    typeof addressIndex !== 'number' ||
430	    !Number.isInteger(addressIndex) ||
431	    addressIndex < 0 ||
432	    addressIndex > MAX_ADDRESS_INDEX
433	  ) {
434	    throw new AddressIndexRangeError(
435	      `address_index inválido: debe ser un entero en [0, ${MAX_ADDRESS_INDEX}] ` +
436	        `(espacio no-hardened de BIP-32); se recibió ${addressIndex}`
437	    );
438	  }
439	}
440	
441	/** Cuenta derivada: solo datos NO secretos (HU-06-02 RN-6). */
442	export interface DerivedAccount {
443	  addressIndex: number;
444	  /** Dirección Ethereum con checksum EIP-55. */
445	  address: string;
446	  /** Path BIP-44 efectivamente usado. */
447	  derivationPath: string;
448	  /** Clave pública comprimida (33 bytes) en hex con prefijo `0x`. Dato NO secreto. */
449	  publicKey: string;
450	}
451	
452	/** Construye el resultado público a partir del nodo hijo (la clave privada no sale de aquí). */
453	function toDerivedAccount(child: ExtendedKey, addressIndex: number): DerivedAccount {
454	  // RN-4: dirección = últimos 20 bytes de Keccak-256(X || Y) con la pública SIN comprimir.
455	  const addressBytes = keccak_256(uncompressedXY(child.k)).subarray(12);
456	  return {
457	    addressIndex,
458	    address: toChecksumAddress(addressBytes),
459	    derivationPath: derivationPathFor(addressIndex),
460	    publicKey: '0x' + bytesToHex(compressedPublicKey(child.k)),
461	  };
462	}
463	
464	/**
465	 * Deriva la cuenta del `address_index` dado sobre `m/44'/60'/0'/0/<addressIndex>`.
466	 *
467	 * Función pura de `(seed, addressIndex)` (HU-06-02 RN-5). Valida el rango
468	 * `[0, 2^31 - 1]` ANTES de derivar (RN-9 => `AddressIndexRangeError`). Nunca expone ni
469	 * logea la clave privada (RN-6).
470	 *
471	 * Si ese índice concreto cae en el borde de BIP-32 (`I_L >= n` o `k_hijo == 0`, RN-8) lanza
472	 * `DerivationExhaustedError`; para avanzar automáticamente al índice siguiente usar
473	 * `deriveAccountFromIndexOrNext`.
474	 */
475	export function deriveAccount(
476	  seed: Uint8Array,
477	  addressIndex: number,
478	  deps?: DerivationDeps
479	): DerivedAccount {
480	  assertAddressIndexInRange(addressIndex);
481	  const hmacSha512 = deps?.hmacSha512;
482	  const parent = externalChainNode(seed, hmacSha512);
483	  try {
484	    return toDerivedAccount(ckdPriv(parent, addressIndex, hmacSha512), addressIndex);
485	  } catch (err) {
486	    if (err instanceof InvalidChildKeyError) {
487	      throw new DerivationExhaustedError(
488	        `el address_index ${addressIndex} produce una clave BIP-32 inválida (RN-8)`
489	      );
490	    }
491	    throw err;
492	  }
493	}
494	
495	/**
496	 * Igual que `deriveAccount`, pero implementa el borde de BIP-32 de HU-06-02 RN-8: si el
497	 * índice produce una clave inválida (`I_L >= n` o `k_hijo == 0`), avanza determinísticamente
498	 * al índice siguiente hasta hallar uno válido. Si se supera `MAX_ADDRESS_INDEX` lanza
499	 * `DerivationExhaustedError`.
500	 *
501	 * El índice efectivamente usado se devuelve en `addressIndex` (y queda reflejado en
502	 * `derivationPath`), consistente con HU-06-03 RN-1.
503	 */
504	export function deriveAccountFromIndexOrNext(
505	  seed: Uint8Array,
506	  startIndex: number,
507	  deps?: DerivationDeps
508	): DerivedAccount {
509	  assertAddressIndexInRange(startIndex);
510	  const hmacSha512 = deps?.hmacSha512;
511	  const parent = externalChainNode(seed, hmacSha512);
512	
513	  for (let index = startIndex; index <= MAX_ADDRESS_INDEX; index++) {
514	    try {
515	      return toDerivedAccount(ckdPriv(parent, index, hmacSha512), index);
516	    } catch (err) {
517	      if (err instanceof InvalidChildKeyError) continue; // RN-8: avanzar al siguiente índice
518	      throw err;
519	    }
520	  }
521	
522	  throw new DerivationExhaustedError(
523	    `no se halló un address_index válido en [${startIndex}, ${MAX_ADDRESS_INDEX}]`
524	  );
525	}

