    42	}
    43	
    44	export function encryptPayload(plaintext: Buffer, key: Buffer): Buffer {
    45	  const nonce = randomBytes(NONCE_BYTES);
    46	  const cipher = createCipheriv('aes-256-gcm', key, nonce);
    47	  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    48	  const tag = cipher.getAuthTag();
    49	  return Buffer.concat([nonce, ciphertext, tag]);
    50	}
    51	
    52	export function decryptPayload(blob: Buffer, key: Buffer): Buffer {
    53	  if (blob.length < NONCE_BYTES + TAG_BYTES) {
    54	    throw new ProvisioningError('INTERNAL_ERROR', 'El material cifrado del seed está incompleto.');
    55	  }
    56	  const nonce = blob.subarray(0, NONCE_BYTES);
    57	  const tag = blob.subarray(blob.length - TAG_BYTES);
    58	  const ciphertext = blob.subarray(NONCE_BYTES, blob.length - TAG_BYTES);
    59	  const decipher = createDecipheriv('aes-256-gcm', key, nonce);
    60	  decipher.setAuthTag(tag);
    61	  try {
    62	    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
    63	  } catch {
    64	    // Tag GCM que no verifica: corrupción, restauración incorrecta o credencial errónea.
    65	    throw new ProvisioningError(
    66	      'INTERNAL_ERROR',
    67	      'No se pudo descifrar el seed HD persistido (credencial incorrecta o material corrupto).',
    68	    );
    69	  }
    70	}
