    78	export interface ProvisionOptions {
    79	  db: Db;
    80	  /** Credencial de cifrado del entorno; su ausencia aborta el provisioning (RN-6/RN-11). */
    81	  encryptionKey?: Buffer;
    82	  /** Mnemonic importado por configuración (opcional). Debe cumplir BIP-39 de 24 palabras. */
    83	  importedMnemonic?: string;
