    87	/**
    88	 * Carga el seed persistido o, si no existe, provisiona uno nuevo (o importa el configurado).
    89	 * Nunca regenera ni sobrescribe un seed existente (RN-4/RN-8).
    90	 */
    91	export function provisionWallet(options: ProvisionOptions): ProvisionedWallet {
    92	  const { db, encryptionKey } = options;
    93	  const existing = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as
    94	    | { payload: Uint8Array }
    95	    | undefined;
    96	
    97	  if (!encryptionKey) {
    98	    // Credencial ausente. Con un seed ya persistido el fallo es de descifrado
    99	    // (`INTERNAL_ERROR`, AT-06-01-11); sin seed es un error de configuración del entorno.
   100	    // En ambos casos se aborta: nunca se continúa sin seed ni se genera uno nuevo (RN-11).
   101	    throw new ProvisioningError(
   102	      existing ? 'INTERNAL_ERROR' : 'VALIDATION_ERROR',
   103	      existing
   104	        ? 'No se pudo descifrar el seed HD persistido: falta la credencial de cifrado ' +
   105	          '(WALLET_ENCRYPTION_KEY).'
   106	        : 'Falta WALLET_ENCRYPTION_KEY: la credencial de cifrado del seed HD se provee por ' +
   107	          'configuración del entorno y nunca se embebe en el código (HU-06-01 RN-6). ' +
   108	          'Generá una con: npm run genkey',
   109	    );
   110	  }
   111	
   112	  if (existing) {
   113	    const plaintext = decryptPayload(Buffer.from(existing.payload), encryptionKey);
   114	    let payload: SeedPayload;
   115	    try {
   116	      payload = JSON.parse(plaintext.toString('utf8')) as SeedPayload;
   117	    } catch {
   118	      throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD persistido no es legible.');
   119	    }
   120	    if (typeof payload?.mnemonic !== 'string') {
   121	      throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD persistido no es legible.');
   122	    }
   123	    const seed = mnemonicToSeed(payload.mnemonic, payload.passphrase ?? '');
   124	    return { seed, generated: false };
   125	  }
   126	
   127	  const passphrase = options.passphrase ?? '';
   128	  let mnemonic: string;
   129	  if (options.importedMnemonic) {
   130	    try {
   131	      validateMnemonic24(options.importedMnemonic);
   132	    } catch (err) {
   133	      if (err instanceof MnemonicValidationError) {
   134	        // No se adopta ni se persiste nada (RN-2/RN-11).
   135	        throw new ProvisioningError('VALIDATION_ERROR', `Mnemonic BIP-39 inválido: ${err.message}`);
   136	      }
   137	      throw err;
   138	    }
   139	    mnemonic = options.importedMnemonic;
   140	  } else {
   141	    mnemonic = generateMnemonic24();
   142	  }
   143	
   144	  const payload: SeedPayload = { v: 1, mnemonic, passphrase };
   145	  const blob = encryptPayload(Buffer.from(JSON.stringify(payload), 'utf8'), encryptionKey);
   146	  // Escritura atómica: una única transacción; el seed se considera provisionado sólo si
   147	  // luego puede leerse y descifrarse (RN-9).
   148	  transaction(db, () => {
   149	    db.prepare('INSERT INTO wallet_seed (id, payload, created_at) VALUES (1, ?, ?)').run(
   150	      blob,
   151	      nowIso(),
   152	    );
   153	  });
   154	  const verification = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as
   155	    | { payload: Uint8Array }
   156	    | undefined;
   157	  if (!verification) {
   158	    throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD no quedó persistido.');
   159	  }
   160	  decryptPayload(Buffer.from(verification.payload), encryptionKey);
   161	
   162	  return { seed: mnemonicToSeed(mnemonic, passphrase), generated: true };
   163	}
