   165	/**
   166	 * Smoke test de integridad al arrancar (RN-10): con un mapeo `cuenta → address_index` no
   167	 * vacío, se re-deriva el índice más bajo asignado y se compara con la dirección
   168	 * persistida. Cualquier discrepancia aborta el arranque (RN-11).
   169	 */
   170	export function verifySeedIntegrity(db: Db, seed: Buffer, k = 1): void {
   171	  const rows = db
   172	    .prepare(
   173	      'SELECT address_index AS addressIndex, address FROM deposit_addresses ORDER BY address_index ASC LIMIT ?',
   174	    )
   175	    .all(k) as unknown as { addressIndex: number; address: string }[];
   176	  for (const row of rows) {
   177	    const derived = deriveAccount(seed, row.addressIndex);
   178	    if (derived.address !== row.address) {
   179	      throw new ProvisioningError(
   180	        'INTERNAL_ERROR',
   181	        `Verificación de integridad del seed fallida para el índice ${row.addressIndex}: ` +
   182	          'la dirección derivada no coincide con la persistida.',
   183	      );
   184	    }
   185	  }
   186	}
