/**
 * Cliente JSON-RPC mínimo contra el endpoint configurable de la red
 * (`ETH_RPC_URL`). La red es única: Sepolia, chainId 11155111 (INV-6).
 *
 * En esta etapa el backend no envía transacciones (las épicas 07/08 están fuera de
 * alcance); el cliente se usa para verificar, al arrancar, que el endpoint configurado
 * apunta efectivamente a Sepolia.
 */
export interface JsonRpcResponse<T> {
  jsonrpc: '2.0';
  id: number | string;
  result?: T;
  error?: { code: number; message: string };
}

export class JsonRpcError extends Error {}

export class JsonRpcClient {
  private nextId = 1;

  constructor(private readonly url: string, private readonly timeoutMs = 5000) {}

  get configured(): boolean {
    return this.url !== '';
  }

  async call<T>(method: string, params: unknown[] = []): Promise<T> {
    if (!this.configured) throw new JsonRpcError('No hay endpoint JSON-RPC configurado.');
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
    try {
      const response = await fetch(this.url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', id: this.nextId++, method, params }),
        signal: controller.signal,
      });
      if (!response.ok) throw new JsonRpcError(`HTTP ${response.status} del nodo JSON-RPC.`);
      const payload = (await response.json()) as JsonRpcResponse<T>;
      if (payload.error) throw new JsonRpcError(payload.error.message);
      return payload.result as T;
    } finally {
      clearTimeout(timer);
    }
  }

  /** `eth_chainId` devuelto como entero decimal en string (nunca float). */
  async chainId(): Promise<string> {
    const hex = await this.call<string>('eth_chainId');
    return BigInt(hex).toString(10);
  }

  async blockNumber(): Promise<string> {
    const hex = await this.call<string>('eth_blockNumber');
    return BigInt(hex).toString(10);
  }
}
=========MAIN=========
/**
 * Punto de entrada del backend.
 *
 * Secuencia de arranque:
 *  1. Carga y validación de configuración (TTL de sesión, credencial de cifrado, red).
 *  2. Apertura de la base persistente.
 *  3. Provisioning/carga del seed HD y **smoke test de integridad** (HU-06-01 RN-10).
 *  4. Verificación opcional del endpoint JSON-RPC configurado (chainId 11155111).
 *  5. Levantado del servidor HTTP.
 *
 * Cualquier fallo de (1)–(3) **aborta** con código de salida distinto de cero y el `code`
 * del catálogo en `stderr`, sin filtrar material secreto (HU-06-01 RN-11).
 */
import { ConfigError, loadConfig, CHAIN_ID } from './core/config';
import { warmUpDummyHash } from './core/password';
import { ProvisioningError } from './modules/wallet/seedStore';
import { JsonRpcClient } from './chain/rpc';
import { bootstrap, type BootstrappedApp } from './bootstrap';

function abort(code: string, message: string): never {
  process.stderr.write(`${JSON.stringify({ fatal: { code, message } })}\n`);
  process.exit(1);
}

async function main(): Promise<void> {
  let config;
  try {
    config = loadConfig();
  } catch (err) {
    if (err instanceof ConfigError) abort('VALIDATION_ERROR', err.message);
    throw err;
  }

  let booted: BootstrappedApp;
  try {
    booted = bootstrap(config);
  } catch (err) {
    if (err instanceof ProvisioningError) abort(err.code, err.message);
    throw err;
  }

  const rpc = new JsonRpcClient(config.ethRpcUrl);
  if (rpc.configured) {
    try {
      const chainId = await rpc.chainId();
      if (chainId !== CHAIN_ID) {
        abort(
          'CHAIN_ID_MISMATCH',
          `El endpoint JSON-RPC configurado reporta chainId ${chainId}; se esperaba ${CHAIN_ID}.`,
        );
      }
      process.stdout.write(`JSON-RPC verificado: chainId ${chainId} (sepolia).\n`);
    } catch (err) {
      if (err instanceof Error && err.name === 'ProvisioningError') throw err;
      process.stderr.write(
        `Aviso: no se pudo contactar el endpoint JSON-RPC configurado (${(err as Error).message}). ` +
          'El backend arranca igual: esta etapa no ejecuta operaciones on-chain.\n',
      );
    }
  }

  await warmUpDummyHash();

  await booted.app.listen({ host: config.host, port: config.port });

  const shutdown = async (): Promise<void> => {
    await booted.close();
    process.exit(0);
  };
  process.on('SIGINT', () => void shutdown());
  process.on('SIGTERM', () => void shutdown());
}

void main().catch((err) => {
  process.stderr.write(`${JSON.stringify({ fatal: { code: 'INTERNAL_ERROR', message: (err as Error).message } })}\n`);
  process.exit(1);
});

