/**
 * Log de auditoría interno de eventos de autenticación (RNE-9).
 *
 * Es **interno**: no se expone por la API del usuario final, por lo que su existencia no
 * viola la regla de no-enumeración de cuentas (RNE-3). Se persiste en la base y además se
 * emite por `stderr` en formato JSON para inspección operativa. Nunca registra la
 * contraseña, su hash, ni el token emitido (RNE-2 / HU-09-02 RN-11).
 */
import type { Db } from '../db/index';
import { nowIso } from './time';

export type AuditEvent = 'REGISTER' | 'LOGIN';
export type AuditResult = 'SUCCESS' | 'FAILURE';

export interface AuditRecord {
  timestamp: string;
  event: AuditEvent;
  email: string | null;
  result: AuditResult;
  reason?: string | null;
  origin?: string | null;
}

export class AuditLog {
  constructor(private readonly db: Db, private readonly echoToStderr = true) {}

  record(entry: Omit<AuditRecord, 'timestamp'> & { timestamp?: string }): void {
    const timestamp = entry.timestamp ?? nowIso();
    this.db
      .prepare(
        'INSERT INTO auth_audit_log (timestamp, event, email, result, reason, origin) VALUES (?, ?, ?, ?, ?, ?)',
      )
      .run(
        timestamp,
        entry.event,
        entry.email,
        entry.result,
        entry.reason ?? null,
        entry.origin ?? null,
      );
    if (this.echoToStderr) {
      process.stderr.write(
        JSON.stringify({ audit: { ...entry, timestamp } }) + '\n',
      );
    }
  }

  /** Sólo para inspección interna / tests (no hay superficie HTTP para esto). */
  list(limit = 100): AuditRecord[] {
    return this.db
      .prepare('SELECT timestamp, event, email, result, reason, origin FROM auth_audit_log ORDER BY id DESC LIMIT ?')
      .all(limit) as unknown as AuditRecord[];
  }
}

