/**
 * Catálogo de errores de dominio y envelope uniforme de la API.
 *
 * Fuente de verdad: `spec/00-fundaciones/modelo-de-errores.md` (catálogo y mapeo HTTP) y
 * `spec/09-api-http-websocket/HU-09-05-modelo-de-errores-api.md` (superficie de la API).
 *
 * El espacio de nombres de `code` es plano, cerrado y estable: no se inventan códigos
 * nuevos ni variantes de un código existente.
 */

export const ERROR_HTTP_STATUS = {
  // 3.1 Autenticación y autorización
  UNAUTHENTICATED: 401,
  UNAUTHORIZED: 403,
  RATE_LIMITED: 429,
  // 3.2 Validación general
  VALIDATION_ERROR: 422,
  NOT_FOUND: 404,
  METHOD_NOT_ALLOWED: 405,
  // 3.3 Trading: validación de órdenes
  INVALID_PRICE_TICK: 422,
  INVALID_LOT_SIZE: 422,
  BELOW_MIN_NOTIONAL: 422,
  INVALID_SIDE: 422,
  INVALID_ORDER_TYPE: 422,
  PRICE_REQUIRED: 422,
  PRICE_NOT_ALLOWED: 422,
  // 3.4 Trading: estado y ejecución
  INSUFFICIENT_FUNDS: 422,
  ORDER_NOT_FOUND: 404,
  ORDER_NOT_CANCELLABLE: 409,
  SELF_TRADE_BLOCKED: 422,
  MARKET_NO_LIQUIDITY: 422,
  MARKET_BUDGET_INSUFFICIENT: 422,
  DUPLICATE_CLIENT_ORDER_ID: 409,
  // 3.5 On-chain
  INVALID_ADDRESS: 422,
  WITHDRAWAL_BELOW_MIN: 422,
  WITHDRAWAL_AMOUNT_INVALID: 422,
  DEPOSIT_ALREADY_CREDITED: 409,
  DEPOSIT_NOT_CONFIRMED: 409,
  CHAIN_ID_MISMATCH: 422,
  NONCE_CONFLICT: 409,
  BROADCAST_FAILED: 502,
  // 3.6 Cuentas
  EMAIL_ALREADY_EXISTS: 409,
  INVALID_CREDENTIALS: 401,
  ACCOUNT_NOT_FOUND: 404,
  // 3.7 Genéricos / sistema
  CONFLICT: 409,
  INTERNAL_ERROR: 500,
} as const;

export type ErrorCode = keyof typeof ERROR_HTTP_STATUS;

export type ErrorDetails = Record<string, unknown>;

export interface ErrorEnvelope {
  error: {
    code: ErrorCode;
    message: string;
    details?: ErrorDetails;
  };
}

/** Error de dominio con `code` del catálogo. Su status HTTP se deriva del catálogo. */
export class AppError extends Error {
  readonly code: ErrorCode;
  readonly details?: ErrorDetails;
  /** Headers extra a agregar en la respuesta (p. ej. `Retry-After`). */
  readonly headers?: Record<string, string>;

  constructor(
    code: ErrorCode,
    message: string,
    details?: ErrorDetails,
    headers?: Record<string, string>,
  ) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    this.details = details;
    this.headers = headers;
  }

  get httpStatus(): number {
    return ERROR_HTTP_STATUS[this.code];
  }

  toEnvelope(): ErrorEnvelope {
    const envelope: ErrorEnvelope = {
      error: { code: this.code, message: this.message },
    };
    if (this.details !== undefined) envelope.error.details = this.details;
    return envelope;
  }
}

/** Una causa de fallo de esquema, tal como se serializa en `details.issues`. */
export interface ValidationIssue {
  field: string;
  message: string;
}

export function validationError(issues: ValidationIssue[], message?: string): AppError {
  return new AppError(
    'VALIDATION_ERROR',
    message ?? 'El payload no cumple el esquema esperado.',
    { issues },
  );
}

export function unauthenticated(): AppError {
  // El mensaje no distingue el motivo (token ausente / inválido / expirado): HU-09-02 RN-3.
  return new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
}

