 * Patrón de monto serializado (convenciones-monetarias.md §5): string de entero decimal no
 * negativo, sin signo, sin decimales, sin notación científica y sin ceros a la izquierda.
 */
export const AMOUNT_PATTERN = /^(0|[1-9][0-9]*)$/;

export function isSerializedAmount(value: unknown): value is string {
  return typeof value === 'string' && AMOUNT_PATTERN.test(value);
}
/**
 * Rate limiting con ventana deslizante en memoria.
 *
 * - Endpoints autenticados: 60 requests/min por `accountId` y por endpoint
 *   (HU-09-02 RN-12).
 * - `/auth/register` y `/auth/login`: políticas opcionales de la épica 01
 *   (HU-01-01 RN-10, HU-01-02 RN-9), desactivadas salvo configuración explícita.
 *
 * Al superarse el umbral se responde `RATE_LIMITED` (429) con
 * `details.retryAfterSeconds` (entero) y header `Retry-After` (HU-09-05 RN-8).
 */
import type { RateLimitPolicy } from '../core/config';

export interface RateLimitDecision {
  limited: boolean;
  retryAfterSeconds: number;
}

export class SlidingWindowLimiter {
  private readonly hits = new Map<string, number[]>();

  constructor(private readonly policy: RateLimitPolicy) {}

  get enabled(): boolean {
    return this.policy.enabled;
  }

  private prune(key: string, now: number): number[] {
    const windowMs = this.policy.windowSeconds * 1000;
    const entries = (this.hits.get(key) ?? []).filter((t) => now - t < windowMs);
    if (entries.length > 0) this.hits.set(key, entries);
    else this.hits.delete(key);
    return entries;
  }

  private retryAfter(entries: number[], now: number): number {
    const windowMs = this.policy.windowSeconds * 1000;
    const oldest = entries[0];
    if (oldest === undefined) return 0;
    return Math.max(0, Math.ceil((oldest + windowMs - now) / 1000));
  }

  /** Consume una unidad de cuota. Devuelve si la request debe rechazarse con 429. */
  consume(key: string, now = Date.now()): RateLimitDecision {
    if (!this.policy.enabled) return { limited: false, retryAfterSeconds: 0 };
    const entries = this.prune(key, now);
    if (entries.length >= this.policy.max) {
      return { limited: true, retryAfterSeconds: this.retryAfter(entries, now) };
    }
    entries.push(now);
    this.hits.set(key, entries);
    return { limited: false, retryAfterSeconds: 0 };
  }

  /** Consulta sin consumir cuota (para políticas que sólo cuentan fallos). */
  peek(key: string, now = Date.now()): RateLimitDecision {
    if (!this.policy.enabled) return { limited: false, retryAfterSeconds: 0 };
    const entries = this.prune(key, now);
    if (entries.length >= this.policy.max) {
      return { limited: true, retryAfterSeconds: this.retryAfter(entries, now) };
    }
    return { limited: false, retryAfterSeconds: 0 };
  }

  /** Registra un evento (p. ej. un intento de login fallido) sin evaluar el umbral. */
  record(key: string, now = Date.now()): void {
    if (!this.policy.enabled) return;
    const entries = this.prune(key, now);
    entries.push(now);
    this.hits.set(key, entries);
  }

  reset(): void {
    this.hits.clear();
  }
}
