test('AT-01-02-09: rate limiting de login — el intento N+1 se rechaza con RATE_LIMITED (429)', async () => {
  // El limitador cuenta **intentos fallidos** por (origen, email normalizado) y se evalúa
  // como paso 0 de la precedencia (RN-8/RN-9): antes incluso del esquema.
  const MAX = 3;
  const ctx = createTestApp({
    LOGIN_RATE_LIMIT_ENABLED: 'true',
    LOGIN_RATE_LIMIT_MAX_FAILURES: String(MAX),
    LOGIN_RATE_LIMIT_WINDOW_SECONDS: '60',
  });
  try {
    assert.equal(
      ctx.config.loginRateLimit.enabled,
      true,
      'la política de rate limiting de login debe quedar activa con los overrides de entorno declarados (RN-9)',
    );
    assert.equal(ctx.config.loginRateLimit.max, MAX, 'el umbral N debe leerse de la configuración del entorno');
    assert.equal(ctx.config.loginRateLimit.windowSeconds, 60, 'la ventana W debe leerse de la configuración del entorno');

    const existente = uniqueEmail('existe');
    await registerAccount(ctx.app, existente);
    const inexistente = uniqueEmail('nadie');

    async function agotarUmbral(email: string) {
      for (let i = 0; i < MAX; i += 1) {
        const failed = await post(ctx.app, LOGIN_URL, { email, password: 'PasswordIncorrecta' });
        assertErrorEnvelope(failed, 'INVALID_CREDENTIALS', 401);
      }
      return post(ctx.app, LOGIN_URL, { email, password: 'PasswordIncorrecta' });
    }

    const limitedExistente = await agotarUmbral(existente);
    const errorExistente = assertErrorEnvelope(limitedExistente, 'RATE_LIMITED', 429);
    const detallesExistente = errorExistente.details as { retryAfterSeconds: number };
    assert.equal(typeof detallesExistente.retryAfterSeconds, 'number');
    assert.ok(detallesExistente.retryAfterSeconds >= 0);
    assert.equal(limitedExistente.headers['retry-after'], String(detallesExistente.retryAfterSeconds));

    // Uniformidad: el mismo comportamiento para un email inexistente (no revela existencia).
    const limitedInexistente = await agotarUmbral(inexistente);
    const errorInexistente = assertErrorEnvelope(limitedInexistente, 'RATE_LIMITED', 429);
    assert.equal(limitedInexistente.statusCode, limitedExistente.statusCode);
    assert.deepEqual(
      Object.keys(errorInexistente.details as object).sort(),
      Object.keys(errorExistente.details as object).sort(),
    );
    assert.equal(errorInexistente.message, errorExistente.message);

    // Paso 0: con el umbral agotado, incluso un payload inválido responde 429 (no 422).
    const invalido = await post(ctx.app, LOGIN_URL, { email: existente });
    assertErrorEnvelope(invalido, 'RATE_LIMITED', 429);
  } finally {
    await ctx.cleanup();
  }
});

