  peekByPrefix(prefix: string, now = Date.now()): RateLimitDecision {
    if (!this.policy.enabled) return { limited: false, retryAfterSeconds: 0 };
    let worst: RateLimitDecision = { limited: false, retryAfterSeconds: 0 };
    for (const key of [...this.hits.keys()]) {
      if (!key.startsWith(prefix)) continue;
      const decision = this.peek(key, now);
      if (decision.limited && decision.retryAfterSeconds >= worst.retryAfterSeconds) {
        worst = decision;
      }
    }
    return worst;
  }

