1	/**
2	 * Helper compartido por los tests de aceptación: levanta una instancia real del backend
3	 * (base SQLite en un directorio temporal + wallet HD provisionada) y expone utilidades
4	 * para inyectar requests HTTP con `app.inject()` (sin abrir un puerto).
5	 */
6	import * as fs from 'node:fs';
7	import * as os from 'node:os';
8	import * as path from 'node:path';
9	import { randomBytes } from 'node:crypto';
10	import type { FastifyInstance, InjectOptions } from 'fastify';
11	import { loadConfig, type Config } from '../../src/core/config';
12	import { bootstrap, type BootstrappedApp } from '../../src/bootstrap';
13	
14	export interface TestApp extends BootstrappedApp {
15	  config: Config;
16	  dbPath: string;
17	  encryptionKey: string;
18	  /** Cierra la app y borra el directorio temporal. */
19	  cleanup(): Promise<void>;
20	}
21	
22	export function makeEnv(overrides: Record<string, string> = {}): NodeJS.ProcessEnv {
23	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cex-test-'));
24	  return {
25	    LOAD_DOTENV: 'false',
26	    WALLET_ENCRYPTION_KEY: randomBytes(32).toString('hex'),
27	    DATABASE_PATH: path.join(dir, 'exchange.db'),
28	    LOG_LEVEL: 'silent',
29	    ...overrides,
30	  };
31	}
32	
33	/** Levanta una app de test. `env` permite sobreescribir cualquier variable de entorno. */
34	export function createTestApp(overrides: Record<string, string> = {}): TestApp {
35	  const env = makeEnv(overrides);
36	  const config = loadConfig(env);
37	  const booted = bootstrap(config);
38	  return {
39	    ...booted,
40	    config,
41	    dbPath: config.databasePath,
42	    encryptionKey: env.WALLET_ENCRYPTION_KEY as string,
43	    async cleanup() {
44	      await booted.close();
45	      fs.rmSync(path.dirname(config.databasePath), { recursive: true, force: true });
46	    },
47	  };
48	}
49	
50	/** Reabre una app sobre la MISMA base y clave (simula un reinicio del proceso). */
51	export function restartTestApp(previous: TestApp, overrides: Record<string, string> = {}): TestApp {
52	  const env = {
53	    LOAD_DOTENV: 'false',
54	    WALLET_ENCRYPTION_KEY: previous.encryptionKey,
55	    DATABASE_PATH: previous.dbPath,
56	    LOG_LEVEL: 'silent',
57	    ...overrides,
58	  } as NodeJS.ProcessEnv;
59	  const config = loadConfig(env);
60	  const booted = bootstrap(config);
61	  return {
62	    ...booted,
63	    config,
64	    dbPath: previous.dbPath,
65	    encryptionKey: previous.encryptionKey,
66	    async cleanup() {
67	      await booted.close();
68	      fs.rmSync(path.dirname(previous.dbPath), { recursive: true, force: true });
69	    },
70	  };
71	}
72	
73	export const VALID_PASSWORD = 'Sup3rSecreta';
74	
75	export async function post(
76	  app: FastifyInstance,
77	  url: string,
78	  payload: unknown,
79	  options: InjectOptions = {},
80	) {
81	  return app.inject({
82	    method: 'POST',
83	    url,
84	    payload: payload === undefined ? undefined : JSON.stringify(payload),
85	    headers: { 'content-type': 'application/json', ...(options.headers ?? {}) },
86	    ...options,
87	  });
88	}
89	
90	export async function get(app: FastifyInstance, url: string, token?: string, options: InjectOptions = {}) {
91	  return app.inject({
92	    method: 'GET',
93	    url,
94	    headers: {
95	      ...(token ? { authorization: `Bearer ${token}` } : {}),
96	      ...(options.headers ?? {}),
97	    },
98	    ...options,
99	  });
100	}
