  if (port < 0 || port > 65535) throw new ConfigError('PORT fuera de rango.');

  const sessionTtlSeconds = env.SESSION_TTL_SECONDS
    ? parseIntStrict(env.SESSION_TTL_SECONDS, 'SESSION_TTL_SECONDS')
    : 3600;
