 */

export const ERROR_HTTP_STATUS = {
  // 3.1 Autenticación y autorización
  UNAUTHENTICATED: 401,
  UNAUTHORIZED: 403,
  RATE_LIMITED: 429,
  // 3.2 Validación general
  VALIDATION_ERROR: 422,
  NOT_FOUND: 404,
  METHOD_NOT_ALLOWED: 405,
  // 3.3 Trading: validación de órdenes
  INVALID_PRICE_TICK: 422,
  INVALID_LOT_SIZE: 422,
  BELOW_MIN_NOTIONAL: 422,
  INVALID_SIDE: 422,
  INVALID_ORDER_TYPE: 422,
  PRICE_REQUIRED: 422,
  PRICE_NOT_ALLOWED: 422,
  // 3.4 Trading: estado y ejecución
  INSUFFICIENT_FUNDS: 422,
  ORDER_NOT_FOUND: 404,
  ORDER_NOT_CANCELLABLE: 409,
  SELF_TRADE_BLOCKED: 422,
  MARKET_NO_LIQUIDITY: 422,
  MARKET_BUDGET_INSUFFICIENT: 422,
  DUPLICATE_CLIENT_ORDER_ID: 409,
  // 3.5 On-chain
  INVALID_ADDRESS: 422,
  WITHDRAWAL_BELOW_MIN: 422,
  WITHDRAWAL_AMOUNT_INVALID: 422,
  DEPOSIT_ALREADY_CREDITED: 409,
  DEPOSIT_NOT_CONFIRMED: 409,
  CHAIN_ID_MISMATCH: 422,
  NONCE_CONFLICT: 409,
  BROADCAST_FAILED: 502,
  // 3.6 Cuentas
  EMAIL_ALREADY_EXISTS: 409,
  INVALID_CREDENTIALS: 401,
  ACCOUNT_NOT_FOUND: 404,
  // 3.7 Genéricos / sistema
  CONFLICT: 409,
  INTERNAL_ERROR: 500,
} as const;

export type ErrorCode = keyof typeof ERROR_HTTP_STATUS;

export type ErrorDetails = Record<string, unknown>;

export interface ErrorEnvelope {
  error: {
    code: ErrorCode;
    message: string;
    details?: ErrorDetails;
  };
}

/** Error de dominio con `code` del catálogo. Su status HTTP se deriva del catálogo. */
export class AppError extends Error {
  readonly code: ErrorCode;
  readonly details?: ErrorDetails;
  /** Headers extra a agregar en la respuesta (p. ej. `Retry-After`). */
  readonly headers?: Record<string, string>;

  constructor(
    code: ErrorCode,
    message: string,
    details?: ErrorDetails,
    headers?: Record<string, string>,
  ) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    this.details = details;
    this.headers = headers;
  }

  get httpStatus(): number {
    return ERROR_HTTP_STATUS[this.code];
  }

  toEnvelope(): ErrorEnvelope {
    const envelope: ErrorEnvelope = {
      error: { code: this.code, message: this.message },
    };
    if (this.details !== undefined) envelope.error.details = this.details;
    return envelope;
  }
}

/** Una causa de fallo de esquema, tal como se serializa en `details.issues`. */
export interface ValidationIssue {
  field: string;
  message: string;
}

export function validationError(issues: ValidationIssue[], message?: string): AppError {
  return new AppError(
    'VALIDATION_ERROR',
    message ?? 'El payload no cumple el esquema esperado.',
    { issues },
  );
}

export function unauthenticated(): AppError {
  // El mensaje no distingue el motivo (token ausente / inválido / expirado): HU-09-02 RN-3.
  return new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
}

/**
 * Superficie HTTP de la API (épica 09, alcance de esta etapa).
 *
 * Contrato: ruta base `/api/v1`, envelope uniforme de error
 * `{ error: { code, message, details? } }`, un solo error por respuesta según la
 * precedencia determinista, y autenticación por token Bearer en los recursos protegidos.
 */
import Fastify, { type FastifyInstance, type FastifyReply, type FastifyRequest } from 'fastify';
import { AppError, validationError } from '../core/errors';
import { CHAIN_ID, NETWORK_NAME, type Config } from '../core/config';
import { nowIso } from '../core/time';
import { normalizeEmail } from '../core/validation';
import type { Db } from '../db/index';
import type { AuditLog } from '../core/audit';
import type { AccountService } from '../modules/accounts/service';
import type { SessionService } from '../modules/accounts/sessions';
import type { WalletService } from '../modules/wallet/service';
import { SlidingWindowLimiter } from './rateLimit';

export interface AppDependencies {
  config: Config;
  db: Db;
  accounts: AccountService;
  sessions: SessionService;
  wallet: WalletService;
  audit: AuditLog;
}

/** Verbos soportados por cada ruta existente (para responder 405 y no 404). */
const ROUTE_METHODS: Record<string, string[]> = {
  '/health': ['GET', 'HEAD'],
  '/api/v1/auth/register': ['POST'],
  '/api/v1/auth/login': ['POST'],
  '/api/v1/deposit-address': ['GET', 'HEAD'],
  '/internal/deposit-addresses': ['GET', 'HEAD'],
};

const SUPPORTED_ASSETS = ['ETH', 'USDC'] as const;
type SupportedAsset = (typeof SUPPORTED_ASSETS)[number];

function normalizePath(url: string): string {
  const pathname = url.split('?')[0];
  if (pathname.length > 1 && pathname.endsWith('/')) return pathname.slice(0, -1);
  return pathname;
}

/**
 * Error de parseo del cuerpo diferido hasta después del paso 0 de la precedencia
 * (rate limiting) y de la autenticación. Se guarda en la request bajo un símbolo propio.
 */
const DEFERRED_BODY_ERROR = Symbol('deferredBodyError');

type RequestWithDeferredError = { [DEFERRED_BODY_ERROR]?: AppError };

function deferBodyError(request: unknown, error: AppError): void {
  (request as RequestWithDeferredError)[DEFERRED_BODY_ERROR] = error;
}

/** Levanta el error de parseo diferido, si lo hubo. */
function throwDeferredBodyError(request: unknown): void {
  const error = (request as RequestWithDeferredError)[DEFERRED_BODY_ERROR];
  if (error) throw error;
}

function singleQueryValue(value: unknown): string | undefined {
  if (value === undefined) return undefined;
  if (Array.isArray(value)) return value.length > 0 ? String(value[value.length - 1]) : undefined;
  return String(value);
}

export function buildApp(deps: AppDependencies): FastifyInstance {
  const { config, accounts, sessions, wallet, audit } = deps;

  const app = Fastify({
    logger: { level: config.logLevel },
    ajv: { customOptions: { allErrors: true } },
  });

  const apiLimiter = new SlidingWindowLimiter(config.apiRateLimit);
  const registerLimiter = new SlidingWindowLimiter(config.registerRateLimit);
  const loginFailureLimiter = new SlidingWindowLimiter(config.loginRateLimit);

  // ---------------------------------------------------------------------------
  // Parseo del cuerpo: cualquier cuerpo se interpreta como JSON. Un cuerpo que no sea
  // JSON válido produce VALIDATION_ERROR (422) — HU-09-01 RN-3.
  //
  // El fallo de parseo NO se emite acá: el parser corre antes que los handlers, y el rate
  // limiting es el **paso 0** de la precedencia, anterior a cualquier validación "incluso
  // la de esquema" (HU-01-01 RN-9/RN-10, HU-01-02 RN-8/RN-9). Por eso el error queda
  // diferido en la request y lo levanta el handler *después* de evaluar el límite (o, para
  // el resto de las rutas, el hook `preHandler` de más abajo, que además corre después de
  // la autenticación de HU-09-02 RN-9).
  // ---------------------------------------------------------------------------
  app.removeContentTypeParser(['application/json', 'text/plain']);
  app.addContentTypeParser('*', { parseAs: 'string' }, (request, body: string, done) => {
    const contentType = request.headers['content-type'];
    if (contentType && !/json/i.test(contentType)) {
      deferBodyError(
        request,
        validationError([{ field: 'Content-Type', message: 'Se espera application/json.' }]),
      );
      done(null, undefined);
      return;
    }
    if (body === undefined || body === null || body.length === 0) {
      done(null, undefined);
      return;
    }
    try {
      done(null, JSON.parse(body));
    } catch {
      deferBodyError(
        request,
        validationError([{ field: 'body', message: 'El cuerpo no es JSON válido.' }]),
      );
      done(null, undefined);
    }
  });

  // Rutas que evalúan el error de parseo diferido dentro del handler (después del paso 0).
  const DEFERRED_BODY_ROUTES = new Set(['/api/v1/auth/register', '/api/v1/auth/login']);
  app.addHook('preHandler', async (request) => {
    if (DEFERRED_BODY_ROUTES.has(normalizePath(request.url))) return;
    throwDeferredBodyError(request);
  });

  // ---------------------------------------------------------------------------
  // Manejo uniforme de errores (HU-09-05).
  // ---------------------------------------------------------------------------
  function sendError(reply: FastifyReply, error: AppError): FastifyReply {
    if (error.headers) {
      for (const [name, value] of Object.entries(error.headers)) reply.header(name, value);
    }
    return reply.status(error.httpStatus).send(error.toEnvelope());
  }

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof AppError) {
      return sendError(reply, error);
    }
    const fastifyCode = (error as { code?: string }).code ?? '';
    if (
      fastifyCode.startsWith('FST_ERR_CTP_') ||
      fastifyCode === 'FST_ERR_VALIDATION' ||
      (typeof (error as { statusCode?: number }).statusCode === 'number' &&
        (error as { statusCode: number }).statusCode === 400)
    ) {
      return sendError(
        reply,
        validationError([{ field: 'body', message: 'Cuerpo o parámetros inválidos.' }]),
      );
    }
    // INTERNAL_ERROR no filtra detalles sensibles (HU-09-05 RN-9); el detalle queda en el
    // log del servidor.
    request.log.error({ err: error }, 'error interno no clasificado');
    return sendError(reply, new AppError('INTERNAL_ERROR', 'Error interno del servidor.'));
  });

  app.setNotFoundHandler((request, reply) => {
    const pathname = normalizePath(request.url);
    const allowed = ROUTE_METHODS[pathname];
    if (allowed && !allowed.includes(request.method)) {
      return sendError(
        reply,
        new AppError('METHOD_NOT_ALLOWED', 'Método no permitido sobre la ruta.', {
          method: request.method,
          allowed,
        }),
      );
    }
    return sendError(
      reply,
      new AppError('NOT_FOUND', 'Recurso inexistente.', { resource: 'route', id: pathname }),
    );
  });

  // ---------------------------------------------------------------------------
  // Autenticación (HU-09-02 RN-1..RN-4): se evalúa antes que cualquier validación de
  // esquema o regla de negocio (RN-9).
  // ---------------------------------------------------------------------------
  function authenticate(request: FastifyRequest): { accountId: string } {
    const header = request.headers.authorization;
    if (!header || typeof header !== 'string') throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
    // El nombre del esquema es case-insensitive (RFC 7235); el valor del token no.
    const match = /^Bearer[ \t]+(.+)$/i.exec(header.trim());
    if (!match) throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
    const identity = sessions.resolve(match[1].trim());
    if (!identity) throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
    return { accountId: identity.accountId };
  }

  function enforceApiRateLimit(accountId: string, routeKey: string): void {
    const decision = apiLimiter.consume(`${accountId}|${routeKey}`);
    if (decision.limited) {
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de solicitudes permitido.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
  }

  // ---------------------------------------------------------------------------
  // Health check
  // ---------------------------------------------------------------------------
  app.get('/health', async () => ({
    status: 'ok',
    service: 'cex-backend',
    time: nowIso(),
    network: NETWORK_NAME,
    chainId: CHAIN_ID,
    rpcConfigured: config.ethRpcUrl !== '',
  }));

  // ---------------------------------------------------------------------------
  // HU-01-01 — Registro (público, 201)
  // ---------------------------------------------------------------------------
  app.post('/api/v1/auth/register', async (request, reply) => {
    // Paso 0 de la precedencia (HU-01-01 RN-9/RN-10): rate limiting antes de todo.
    const decision = registerLimiter.consume(`${request.ip}`);
    if (decision.limited) {
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de registros permitido desde este origen.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-9).
    throwDeferredBodyError(request);
    const account = await accounts.register(request.body, request.ip ?? null);
    return reply.status(201).send(account);
  });

  // ---------------------------------------------------------------------------
  // HU-01-02 — Login (público, 200)
  // ---------------------------------------------------------------------------
  app.post('/api/v1/auth/login', async (request, reply) => {
    // Paso 0: rate limiting de intentos fallidos por (origen, email), uniforme y sin
    // revelar la existencia del email (HU-01-02 RN-8/RN-9).
    const rawEmail =
      typeof request.body === 'object' &&
      request.body !== null &&
      typeof (request.body as Record<string, unknown>).email === 'string'
        ? normalizeEmail((request.body as Record<string, string>).email)
        : '';
    const limiterKey = `${request.ip}|${rawEmail}`;
    // Si el cuerpo no parseó no hay email: el paso 0 se evalúa igual, con el origen como
    // granularidad, para que una solicitud con payload inválido responda 429 y no 422
    // (HU-01-02 RN-8).
    const decision =
      rawEmail === ''
        ? loginFailureLimiter.peekByPrefix(`${request.ip}|`)
        : loginFailureLimiter.peek(limiterKey);
    if (decision.limited) {
      audit.record({
        event: 'LOGIN',
        email: rawEmail || null,
        result: 'FAILURE',
        reason: 'RATE_LIMITED',
        origin: request.ip ?? null,
      });
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de intentos de autenticación.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-8).
    throwDeferredBodyError(request);
    try {
      const result = await accounts.login(request.body, request.ip ?? null);
      return reply.status(200).send(result);
    } catch (err) {
      if (err instanceof AppError && err.code === 'INVALID_CREDENTIALS') {
        loginFailureLimiter.record(limiterKey);
      }
      throw err;
    }
  });

  // ---------------------------------------------------------------------------
  // HU-06-04 — Consulta de dirección de depósito (protegido, 200)
  // ---------------------------------------------------------------------------
  app.get('/api/v1/deposit-address', async (request, reply) => {
    // Precedencia (HU-06-04 RN-9): UNAUTHENTICATED → UNAUTHORIZED → esquema/activo →
    // red → asignación/lectura.
    const identity = authenticate(request);
    enforceApiRateLimit(identity.accountId, 'GET /api/v1/deposit-address');

    const query = (request.query ?? {}) as Record<string, unknown>;
    const asset = singleQueryValue(query.asset);
    if (asset === undefined || !SUPPORTED_ASSETS.includes(asset as SupportedAsset)) {
      throw validationError([
        {
          field: 'asset',
          message: `El activo debe ser uno de: ${SUPPORTED_ASSETS.join(', ')}.`,
        },
      ]);
    }

    // La red es implícitamente Sepolia; si la consulta declara otra, se rechaza (RN-4).
    const chainIdParam = singleQueryValue(query.chainId);
    if (chainIdParam !== undefined && chainIdParam.trim() !== CHAIN_ID) {
      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
        expected: CHAIN_ID,
        got: chainIdParam,
      });
    }
    const networkParam = singleQueryValue(query.network);
    if (networkParam !== undefined && networkParam.trim().toLowerCase() !== NETWORK_NAME) {
      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
        expected: CHAIN_ID,
        got: networkParam,
      });
    }

    // La identidad sale exclusivamente del token: cualquier selector de cuenta inyectado
    // por query o body se ignora (RN-2).
    const record = wallet.getOrAssign(identity.accountId);

    const body: Record<string, string> = {
      asset,
      address: record.address,
      network: record.network,
      chainId: record.chainId,
      derivationPath: record.derivationPath,
    };
    if (asset === 'USDC') body.tokenAddress = config.usdcContractAddress;
    return reply.status(200).send(body);
  });

  // ---------------------------------------------------------------------------
  // Consulta interna del conjunto de direcciones asignadas (HU-06-03 RN-11).
  // No es pública: requiere `X-Internal-Token` o provenir de loopback.
  // ---------------------------------------------------------------------------
  app.get('/internal/deposit-addresses', async (request, reply) => {
    const token = request.headers['x-internal-token'];
    const isLoopback = ['127.0.0.1', '::1', '::ffff:127.0.0.1'].includes(request.ip);
    const authorized = config.internalApiToken
      ? token === config.internalApiToken
      : isLoopback;
    if (!authorized) throw new AppError('UNAUTHENTICATED', 'Credencial interna ausente o inválida.');
    return reply.status(200).send({
      network: NETWORK_NAME,
      chainId: CHAIN_ID,
      items: wallet.listAll().map((record) => ({
        accountId: record.accountId,
        addressIndex: record.addressIndex,
        address: record.address,
        derivationPath: record.derivationPath,
        network: record.network,
        chainId: record.chainId,
        createdAt: record.createdAt,
      })),
    });
  });

  return app;
}

/**
 * Provisioning y custodia del seed HD (HU-06-01).
 *
 * - El material secreto se persiste **cifrado en reposo** con AES-256-GCM, con nonce
 *   aleatorio de 96 bits por operación de cifrado y tag de 128 bits, en el formato
 *   `nonce || ciphertext || tag` (RN-6).
 * - La clave de cifrado proviene de la configuración del entorno; nunca se persiste junto
 *   al material cifrado ni está embebida en el código.
 * - Ante mnemonic inválido, fallo de descifrado o verificación de integridad fallida, el
 *   proceso **aborta** sin generar ni sobrescribir un seed (RN-11). Esta capa señaliza el
 *   fallo con `ProvisioningError`, que `main.ts` traduce a salida distinta de cero con el
 *   `code` del catálogo en `stderr`, **sin filtrar material secreto** (RN-5).
 */
import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto';
import { EncryptionKeyFormatError, decodeEncryptionKey } from '../../core/config';
import type { Db } from '../../db/index';
import { transaction } from '../../db/index';
import { nowIso } from '../../core/time';
import {
  MnemonicValidationError,
  deriveAccount,
  generateMnemonic24,
  mnemonicToSeed,
  validateMnemonic24,
} from '../../wallet/hd';

const NONCE_BYTES = 12;
const TAG_BYTES = 16;

export type ProvisioningErrorCode = 'VALIDATION_ERROR' | 'INTERNAL_ERROR';

export class ProvisioningError extends Error {
  constructor(readonly code: ProvisioningErrorCode, message: string) {
    super(message);
    this.name = 'ProvisioningError';
  }
}

interface SeedPayload {
  v: 1;
  mnemonic: string;
  passphrase: string;
}

export function encryptPayload(plaintext: Buffer, key: Buffer): Buffer {
  const nonce = randomBytes(NONCE_BYTES);
  const cipher = createCipheriv('aes-256-gcm', key, nonce);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([nonce, ciphertext, tag]);
}

export function decryptPayload(blob: Buffer, key: Buffer): Buffer {
  if (blob.length < NONCE_BYTES + TAG_BYTES) {
    throw new ProvisioningError('INTERNAL_ERROR', 'El material cifrado del seed está incompleto.');
  }
  const nonce = blob.subarray(0, NONCE_BYTES);
  const tag = blob.subarray(blob.length - TAG_BYTES);
  const ciphertext = blob.subarray(NONCE_BYTES, blob.length - TAG_BYTES);
  const decipher = createDecipheriv('aes-256-gcm', key, nonce);
  decipher.setAuthTag(tag);
  try {
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  } catch {
    // Tag GCM que no verifica: corrupción, restauración incorrecta o credencial errónea.
    throw new ProvisioningError(
      'INTERNAL_ERROR',
      'No se pudo descifrar el seed HD persistido (credencial incorrecta o material corrupto).',
    );
  }
}

export interface ProvisionedWallet {
  seed: Buffer;
  /** `true` si esta ejecución generó el seed; `false` si lo recuperó del almacenamiento. */
  generated: boolean;
}

export interface ProvisionOptions {
  db: Db;
  /**
   * Credencial de cifrado **tal como viene del entorno** (sin decodificar). Su ausencia y su
   * formato inválido se clasifican acá y no en la carga de configuración, porque el `code`
   * del aborto depende de si hay un seed persistido (RN-6/RN-11, AT-06-01-11).
   */
  encryptionKeyRaw?: string;
  /** Mnemonic importado por configuración (opcional). Debe cumplir BIP-39 de 24 palabras. */
  importedMnemonic?: string;
  passphrase?: string;
}

/**
 * Carga el seed persistido o, si no existe, provisiona uno nuevo (o importa el configurado).
 * Nunca regenera ni sobrescribe un seed existente (RN-4/RN-8).
 */
export function provisionWallet(options: ProvisionOptions): ProvisionedWallet {
  const { db } = options;
  const existing = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as
    | { payload: Uint8Array }
    | undefined;

  const rawKey = options.encryptionKeyRaw;
  let encryptionKey: Buffer | undefined;
  let keyProblem: string | undefined;
  if (rawKey !== undefined && rawKey.trim() !== '') {
    try {
      encryptionKey = decodeEncryptionKey(rawKey);
    } catch (err) {
      if (!(err instanceof EncryptionKeyFormatError)) throw err;
      keyProblem = err.message;
    }
  }

  if (!encryptionKey) {
    // Credencial ausente **o con formato inválido**: con un seed ya persistido el fallo es
    // de descifrado (`INTERNAL_ERROR`, AT-06-01-11); sin seed es un error de configuración
    // del entorno (`VALIDATION_ERROR`). En ambos casos se aborta: nunca se continúa sin
    // seed ni se genera uno nuevo (RN-11).
    const causa = keyProblem
      ? 'la credencial de cifrado configurada no tiene un formato válido'
      : 'falta la credencial de cifrado (WALLET_ENCRYPTION_KEY)';
    throw new ProvisioningError(
      existing ? 'INTERNAL_ERROR' : 'VALIDATION_ERROR',
      existing
        ? `No se pudo descifrar el seed HD persistido: ${causa}.`
        : 'La credencial de cifrado del seed HD se provee por configuración del entorno y ' +
          `nunca se embebe en el código (HU-06-01 RN-6): ${causa}. ` +
          (keyProblem ?? 'Generá una con: npm run genkey'),
    );
  }

  if (existing) {
    const plaintext = decryptPayload(Buffer.from(existing.payload), encryptionKey);
    let payload: SeedPayload;
    try {
      payload = JSON.parse(plaintext.toString('utf8')) as SeedPayload;
    } catch {
      throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD persistido no es legible.');
    }
    if (typeof payload?.mnemonic !== 'string') {
      throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD persistido no es legible.');
    }
    const seed = mnemonicToSeed(payload.mnemonic, payload.passphrase ?? '');
    return { seed, generated: false };
  }

  const passphrase = options.passphrase ?? '';
  let mnemonic: string;
  if (options.importedMnemonic) {
    try {
      validateMnemonic24(options.importedMnemonic);
    } catch (err) {
      if (err instanceof MnemonicValidationError) {
        // No se adopta ni se persiste nada (RN-2/RN-11).
        throw new ProvisioningError('VALIDATION_ERROR', `Mnemonic BIP-39 inválido: ${err.message}`);
      }
      throw err;
    }
    mnemonic = options.importedMnemonic;
  } else {
    mnemonic = generateMnemonic24();
  }

  const payload: SeedPayload = { v: 1, mnemonic, passphrase };
  const blob = encryptPayload(Buffer.from(JSON.stringify(payload), 'utf8'), encryptionKey);
  // Escritura atómica: una única transacción; el seed se considera provisionado sólo si
  // luego puede leerse y descifrarse (RN-9).
  transaction(db, () => {
    db.prepare('INSERT INTO wallet_seed (id, payload, created_at) VALUES (1, ?, ?)').run(
      blob,
      nowIso(),
    );
  });
  const verification = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as
    | { payload: Uint8Array }
    | undefined;
  if (!verification) {
    throw new ProvisioningError('INTERNAL_ERROR', 'El seed HD no quedó persistido.');
  }
