/** Mnemonic BIP-39 de 24 palabras (256 bits de entropía) usado como seed importado. */
const MNEMONIC_24 = `${Array(23).fill('abandon').join(' ')} art`;
/** Un segundo mnemonic de 24 palabras, distinto, para simular una restauración incorrecta. */
const MNEMONIC_24_AJENO = `${Array(23).fill('zoo').join(' ')} vote`;

function bytesToHex(bytes: Uint8Array): string {
  return Buffer.from(bytes).toString('hex');
}

/** Checksum EIP-55 implementado en el test (independiente de `src/wallet/hd.ts`). */
function toEip55(raw20: Uint8Array): string {
  const lower = bytesToHex(raw20);
  const hash = bytesToHex(keccak_256(Buffer.from(lower, 'ascii')));
  let out = '';
  for (let i = 0; i < lower.length; i += 1) {
    out += Number.parseInt(hash[i], 16) >= 8 ? lower[i].toUpperCase() : lower[i];
  }
  return `0x${out}`;
}

/** `true` si la dirección tiene formato `0x`+40 hex y checksum EIP-55 correcto. */
function isEip55(address: unknown): boolean {
  if (typeof address !== 'string' || !/^0x[0-9a-fA-F]{40}$/.test(address)) return false;
  return address === toEip55(Buffer.from(address.slice(2).toLowerCase(), 'hex'));
}

/** Derivación BIP-44 de referencia (externa al sistema) sobre `m/44'/60'/0'/0/{i}`. */
function referenceDerivation(mnemonic: string, addressIndex: number, passphrase = '') {
  assert.ok(validateMnemonic(mnemonic, ENGLISH_WORDLIST), 'el mnemonic de referencia es BIP-39');
  const seed = mnemonicToSeedSync(mnemonic, passphrase);
  const child = HDKey.fromMasterSeed(seed).derive(`m/44'/60'/0'/0/${addressIndex}`);
  assert.ok(child.privateKey, 'la referencia derivó una clave privada');
  const uncompressed = secp256k1.getPublicKey(child.privateKey, false).slice(1); // X || Y
  return {
    address: toEip55(keccak_256(uncompressed).slice(12)),
    privateKeyHex: bytesToHex(child.privateKey),
    seedHex: bytesToHex(seed),
  };
}

function referenceAddress(mnemonic: string, addressIndex: number): string {
  return referenceDerivation(mnemonic, addressIndex).address;
}

interface AddressRow {
  accountId: string;
  addressIndex: number;
  address: string;
  derivationPath: string;
  network: string;
  chainId: string;
  createdAt: string;
}

function addressRows(db: Db): AddressRow[] {
  return db
    .prepare(
      `SELECT account_id AS accountId, address_index AS addressIndex, address,
              derivation_path AS derivationPath, network, chain_id AS chainId,
              created_at AS createdAt
       FROM deposit_addresses ORDER BY address_index ASC`,
    )
    .all() as unknown as AddressRow[];
}

function seedBlob(db: Db): Buffer {
  const row = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as unknown as
    | { payload: Uint8Array }
    | undefined;
  assert.ok(row, 'hay un seed persistido');
  return Buffer.from(row.payload);
}

function seedRowCount(db: Db): number {
  const row = db.prepare('SELECT COUNT(*) AS n FROM wallet_seed').get() as unknown as { n: number };
  return Number(row.n);
}

function envFor(dbPath: string, keyHex: string, extra: Record<string, string> = {}): NodeJS.ProcessEnv {
  return {
    LOAD_DOTENV: 'false',
    WALLET_ENCRYPTION_KEY: keyHex,
    DATABASE_PATH: dbPath,
    LOG_LEVEL: 'silent',
    ...extra,
  } as NodeJS.ProcessEnv;
}

/** Directorio temporal propio (para los tests que manipulan la base a bajo nivel). */
function makeTempDb(): { dir: string; dbPath: string; keyHex: string; key: Buffer } {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cex-e06-'));
  const key = randomBytes(32);
  return { dir, dbPath: path.join(dir, 'exchange.db'), keyHex: key.toString('hex'), key };
}

function rmDir(dbPath: string): void {
  fs.rmSync(path.dirname(dbPath), { recursive: true, force: true });
}

function encodedSeedPayload(mnemonic: string, key: Buffer, passphrase = ''): Buffer {
  return encryptPayload(Buffer.from(JSON.stringify({ v: 1, mnemonic, passphrase }), 'utf8'), key);
}

/** Todas las claves (recursivas) de un objeto JSON. */
function collectKeys(value: unknown, out: string[] = []): string[] {
  if (Array.isArray(value)) {
    for (const item of value) collectKeys(item, out);
  } else if (value !== null && typeof value === 'object') {
    for (const [key, inner] of Object.entries(value as Record<string, unknown>)) {
      out.push(key);
      collectKeys(inner, out);
    }
  }
  return out;
}

