/**
 * Tests de REGRESIÓN de la revisión externa.
 *
 * Cada bloque fija una corrección concreta y cita la RN/AT de la spec que la exige. Son
 * casos que las suites de aceptación existentes no ejercitaban:
 *
 *  1. Rate limiting como **paso 0** de la precedencia, también cuando el cuerpo no parsea
 *     (HU-01-01 RN-9/RN-10 + AT-01-01-20; HU-01-02 RN-8/RN-9 + AT-01-02-09).
 *  2. Longitudes de contraseña y de email medidas en **caracteres** (code points) y no en
 *     unidades UTF-16 (HU-01-01 RN-2/RN-3; AT-01-01-05/12/13/14/15).
 *  3. Aborto del arranque con seed ya persistido y credencial **malformada**
 *     (HU-06-01 RN-6/RN-11, AT-06-01-11).
 *  4. `USDC_CONTRACT_ADDRESS` siempre emitido con checksum EIP-55
 *     (HU-09-01 RN-10, HU-06-04 RN-6).
 *  5. `address_index` fuera del rango no-hardened como error del catálogo
 *     (HU-06-02 RN-9, AT-06-02-09).
 *  6. Umbral y ventana obligatorios cuando el rate limiting opcional se activa
 *     (HU-01-01 RN-10, HU-01-02 RN-9) y defaults del límite de HU-09-02 RN-12.
 */

import test from 'node:test';
import assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { randomBytes } from 'node:crypto';

import {
  createTestApp,
  post,
  get,
  registerAccount,
  loginToken,
  uniqueEmail,
  VALID_PASSWORD,
  type TestApp,
} from './helpers/testApp';
import { ConfigError, loadConfig } from '../src/core/config';
import { bootstrap } from '../src/bootstrap';
import { openDatabase, type Db } from '../src/db/index';
import { AppError } from '../src/core/errors';
import { ProvisioningError, provisionWallet } from '../src/modules/wallet/seedStore';
import { deriveAccount, isValidChecksumAddress, toChecksumAddress } from '../src/wallet/hd';

const REGISTER_URL = '/api/v1/auth/register';
const LOGIN_URL = '/api/v1/auth/login';

// ---------------------------------------------------------------------------
// Utilidades del test
// ---------------------------------------------------------------------------

/** Envelope de error uniforme `{ error: { code, message, details? } }` (HU-09-05 RN-1). */
function assertErrorEnvelope(
  response: { statusCode: number; body: string },
  code: string,
  status: number,
) {
  assert.equal(response.statusCode, status, `status esperado ${status}, cuerpo: ${response.body}`);
  const body = JSON.parse(response.body) as {
    error: { code: string; message: string; details?: Record<string, unknown> };
  };
  assert.ok(body.error, `falta el envelope "error": ${response.body}`);
  assert.equal(body.error.code, code);
  assert.equal(typeof body.error.message, 'string');
  assert.ok(body.error.message.length > 0, 'el mensaje de error no puede ser vacío');
  assert.deepEqual(Object.keys(body).sort(), ['error']);
  return body.error;
}

/** `RATE_LIMITED` (429) con `details.retryAfterSeconds ≥ 0` entero y header `Retry-After`. */
function assertRateLimited(response: { statusCode: number; body: string; headers: Record<string, unknown> }) {
  const error = assertErrorEnvelope(response, 'RATE_LIMITED', 429);
  const retryAfter = (error.details as { retryAfterSeconds?: unknown } | undefined)
    ?.retryAfterSeconds;
  assert.equal(typeof retryAfter, 'number', 'details.retryAfterSeconds debe estar presente');
  assert.ok(Number.isInteger(retryAfter as number), 'retryAfterSeconds debe ser entero');
  assert.ok((retryAfter as number) >= 0, 'retryAfterSeconds debe ser ≥ 0');
  assert.equal(String(response.headers['retry-after']), String(retryAfter));
  return error;
}

/** Cuerpo crudo que NO es JSON válido (el parser falla). */
function postCuerpoRoto(ctx: TestApp, url: string) {
  return ctx.app.inject({
    method: 'POST',
    url,
    payload: '{oops',
    headers: { 'content-type': 'application/json' },
  });
}

/** Cuerpo con `Content-Type` no-JSON (el parser lo rechaza antes del esquema). */
function postContentTypeInvalido(ctx: TestApp, url: string) {
  return ctx.app.inject({
    method: 'POST',
    url,
    payload: 'email=a@b.com&password=Sup3rSecreta',
    headers: { 'content-type': 'text/plain' },
  });
}

function capturarError(fn: () => unknown): unknown {
  try {
    fn();
  } catch (err) {
    return err;
  }
  assert.fail('se esperaba una excepción y no se lanzó ninguna');
}

function seedBlob(db: Db): Buffer {
  const row = db.prepare('SELECT payload FROM wallet_seed WHERE id = 1').get() as unknown as
    | { payload: Uint8Array }
    | undefined;
  assert.ok(row, 'hay un seed persistido');
  return Buffer.from(row.payload);
}

function seedRowCount(db: Db): number {
  const row = db.prepare('SELECT COUNT(*) AS n FROM wallet_seed').get() as unknown as { n: number };
  return Number(row.n);
}

function makeTempDb(): { dbPath: string; keyHex: string } {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cex-reg-'));
  return { dbPath: path.join(dir, 'exchange.db'), keyHex: randomBytes(32).toString('hex') };
}

function rmDir(dbPath: string): void {
  fs.rmSync(path.dirname(dbPath), { recursive: true, force: true });
}

function envFor(dbPath: string, keyRaw?: string): NodeJS.ProcessEnv {
  return {
    LOAD_DOTENV: 'false',
    DATABASE_PATH: dbPath,
    LOG_LEVEL: 'silent',
    ...(keyRaw === undefined ? {} : { WALLET_ENCRYPTION_KEY: keyRaw }),
  } as NodeJS.ProcessEnv;
}

/** Credenciales de cifrado con formato inválido (no decodifican a 32 bytes). */
const CREDENCIALES_MALFORMADAS: { descripcion: string; valor: string }[] = [
  { descripcion: 'base64 basura', valor: 'notbase64!!!' },
  { descripcion: '16 bytes en hex (mitad de la longitud requerida)', valor: 'a'.repeat(32) },
  { descripcion: 'hex de longitud impar', valor: '0xabc' },
];

// ===========================================================================
// 1. Rate limiting como paso 0 de la precedencia, incluso con cuerpo que no parsea
//    (HU-01-01 RN-9/RN-10 + AT-01-01-20; HU-01-02 RN-8/RN-9 + AT-01-02-09)
// ===========================================================================

test('AT-01-01-20 (regresión): con el umbral de registro agotado, un cuerpo que no parsea responde RATE_LIMITED (429) y no VALIDATION_ERROR', async () => {
  const N = 2;
  const ctx = createTestApp({
    REGISTER_RATE_LIMIT_ENABLED: 'true',
    REGISTER_RATE_LIMIT_MAX: String(N),
    REGISTER_RATE_LIMIT_WINDOW_SECONDS: '60',
  });
  try {
    // Se agota el umbral N desde este origen (cada solicitud consume cuota en el paso 0,
    // aun cuando después falle la validación de esquema).
    for (let i = 0; i < N; i += 1) {
      const respuesta = await post(ctx.app, REGISTER_URL, {});
      assertErrorEnvelope(respuesta, 'VALIDATION_ERROR', 422);
    }

    // Solicitud N+1 con cuerpo que NO es JSON válido: el paso 0 es anterior a la
    // validación de esquema, así que gana RATE_LIMITED (RN-9/RN-10).
    assertRateLimited(await postCuerpoRoto(ctx, REGISTER_URL));

    // Ídem con un Content-Type no-JSON: el fallo del parser tampoco puede adelantarse
    // al paso 0.
    assertRateLimited(await postContentTypeInvalido(ctx, REGISTER_URL));

    // Y con un cuerpo válido, obviamente, también.
    assertRateLimited(await post(ctx.app, REGISTER_URL, { email: uniqueEmail(), password: VALID_PASSWORD }));

    // Ninguna de esas solicitudes creó cuentas.
    const row = ctx.db.prepare('SELECT COUNT(*) AS n FROM accounts').get() as { n: number };
    assert.equal(Number(row.n), 0);
  } finally {
    await ctx.cleanup();
  }
});

test('HU-01-01 RN-9 (regresión): sin rate limiting activo, un cuerpo que no parsea sigue dando VALIDATION_ERROR (422)', async () => {
  const ctx = createTestApp(); // rate limiting de registro desactivado por default (RN-10)
  try {
    const roto = assertErrorEnvelope(await postCuerpoRoto(ctx, REGISTER_URL), 'VALIDATION_ERROR', 422);
    const issuesRoto = (roto.details as { issues?: { field: string }[] } | undefined)?.issues;
    assert.ok(Array.isArray(issuesRoto) && issuesRoto.length > 0, 'VALIDATION_ERROR trae details.issues');

    const ct = assertErrorEnvelope(
      await postContentTypeInvalido(ctx, REGISTER_URL),
      'VALIDATION_ERROR',
      422,
    );
    const issuesCt = (ct.details as { issues?: { field: string }[] } | undefined)?.issues;
    assert.ok(Array.isArray(issuesCt) && issuesCt.length > 0, 'VALIDATION_ERROR trae details.issues');

    // El camino normal (registro válido) sigue funcionando.
    const cuenta = await registerAccount(ctx.app, uniqueEmail());
    assert.equal(cuenta.status, 'ACTIVE');
  } finally {
    await ctx.cleanup();
  }
});

test('AT-01-02-09 (regresión): agotado el umbral de login, un cuerpo que no parsea responde RATE_LIMITED (429) y no VALIDATION_ERROR', async () => {
  const N = 2;
  const ctx = createTestApp({
    LOGIN_RATE_LIMIT_ENABLED: 'true',
    LOGIN_RATE_LIMIT_MAX_FAILURES: String(N),
    LOGIN_RATE_LIMIT_WINDOW_SECONDS: '60',
  });
  try {
    const email = uniqueEmail();
    await registerAccount(ctx.app, email);

    // Exactamente N intentos fallidos hacia el mismo email desde el mismo origen.
    for (let i = 0; i < N; i += 1) {
      const respuesta = await post(ctx.app, LOGIN_URL, { email, password: 'IncorrectaXYZ' });
      assertErrorEnvelope(respuesta, 'INVALID_CREDENTIALS', 401);
    }

    // Intento N+1 con cuerpo que no parsea: no hay email con el cual armar la clave, pero
    // el paso 0 se evalúa igual con el origen como granularidad (RN-8/RN-9).
    assertRateLimited(await postCuerpoRoto(ctx, LOGIN_URL));
    assertRateLimited(await postContentTypeInvalido(ctx, LOGIN_URL));

    // Y el intento N+1 "normal" hacia el mismo email también, incluso con la contraseña
    // correcta (el paso 0 precede a la verificación de credenciales).
    assertRateLimited(await post(ctx.app, LOGIN_URL, { email, password: VALID_PASSWORD }));
  } finally {
    await ctx.cleanup();
  }
});

test('HU-01-02 RN-8 (regresión): sin rate limiting de login activo, un cuerpo que no parsea sigue dando VALIDATION_ERROR (422)', async () => {
  const ctx = createTestApp(); // rate limiting de login desactivado por default (RN-9)
  try {
    const email = uniqueEmail();
    await registerAccount(ctx.app, email);
    // Varios fallos: sin política activa no hay 429 posible.
    for (let i = 0; i < 3; i += 1) {
      assertErrorEnvelope(
        await post(ctx.app, LOGIN_URL, { email, password: 'IncorrectaXYZ' }),
        'INVALID_CREDENTIALS',
        401,
      );
    }
    assertErrorEnvelope(await postCuerpoRoto(ctx, LOGIN_URL), 'VALIDATION_ERROR', 422);
    assertErrorEnvelope(await postContentTypeInvalido(ctx, LOGIN_URL), 'VALIDATION_ERROR', 422);
    // El camino normal sigue funcionando.
    assert.ok((await loginToken(ctx.app, email)).length > 0);
  } finally {
    await ctx.cleanup();
  }
});

