test('AT-01-01-05/12/13 (regresión): la longitud de la contraseña se mide en caracteres, no en unidades UTF-16', async () => {
  const ctx = createTestApp();
  try {
    // 4 caracteres (8 unidades UTF-16): demasiado corta ⇒ 422 (RN-3, AT-01-01-05).
    const corta = '😀'.repeat(4);
    assert.equal([...corta].length, 4);
    assert.equal(corta.length, 8, 'el caso sólo tiene sentido si UTF-16 cuenta distinto');
    assertErrorEnvelope(
      await post(ctx.app, REGISTER_URL, { email: uniqueEmail(), password: corta }),
      'VALIDATION_ERROR',
      422,
    );

    // 8 caracteres exactos (16 unidades UTF-16): límite inferior VÁLIDO (AT-01-01-12).
    const emailMinimo = uniqueEmail();
    const minima = '😀'.repeat(8);
    assert.equal([...minima].length, 8);
    const alta = await post(ctx.app, REGISTER_URL, { email: emailMinimo, password: minima });
    assert.equal(alta.statusCode, 201, alta.body);
    assert.equal((alta.json() as { status: string }).status, 'ACTIVE');
    // Y esa misma contraseña autentica (el hash se calculó sobre el string completo).
    const login = await post(ctx.app, LOGIN_URL, { email: emailMinimo, password: minima });
    assert.equal(login.statusCode, 200, login.body);
    assert.equal((login.json() as { tokenType: string }).tokenType, 'Bearer');

    // 128 caracteres exactos (256 unidades UTF-16): límite superior VÁLIDO (AT-01-01-13).
    const maxima = '😀'.repeat(128);
    assert.equal([...maxima].length, 128);
    const altaMaxima = await post(ctx.app, REGISTER_URL, { email: uniqueEmail(), password: maxima });
    assert.equal(altaMaxima.statusCode, 201, altaMaxima.body);

    // 129 caracteres: excede el máximo ⇒ 422 (RN-3, AT-01-01-06).
    const excedida = '😀'.repeat(129);
    assert.equal([...excedida].length, 129);
    assertErrorEnvelope(
      await post(ctx.app, REGISTER_URL, { email: uniqueEmail(), password: excedida }),
      'VALIDATION_ERROR',
      422,
    );
  } finally {
    await ctx.cleanup();
  }
});

test('AT-01-01-14/15 (regresión): la longitud del email se mide en caracteres, no en unidades UTF-16', async () => {
  const ctx = createTestApp();
  try {
    const dominio = '@example.com'; // 12 caracteres
    // 254 caracteres EXACTOS con un carácter fuera del BMP en la parte local: VÁLIDO.
    const emailValido = `😀${'a'.repeat(241)}${dominio}`;
    assert.equal([...emailValido].length, 254, 'el borde se mide en code points');
