// 3. Aborto del arranque: seed persistido + credencial MALFORMADA
//    (HU-06-01 RN-6/RN-11, AT-06-01-11)
// ===========================================================================

test('AT-06-01-11 (regresión): con seed persistido, una credencial MALFORMADA aborta con INTERNAL_ERROR sin tocar el seed', async () => {
  const ctx = createTestApp();
  const dbPath = ctx.dbPath;
  try {
    await registerAccount(ctx.app, uniqueEmail());
    const blobOriginal = seedBlob(ctx.db);
    await ctx.close();

    const db = openDatabase(dbPath);
    try {
      for (const { descripcion, valor } of CREDENCIALES_MALFORMADAS) {
        // (a) Directamente sobre el provisioning.
        const error = capturarError(() => provisionWallet({ db, encryptionKeyRaw: valor }));
        assert.ok(error instanceof ProvisioningError, `se esperaba ProvisioningError (${descripcion})`);
        assert.equal(
          error.code,
          'INTERNAL_ERROR',
          `con un seed ya persistido el fallo es de descifrado, no de configuración (${descripcion})`,
        );
        assert.ok(!error.message.includes(valor), 'el error no repite la credencial recibida');

        // El seed no se regeneró ni se sobrescribió (RN-11).
        assert.equal(seedRowCount(db), 1, 'se persistió un seed adicional');
        assert.ok(seedBlob(db).equals(blobOriginal), 'el seed fue regenerado/sobrescrito');
      }
    } finally {
      db.close();
    }

    // (b) Mismo caso por la vía del arranque completo, como AT-06-01-11.
    for (const { descripcion, valor } of CREDENCIALES_MALFORMADAS) {
      const error = capturarError(() => bootstrap(loadConfig(envFor(dbPath, valor))));
      assert.ok(error instanceof ProvisioningError, `se esperaba ProvisioningError (${descripcion})`);
      assert.equal(error.code, 'INTERNAL_ERROR');
    }

    const post = openDatabase(dbPath);
    try {
      assert.equal(seedRowCount(post), 1);
      assert.ok(seedBlob(post).equals(blobOriginal), 'el arranque abortado modificó el seed');
    } finally {
      post.close();
    }
  } finally {
    rmDir(dbPath);
  }
});

test('HU-06-01 RN-6 (regresión): SIN seed persistido, una credencial malformada o ausente es VALIDATION_ERROR', () => {
  const { dbPath } = makeTempDb();
