// 4. `USDC_CONTRACT_ADDRESS` siempre con checksum EIP-55
//    (HU-09-01 RN-10, HU-06-04 RN-6)
// ===========================================================================

/** Dirección del USDC-mock usada en estos tests, en su forma con checksum EIP-55. */
const USDC_CHECKSUM = toChecksumAddress('0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238');

test('HU-09-01 RN-10 (regresión): `tokenAddress` se emite con checksum EIP-55 aunque el entorno lo declare en minúsculas', async () => {
  for (const forma of [USDC_CHECKSUM.toLowerCase(), `0x${USDC_CHECKSUM.slice(2).toUpperCase()}`]) {
    const ctx = createTestApp({ USDC_CONTRACT_ADDRESS: forma });
    try {
      // La configuración ya normaliza el valor que se emite (HU-06-04 RN-6).
      assert.equal(ctx.config.usdcContractAddress, USDC_CHECKSUM);

      const email = uniqueEmail();
      await registerAccount(ctx.app, email);
      const token = await loginToken(ctx.app, email);

      const respuesta = await get(ctx.app, '/api/v1/deposit-address?asset=USDC', token);
      assert.equal(respuesta.statusCode, 200, respuesta.body);
      const body = respuesta.json() as { tokenAddress: string; address: string };
      assert.equal(body.tokenAddress, USDC_CHECKSUM);
      assert.ok(
        isValidChecksumAddress(body.tokenAddress),
        `tokenAddress sin checksum EIP-55: ${body.tokenAddress}`,
      );
      assert.notEqual(body.tokenAddress, forma, 'se emitió la forma cruda del entorno');
      // La dirección de depósito también conserva su checksum.
      assert.ok(isValidChecksumAddress(body.address));
    } finally {
      await ctx.cleanup();
    }
  }
});

test('HU-06-04 RN-6 (regresión): `USDC_CONTRACT_ADDRESS` con checksum inválido o formato inválido impide el arranque', () => {
  // Caja mixta cuyo checksum EIP-55 NO verifica (típico error de tipeo).
  const cuerpo = [...USDC_CHECKSUM.slice(2)];
  const posicion = cuerpo.findIndex((c) => /[a-fA-F]/.test(c));
  cuerpo[posicion] =
    cuerpo[posicion] === cuerpo[posicion].toUpperCase()
      ? cuerpo[posicion].toLowerCase()
      : cuerpo[posicion].toUpperCase();
  const mixtaInvalida = `0x${cuerpo.join('')}`;
  assert.notEqual(mixtaInvalida, USDC_CHECKSUM);
  assert.ok(!isValidChecksumAddress(mixtaInvalida), 'el caso requiere un checksum que no verifique');

  assert.throws(
    () => loadConfig({ LOAD_DOTENV: 'false', USDC_CONTRACT_ADDRESS: mixtaInvalida }),
    ConfigError,
  );

  // Formato inválido: no son 40 hex con prefijo `0x`.
  for (const invalida of ['0x123', 'no-es-una-direccion', USDC_CHECKSUM.slice(2)]) {
    assert.throws(
      () => loadConfig({ LOAD_DOTENV: 'false', USDC_CONTRACT_ADDRESS: invalida }),
      ConfigError,
      `debía rechazarse: ${invalida}`,
    );
  }

  // La forma con checksum correcto, en cambio, arranca y se conserva tal cual.
  const config = loadConfig({ LOAD_DOTENV: 'false', USDC_CONTRACT_ADDRESS: USDC_CHECKSUM });
  assert.equal(config.usdcContractAddress, USDC_CHECKSUM);
});

