// 5. `address_index` fuera del rango no-hardened (HU-06-02 RN-9, AT-06-02-09)
// ===========================================================================

test('AT-06-02-09 (regresión): `address_index` fuera del rango no-hardened es un VALIDATION_ERROR del catálogo (422)', () => {
  const seed = Buffer.alloc(64, 7);
  const error = capturarError(() => deriveAccount(seed, 2147483648));

  assert.ok(
    error instanceof AppError,
    'el error de rango debe pertenecer al catálogo de errores (AppError)',
  );
  assert.equal(error.code, 'VALIDATION_ERROR');
  assert.equal(error.httpStatus, 422);
  const issues = (error.details as { issues?: { field: string; message: string }[] } | undefined)
    ?.issues;
  assert.ok(Array.isArray(issues) && issues.length > 0, 'debe traer details.issues');
  assert.ok(
    issues!.some((issue) => issue.field === 'address_index'),
    'details.issues debe indicar el parámetro address_index',
  );
  // El envelope de HU-09-05 se puede serializar directamente.
  assert.deepEqual(Object.keys(error.toEnvelope()), ['error']);
  assert.equal(error.toEnvelope().error.code, 'VALIDATION_ERROR');

  // Y el último índice no-hardened sigue siendo válido.
  const ultimo = deriveAccount(seed, 2147483647);
  assert.equal(ultimo.addressIndex, 2147483647);
  assert.equal(ultimo.derivationPath, "m/44'/60'/0'/0/2147483647");
});

test('HU-06-02 RN-9 (regresión): `AddressIndexRangeError` sigue existiendo y extiende `AppError`', async () => {
  const { AddressIndexRangeError } = await import('../src/wallet/hd');
