// 6. Parámetros obligatorios del rate limiting opcional (HU-01-01 RN-10, HU-01-02 RN-9)
//    vs. defaults fijados por la spec para HU-09-02 RN-12.
// ===========================================================================

test('HU-01-01 RN-10 (regresión): activar el rate limiting de registro sin declarar umbral y ventana impide el arranque', () => {
  const base = { LOAD_DOTENV: 'false' } as NodeJS.ProcessEnv;

  // Activado sin ningún parámetro.
  assert.throws(
    () => loadConfig({ ...base, REGISTER_RATE_LIMIT_ENABLED: 'true' }),
    ConfigError,
  );
  // Activado con sólo el umbral.
  assert.throws(
    () => loadConfig({ ...base, REGISTER_RATE_LIMIT_ENABLED: 'true', REGISTER_RATE_LIMIT_MAX: '5' }),
    ConfigError,
  );
  // Activado con sólo la ventana.
  assert.throws(
    () =>
      loadConfig({
        ...base,
        REGISTER_RATE_LIMIT_ENABLED: 'true',
        REGISTER_RATE_LIMIT_WINDOW_SECONDS: '60',
      }),
    ConfigError,
  );

  // Con ambos declarados, arranca con los valores del entorno.
  const config = loadConfig({
    ...base,
    REGISTER_RATE_LIMIT_ENABLED: 'true',
    REGISTER_RATE_LIMIT_MAX: '5',
    REGISTER_RATE_LIMIT_WINDOW_SECONDS: '30',
  });
  assert.deepEqual(config.registerRateLimit, { enabled: true, max: 5, windowSeconds: 30 });

  // Desactivado (default RN-10): no hace falta declarar nada.
  assert.equal(loadConfig(base).registerRateLimit.enabled, false);
});

test('HU-01-02 RN-9 (regresión): activar el rate limiting de login sin declarar umbral y ventana impide el arranque', () => {
  const base = { LOAD_DOTENV: 'false' } as NodeJS.ProcessEnv;

  assert.throws(() => loadConfig({ ...base, LOGIN_RATE_LIMIT_ENABLED: 'true' }), ConfigError);
  assert.throws(
    () =>
      loadConfig({ ...base, LOGIN_RATE_LIMIT_ENABLED: 'true', LOGIN_RATE_LIMIT_MAX_FAILURES: '5' }),
    ConfigError,
  );
  assert.throws(
    () =>
      loadConfig({
        ...base,
        LOGIN_RATE_LIMIT_ENABLED: 'true',
        LOGIN_RATE_LIMIT_WINDOW_SECONDS: '60',
      }),
    ConfigError,
  );

  const config = loadConfig({
    ...base,
    LOGIN_RATE_LIMIT_ENABLED: 'true',
    LOGIN_RATE_LIMIT_MAX_FAILURES: '3',
    LOGIN_RATE_LIMIT_WINDOW_SECONDS: '45',
  });
  assert.deepEqual(config.loginRateLimit, { enabled: true, max: 3, windowSeconds: 45 });
  assert.equal(loadConfig(base).loginRateLimit.enabled, false);
});

test('HU-09-02 RN-12 (regresión): el límite por cuenta autenticada NO exige declarar sus parámetros (60 req / 60 s por default)', () => {
  const config = loadConfig({ LOAD_DOTENV: 'false' });
  assert.deepEqual(config.apiRateLimit, { enabled: true, max: 60, windowSeconds: 60 });

