 */

import test from 'node:test';
import assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { randomBytes } from 'node:crypto';

import {
  createTestApp,
  post,
  get,
  registerAccount,
  loginToken,
  uniqueEmail,
  VALID_PASSWORD,
  type TestApp,
} from './helpers/testApp';
import { ConfigError, loadConfig } from '../src/core/config';
import { bootstrap } from '../src/bootstrap';
import { openDatabase, type Db } from '../src/db/index';
import { AppError } from '../src/core/errors';
import { ProvisioningError, provisionWallet } from '../src/modules/wallet/seedStore';
import {
  AddressIndexRangeError,
  deriveAccount,
  isValidChecksumAddress,
  toChecksumAddress,
} from '../src/wallet/hd';

const REGISTER_URL = '/api/v1/auth/register';
const LOGIN_URL = '/api/v1/auth/login';

// ---------------------------------------------------------------------------
// Utilidades del test
// ---------------------------------------------------------------------------

/** Envelope de error uniforme `{ error: { code, message, details? } }` (HU-09-05 RN-1). */
function assertErrorEnvelope(
  response: { statusCode: number; body: string },
  code: string,
  status: number,
) {
  assert.equal(response.statusCode, status, `status esperado ${status}, cuerpo: ${response.body}`);
  const body = JSON.parse(response.body) as {
    error: { code: string; message: string; details?: Record<string, unknown> };
  };
  assert.ok(body.error, `falta el envelope "error": ${response.body}`);
  assert.equal(body.error.code, code);
  assert.equal(typeof body.error.message, 'string');
  assert.ok(body.error.message.length > 0, 'el mensaje de error no puede ser vacío');
  assert.deepEqual(Object.keys(body).sort(), ['error']);
  return body.error;
}

/** `RATE_LIMITED` (429) con `details.retryAfterSeconds ≥ 0` entero y header `Retry-After`. */
function assertRateLimited(response: { statusCode: number; body: string; headers: Record<string, unknown> }) {
  const error = assertErrorEnvelope(response, 'RATE_LIMITED', 429);
  const retryAfter = (error.details as { retryAfterSeconds?: unknown } | undefined)
    ?.retryAfterSeconds;
  assert.equal(typeof retryAfter, 'number', 'details.retryAfterSeconds debe estar presente');
  assert.ok(Number.isInteger(retryAfter as number), 'retryAfterSeconds debe ser entero');
  assert.ok((retryAfter as number) >= 0, 'retryAfterSeconds debe ser ≥ 0');
  assert.equal(String(response.headers['retry-after']), String(retryAfter));
  return error;
}

/** Cuerpo crudo que NO es JSON válido (el parser falla). */
function postCuerpoRoto(ctx: TestApp, url: string) {
  return ctx.app.inject({
    method: 'POST',
    url,
    payload: '{oops',
    headers: { 'content-type': 'application/json' },
  });
}

/** Cuerpo con `Content-Type` no-JSON (el parser lo rechaza antes del esquema). */
function postContentTypeInvalido(ctx: TestApp, url: string) {
  return ctx.app.inject({
    method: 'POST',
    url,
    payload: 'email=a@b.com&password=Sup3rSecreta',
    headers: { 'content-type': 'text/plain' },
  });
