// ---------------------------------------------------------------------------
// 7. La autenticación sigue siendo anterior al esquema en los recursos protegidos
//    (HU-09-02 RN-9, AT-09-05-04). El diferimiento del error de parseo del cuerpo no
//    puede invertir esa precedencia.
// ---------------------------------------------------------------------------

test('AT-09-05-04 (regresión): un cuerpo que no parsea SIN token responde UNAUTHENTICATED (401), no VALIDATION_ERROR', async () => {
  const ctx = createTestApp();
  try {
    const sinToken = await ctx.app.inject({
      method: 'GET',
      url: '/api/v1/deposit-address?asset=ETH',
      payload: '{oops',
      headers: { 'content-type': 'application/json' },
    });
    assertErrorEnvelope(sinToken, 'UNAUTHENTICATED', 401);

    // Con token válido, el mismo cuerpo inválido sí se reporta como VALIDATION_ERROR.
    const email = uniqueEmail();
    await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);
    const conToken = await ctx.app.inject({
      method: 'GET',
      url: '/api/v1/deposit-address?asset=ETH',
      payload: '{oops',
      headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` },
    });
    assertErrorEnvelope(conToken, 'VALIDATION_ERROR', 422);
  } finally {
    await ctx.cleanup();
  }
});
EOF
